window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_046"]={"n":"严嵩","dyn":"明","poems":[{"t":"山塘","f":"五言古诗","c":["山塘深且广，逦迤抱山麓。","隔浦见人家，依依桑柘绿。","日落烟水寒，绕塘飞属玉。"]},{"t":"仰天冈","f":"五言古诗","c":["石磴盘秋萝，危亭出峰树。","行人上山道，望望云飞处。","洞口晚钟声，林僧独归去。"]},{"t":"东堂新成 其一","f":"七言律诗","c":["种树乘阴辟沼渔，数椽聊此卜幽居。","诸峰稍识岚霏外，三径新锄灌莽馀。","穷巷颇回高士辙，藜床时读古人书。","欲因萝薜辞簪弁，惭愧承恩在玉除。"]},{"t":"奉命视牲","f":"五言律诗","c":["观阙层城峻，郊宫复道开。","市烟当树合，炬火逐尘来。","牲帖牺人报，驺声骑士催。","夜归题笏记，候晓奏蓬莱。"]},{"t":"赐衣","f":"五言古诗","c":["宫衣锦段新，宣赐遍臣邻。","绣纹盘虎豹，金彩织麒麟。","诏向龙沙远，颁从玉陛均。","拜登齐阙谢，愧省独墙循。","士节论辞受，君恩爱笑颦。","礼看超等级，劳岂效涓尘。","荷德乾坤大，糜财府库贫。","先朝题岁月，诸道贡奇珍。","貂座仪章滥，鹈梁讽谕陈。","缙绅皆用武，辇辂尚留巡。","暗忆垂裳治，虚惭挟纩仁。","日占青海使，寒望翠华春。","未厌干戈役，私嗟章甫身。"]},{"t":"扬州","f":"五言律诗","c":["观忆琼花色，桥怜万柳阴。","芜城今夜月，怀古一悲吟。","胜迹那堪问，长江独至今。","波间饰龙舰，早晚翠华临。"]},{"t":"暮次灵川怀寄大参师舜宪副天益二乡丈 其一","f":"七言律诗","c":["天南岁晚更依依，朔雪寒云绕树飞。","投馆惊看风土异，临觞怅忆故人违。","情同漓水仍西注，身似春鸿向北归。","想见邮亭频驻马，独吟千嶂巳斜晖。"]},{"t":"全州岁夜","f":"五言律诗","c":["殊俗聊相值，空堂谁与同。","灯明深雪里，岁尽漏声中。","野暗孤城柝，庭高古树风。","频年远为客，此夕意何穷。"]},{"t":"萧子卜居梅林赋赠","f":"七言律诗","c":["溪上梅花玉作林，溪边茅屋苦寒侵。","孤山倚棹逢诗兴，颍上移家见客心。","日晚渔歌来浦溆，雪晴花色上衣襟。","风尘拥传劳为郡，时向沧洲寄一吟。"]},{"t":"寄寿少傅邃翁先生","f":"七言律诗","c":["圣朝望重经纶地，五亩情怡水竹间。","天下正须安石起，洛中犹放涑翁閒。","诗寻丁卯桥边宅，舟放金焦寺里山。","毬马烨如尊俎胜，隐园高会渺难攀。"]},{"t":"见用修赠张生诗和以寄之","f":"七言律诗","c":["文酒高怀强自宽，风烟异域若为欢。","哀歌漫引冯驩铗，感遇空弹贡禹冠。","梁月渐低回远梦，塞鸿初至得新翰。","春愁只恐销容鬓，莫向天涯重倚栏。"]},{"t":"早入承天门见鸦次韵","f":"七言律诗","c":["喧鸦争入帝城飞，映雾翻林飏曙晖。","宫女乍闻惊梦起，省郎纷逐散朝归。","声传万井含钟杳，影落千门带月稀。","还向昭阳自来去，绿窗凝望重依依。"]},{"t":"无逸殿直舍和少师相公韵 其二","f":"七言律诗","c":["灯烛通宵晃禁庐，雾窗云阁近宸居。","瑞烟入座香浮苑，寒影窥帘月到除。","缑岭乍闻丹凤吹，谷城先访赤松书。","归来未向人间说，天语亲承燕对馀。"]},{"t":"赠卢睿卿司业","f":"七言律诗","c":["南舟遥问秣陵程，北客初谙作宦情。","海近云霞连北固，宫深钟漏隐西清。","才名早已储三馆，形胜真堪赋两京。","自昔成均师道重，诸生今喜得阳城。"]},{"t":"赐太液乘舟","f":"七言绝句","c":["兰舟演漾水云空，花叶田田岛屿风。","棹入琼波最深处，玉楼金殿影西东。"]},{"t":"圣驾幸承天发京作","f":"七言律诗","c":["禁城钟动启金扉，凤辇时巡出帝畿。","黄纸特颁都护敕，绯罗齐赐从臣衣。","祥云捧日浮丹仗，芳树和烟隐翠微。","遥想江湘欢父老，汉皇今睹沛中归。"]},{"t":"雪霁登钤山","f":"五言古诗","c":["千峰积瑶素，寰宇映空明。","仙人好赤脚，独蹑层冰行。","叠石疑琼岛，高楼思玉京。","劲风仍振木，朗月已辉城。","永夜山中宿，山泉松涧鸣。"]},{"t":"登郡城南楼见仰山迟游侣","f":"五言律诗","c":["楼压春城迥，山连晓雾寒。","身高百林上，兴绕一峰端。","盘踞开雄镇，登临耸钜观。","所欢犹未至，惆怅凭栏干。"]},{"t":"览游大仰山宿东溪方丈二首 其一","f":"五言古诗","c":["夙驾踰城廓，决策戒行游。","良朋欣屡集，积潦况初收。","鸣鸟盈芳甸，嘉树蔽层丘。","览籍眷名迹，兹焉获所求。","披榛陟危磴，拂石漱寒流。","暝投东溪宿，密竹僧庐幽。","松岭露微月，苍苍烟露浮。"]},{"t":"览游大仰山宿东溪方丈二首 其二","f":"五言古诗","c":["城中望灵山，缥缈隔云雾。","沿回至山麓，山形始呈露。","大仰摩青穹，鸟道不可度。","邓仙与木平，隐若森拱护。","岚烟迷近远，明霭变朝暮。","伊余猿鹤姿，探赏惬幽愫。","岩峦纷合沓，一步屡回顾。","徘徊青莲宇，延伫古松路。","缘葛或褰崖，飞泉亦当户。","永念区中人，畴能息尘务。"]},{"t":"仰山置酒","f":"五言律诗","c":["春游入古寺，息驾在山阿。","不饮杯中物，其如山色何。","泉声间钟磬，草色上烟萝。","向夕岚霏起，诸峰猿啸多。"]},{"t":"大仰寺","f":"七言律诗","c":["珠林胜境隔人寰，古树高花隐石关。","流水声中一犬吠，白云深处数僧閒。","龙潭路黑烟常覆，螭首碑荒字已斑。","明日驱车入城去，却从尘里望山间。"]},{"t":"仰山寻郑谷书堂","f":"五言律诗","c":["遗墟那复辩，岩石但苍莽。","遐想嘉遁年，云霞结真想。","馀辉贲草木，秀句在穹壤。","泠泠韶濩音，千秋宁绝响。"]},{"t":"谒古庙二首 其一","f":"五言古诗","c":["缘回数里道，盘互百重山。","攀林兴不极，沿流趣自閒。","云度肩舆里，花明丛竹间。","神宫藏阒寂，龙井锁潺湲。","时见林中侣，相携采蕨还。"]},{"t":"谒古庙二首 其二","f":"五言律诗","c":["兹山饶灵异，古庙极巍崇。","下有千尺漂，深黑蟠蛟龙。","兴云雨暵岁，阖境歌神功。","神功既莫测，民祀当无穷。"]},{"t":"出仰山","f":"古风","c":["逶迤遵石磴，怅望别云松。","老僧不出户，斋阁自鸣钟。","钟声在山间，客子出山去。","细雨湿春衣，新寒入高树。","此中风景断尘凡，回看翠壑锁烟岚。","刘郎不记来时路，千树桃花隔水南。"]},{"t":"过长陂","f":"七言律诗","c":["长陂鸟鸣初日暄，游子度岭穷攀援。","行寻歇马访新庙，望近蟠龙识古村。","春深尚喜林花盛，雨后忽惊溪水浑。","野老相邀具鸡黍，解鞍时复过柴门。"]},{"t":"阻雨不得登蟠龙","f":"五言古诗","c":["溪上风雨来，飒飒篁竹乱。","油云翳层峰，对面隔霄汉。","鸟道纡百盘，龙门在天半。","佳期恨缅邈，寒望增凄断。","下马憩林居，一顾屡长叹。","自无飞仙术，安得凌绝观。"]},{"t":"途中晴","f":"五言律诗","c":["山游苦奔峭，会意乐有馀。","大仰寻真隐，蟠龙回我车。","湿云收绝壁，高柳媚清渠。","陂岸生新水，期来坐钓鱼。"]},{"t":"蒙山石门梁孟敬先生隐处","f":"五言律诗","c":["东蒙擅奇秀，万仞削苍壁。","阴崖閟浮云，旸谷曜初日。","遥思石门叟，长歌倚岩室。","岁远迹已陈，春草绿如积。"]},{"t":"泛舟","f":"五言律诗","c":["泛舟无俗情，水送复山迎。","江色迷朝霭，松阴转午晴。","稳依危石缆，深傍绿芜行。","吾已忘机事，沙鸥莫漫惊。"]},{"t":"钤阁对雨","f":"五言律诗","c":["白雾涌岩扉，回飙吹客衣。","万松鸣雨急，孤阁到人稀。","眺迥迷前浦，凭高失翠微。","惜春今已晚，虚负采山薇。"]},{"t":"钟山游眺","f":"七言律诗","c":["可怜春岸飞鸥鸟，又见春山长薜萝。","峰势插江溪路小，峡门横石水声多。","平沙觅句看云立，极浦回舟载酒过。","见说此溪多钓伴，月明来听扣舷歌。"]},{"t":"钤阁秋集","f":"七言律诗","c":["钤冈高楼足大观，况逢晴日倚栏干。","竹林啼鸟关幽事，石磴松风生昼寒。","病身自喜逢秋健，携手聊寻尽日欢。","万事浮生空役役，拟从山客借蒲团。"]},{"t":"登宜春喜","f":"七言律诗","c":["沙清江练绕城回，霜净花枝拂槛开。","山阁昼閒宜对酒，病身秋尽始登台。","潇湘木落闻猿啸，彭蠡云长见雁来。","郡僻渔樵堪卜隐，时危戎马转兴哀。"]},{"t":"东溪晴泛","f":"五言律诗","c":["钟峡出秀浦，碧潭无限清。","日浮江色动，舟蹴浪花轻。","盘石思垂钓，沧浪爱濯缨。","沿洄意未极，川暝月华明。"]},{"t":"江皋","f":"五言律诗","c":["岩溜漰渀雨，风松淅沥涛。","远峰晴木暗，清夏暑云高。","问节菖蒲近，观农稼穑劳。","微吟未归去，落日照江皋。"]},{"t":"郊行","f":"五言律诗","c":["沙路平如掌，郊行吟望赊。","山围四野碧，河抱一村斜。","松径入僧寺，草屋见渔家。","春风几日到，村园桃李花。"]},{"t":"洞灵观","f":"五言律诗","c":["玉女已仙去，仙丘尚此中。","龙吟山洞雨，鹤舞石坛风。","异代流传久，浮生梦觉同。","还寻炼丹处，云水夕阳空。"]},{"t":"东堂新成 其二","f":"七言律诗","c":["无端世路绕羊肠，偶以疏慵得自藏。","种竹旋添驯鹤径，买山聊起读书堂。","开窗古木萧萧籁，隐几寒花寂寂香。","莫笑野人生计少，濯缨随处有沧浪。"]},{"t":"赐告","f":"五言律诗","c":["春去复秋至，愁多与病连。","屏居臣分浅，赐告圣恩偏。","阙望长回首，岩栖不记年。","时闻起桴鼓，未暇枕书眠。"]},{"t":"晨起","f":"五言律诗","c":["枕畔闻啼鸟，觉来春思閒。","行药过石壁，倚槛望云山。","馆阁缪通籍，林园深闭关。","殷勤谢知旧，频遣惜朱颜。"]},{"t":"春日","f":"五言律诗","c":["春日宜春睡，梦醒时冁然。","处身无远略，忧世但长年。","池湿青莎雨，莺啼绿树烟。","近知理俗事，学种南山田。"]},{"t":"读易","f":"五言律诗","c":["径转频移柳，斋荒自补茅。","过从无俗客，迂僻少深交。","先雨鹳鸣垤，知风鹊构巢。","行藏吾已任，莫问易中爻。"]},{"t":"感述","f":"七言律诗","c":["结茅楚水枫林下，拥膝长吟任此身。","一官系籍逢多病，数口携家食旧贫。","溪圃秋深菊容淡，石田春暖药苗新。","时危献纳思无术，怅望中原伤战尘。"]},{"t":"有喜致醉","f":"七言律诗","c":["三十年过方有子，却论情事集悲欢。","总叨先德宜昌后，每为身愁欲废官。","琴书他日期堪付，堂构兹丘幸苟完。","庭中翠竹红葵色，乘醉邀宾秉烛看。"]},{"t":"春晓歌","f":"古风","c":["鸡喈喈，鼓逢逢，晨旸熹，春雾濛。","揽衣启户候晴色，山头云兴转深黑。","花潭柳屿空复期，蹑屩携壶难自得。","瓦沟急雨鸣彻宵，征人在途泥没腰。","忽忆此时京国侣，策马披毡趁早朝。"]},{"t":"夜宴歌","f":"楚辞体","c":["璚酒清。","蕙肴盈。","锦镫瑶席张四楹。","华歌妙舞百伎呈。","夜行游兮悦明星。","奉君玉觞前致诚。","上天垂休惠我明。","黄河之水今再澄。","天鸡鸣。","海乌升。","愿君举觞且留情。","乐哉时乎方太平。"]},{"t":"乙亥年雪","f":"古风","c":["燕京雪花大如手，寒冱江南未尝有。","近来江南雪亦如燕京，前年豫章东抵鄱湖冰。","路珉争传耳共骇，故老创见心犹惊。","今年大雪连三日，陌上深踰二三尺。","葭管春回气转寒，柴门暮扫朝仍积。","朝飞暮积无已时，四野浓云一色垂。","共道城中愁桂玉，虚从江畔觅花枝。","阴阳自古皆常度，物候今看却殊故。","瞽史何由讯咎徵，病夫默坐忧时事。"]},{"t":"霰","f":"五言律诗","c":["野霰朝仍集，山云冻不收。","家贫念藜藿，寒至想衣裘。","戎马多征檄，江波有钓舟。","短歌成独醉，聊得坐消忧。"]},{"t":"伐园中木","f":"五言古诗","c":["松柏储栋梁，枣栗充豆笾。","樗榆竟何益，历历蕃中园。","叶大苦蒙翳，材枉空挛蜷。","能令地脉耗，亦使阳和偏。","呼童砺斤斧，爨燎供炊烟。","去莠植嘉谷，斩茅秀兰荃。","栽培与倾覆，在理固宜然。","不材世所弃，剪伐何足怜。"]},{"t":"雨后南池","f":"五言古诗","c":["鸣雨夜不止，春波漫绿塘。","细浪摇孤屿，广岸映回墙。","乍宜添水槛，还能受野航。","蒲荷纷擢秀，槐柳俨成行。","虚疑泛瀛岛，深拟对濠梁。","临流兴不极，日暮歌沧浪。"]},{"t":"夏日閒居","f":"五言律诗","c":["卜筑远阛市，虚堂近高林。","池塘新雨过，夏木绿以阴。","初日照前牖，咿嘤语鸣禽。","听之颇怡悦，足慰静者心。"]},{"t":"对雨","f":"五言律诗","c":["暮霭起前壑，白雨映中林。","曲池通爽气，高馆足秋阴。","把帙引眠思，焚香清道心。","庭边有老树，萧瑟伴閒吟。"]},{"t":"秋夕閒居对雨","f":"五言古诗","c":["一雨洗炎嚣，高斋坐寂寥。","繁声傍竹近，寒色映空遥。","颇袭图书润，还沾枕席飘。","兴幽忘盥栉，巷僻谢招要。","兰晓光逾碧，荷秋叶互凋。","未须挥短箑，凉意晚萧萧。"]},{"t":"郊园","f":"五言律诗","c":["柴扉在深木，无人昼不关。","山围修竹罅，泉鸣乱石间。","倚杖玩苍翠，临风听潺湲。","一瓢挂高树，日暮灌花还。"]},{"t":"观雨作","f":"七言律诗","c":["东峰雨色绕前溪，野树江船望欲迷。","卷幔忽惊山雾入，近村长听水禽啼。","清怜松菊长茅屋，深爱湍流满稻畦。","故人门巷隔车辙，多病青尊不可携。"]},{"t":"斋中读书","f":"古风","c":["柳径柴门辟向东，竹垣高树引清风。","林中送客行常远，屋里看山兴不穷。","唯须药物供身病，且爱闾阎属岁丰。","世事浮云那足问，此生?老蠹鱼丛。"]},{"t":"望钤山","f":"七言律诗","c":["郭东草堂无俗嚣，画屏静对青岧峣。","暮灯隔树影明灭，霜钟吼空声振摇。","莲秀虚疑太华出，桂幽实爱小山招。","为贪鹤背思千里，拟接虹梯问九霄。"]},{"t":"观冯式窦禹钧事述咏 其一","f":"七言绝句","c":["还妾当年不计赀，一商阴德世难之。","状元已报神人送，邻里来谈梦兆奇。"]},{"t":"观冯式窦禹钧事述咏 其二","f":"七言绝句","c":["定数难移岂信然，但修人事可回天。","窦郎梦得先灵告，三纪延年五桂传。"]},{"t":"月夕黎君见寻","f":"七言律诗","c":["兰舟远汎故情欢，柳径相邀月色寒。","贫居市近能呼酒，懒性人逢不整冠。","黄花醉可簪乌帽，水槛閒宜弄钓竿。","不是同心念幽独，碧山那得共君看。"]},{"t":"中丞刘公卢洲宴集公子与予姻也","f":"五言律诗","c":["东郭筑堂好，中丞载酒来。","杯长烧烛坐，门正逐江开。","琼树欣相倚，霜威许见陪。","还知绿野醉，真胜习池回。"]},{"t":"江馆闻雨","f":"五言律诗","c":["江迥风连屋，庭喧雨到床。","寒声杂松竹，远势动潇湘。","幕燕翻应湿，林花落尽香。","问奇那有酒，春棹易相将。"]},{"t":"宿雁洲","f":"五言律诗","c":["山登极巑岏，野适忽夷旷。","清涧屡寒涉，绿畴弥晚望。","水亭荷芰开，园屋云松傍。","应怜雁洲宿，绝胜剡溪访。"]},{"t":"登高值雨留山舍","f":"五言律诗","c":["未遂观奇愿，来过静者居。","涉溪云逐马，下榻雨鸣除。","公子携松酝，乡人馈鲤鱼。","山寒春漏永，莫遣绿尊虚。"]},{"t":"集刘大别业","f":"五言律诗","c":["别业春山里，松筠开翠微。","文觞坐群客，此会昔应稀。","涧雨桐花湿，楼晴燕子飞。","主情殊未已，乘醉出荆扉。"]},{"t":"喜友人至","f":"七言律诗","c":["下马柴门日已曛，灯前悲喜话同群。","空江岁晚无来客，远道情深独见君。","瓦瓮细倾山郭酒，藜床閒卧石堂云。","莫言古调秪自爱，且诵新篇慰我闻。"]},{"t":"中秋陈大参分司同杨太仆宴","f":"五言绝句","c":["凉夕逢秋半，仙杯坐漏长。","未须延桂魄，卿月在薇堂。"]},{"t":"秋夕东堂同傅馆长兄宿","f":"七言绝句","c":["纸窗银烛雨声前，草屋寒栖共老仙。","不觉对床中夜语，青绫仍似玉堂年。"]},{"t":"钤阁同刘子集咏","f":"五言律诗","c":["树引肩舆入，山当对酒吟。","泉流一壑响，云度数峰阴。","兹地尘境绝，逢君坐语深。","谁言簪绂者，同有薜萝心。"]},{"t":"应和见寻","f":"五言律诗","c":["逶迟松桂林，之子能相寻。","远道惊长别，幽期感素心。","楚台临月迥，章水渡烟深。","何物酬佳兴，风窗弹玉琴。"]},{"t":"将赴京作","f":"七言律诗","c":["七看梅发楚江滨，多难空馀一病身。","阙下简书催物役，镜中癯貌愧冠绅。","非才岂合仍求仕，薄禄深悲不逮亲。","此日沧波理征棹，回瞻松柏自沾巾。"]},{"t":"将赴京登郡城春台作","f":"七言律诗","c":["浮生奔走遍尘埃，重对乡山病眼开。","北望几回仍赴阙，南还今日始登台。","袁江晴抱星辰下，燕雁寒冲雾雨来。","攀磴俯林坟极目，抽毫作赋叹非才。"]},{"t":"登春台贻钱别驾","f":"七言律诗","c":["府公地主催科剧，高阁看山引兴来。","三峡波涛深送酒，万峰岚翠迥登台。","黄花似与秋期约，尘世难逢笑口开。","遗德古来韩庙在，为寻荒碣斸苍苔。"]},{"t":"对雪赠客","f":"七言古诗","c":["江南素无此大雪，一夜覆地忽三尺。","平明走觅江上村，不辨东阡与西陌。","眼看世界入混茫，蔽野垂天同一色。","访旧虚回剡曲舟，闭门正卧袁安宅。","山中古树已开梅，瓮里新醪未泼醅。","秪应吟倚湖边棹，何用歌斟帐下杯。"]},{"t":"答符子","f":"七言绝句","c":["新题十幅寄钤冈，白雁西飞云路长。","因忆对床孤烛夜，一帘松月照山堂。"]},{"t":"仰山酬赠韩刘二子","f":"五言律诗","c":["迢递穷山里，君能枉见寻。","松门驻双骑，萝径鸣孤琴。","衣上云岚色，林中经梵音。","应悲市朝客，谁到白云深。"]},{"t":"赠西泉子","f":"五言律诗","c":["到君衡门下，修竹两三竿。","高已远人俗，贫能慰母欢。","邀予进草饭，夕语坐蒲团。","真与时相弃，泉巾独自冠。"]},{"t":"酬别刘梅国兄","f":"五言律诗","c":["故人千里别，何意到空林。","观榜曾随骥，遗诗比赠金。","青天寻蜀道，夜雪度山阴。","明发巴陵渚，烟波愁我心。"]},{"t":"夏日江亭赠客","f":"五言律诗","c":["江喧过雨时，绿树摇南飔。","归客乘流下，扁舟向我辞。","台临春望迥，山绕旅行迟。","无限蘼芜草，因君寄所思。"]},{"t":"奉答符少参先生见贺生男之什 其一","f":"五言律诗","c":["今旦启茅宇，把酒对花枝。","门见弧悬日，堂开履满时。","主人洗愁病，野客同襟期。","家事区区尔，能劳长者知。"]},{"t":"奉答符少参先生见贺生男之什 其二","f":"五言律诗","c":["剥啄惊敲户，缄题重越疆。","将雏新曲妙，遗鲤故情长。","儿子嗤豚犬，琼瑶借宠光。","夜阑还击节，转益病夫狂。"]},{"t":"奉酬空同先生垂访见贻","f":"七言律诗","c":["病来浑与故人疏，珍重能劳长者车。","地僻柴门堪系马，家贫蕉叶可供书。","莺花对酒三春暮，风雅闻音百代馀。","长愿饮河心自足，却惭和郢曲难如。"]},{"t":"钤阁赠傅侍御兄 其一","f":"七言律诗","c":["素琴远抱有馀情，草阁孤峰眼共明。","黄菊几逢词客病，绿尊今对故人清。","留君小作山中宿，念我虚题榜下名。","信有膏肓在泉石，十年从宦竟无成。"]},{"t":"钤阁赠傅侍御兄 其二","f":"七言律诗","c":["山游处处见山情，极目秋空万里明。","石磴屡缘心未倦，松亭小坐思尤清。","林中久负幽人约，壁上新题过客名。","自是登高能赋手，看君四韵已俱成。"]},{"t":"答友人","f":"五言古诗","c":["一官厕朝籍，出入承明墀。","十年卧林巷，恍若与时违。","当时同升侣，往往列金绯。","吾岂薄荣利，贫病恒相羁。","清晨阅明镜，了了见须眉。","自非食肉相，藏拙安所宜。"]},{"t":"次韵田水南兄见访","f":"七言律诗","c":["诸公天上多台省，此客江边秪草堂。","骑马看花空昨梦，把书牵犊笑年光。","兴高肯复维孤舫，身病仍□□十觞。","麋鹿故应耽野性，凤麟端合瑞文章。"]},{"t":"赠陈大参","f":"七言律诗","c":["江头画舫系残年，江上梅花明远天。","园林客到已摇落，溪谷鸟飞多变迁。","山村日落豺虎乱，邮渚云深鸿雁偏。","寄谢紫薇贤岳伯，折冲千里在尊前。"]},{"t":"鹤泉堂赠别","f":"楚辞体","c":["朝出兮江浒，送子兮延伫。","山泠泠兮多风，雾冥冥兮霏雨。","野?寂兮无人，子独归兮何所。","庭有鹤兮壑有泉，我欲与子兮期周旋。","目蹁跹兮耳潺湲，啸傲于此忘其年。","子不来兮心烦冤。"]},{"t":"送曹侍御归朝歌","f":"古风","c":["豫章城头班马鸣，六师夜洗章江兵。","江亭走饯盛冠盖，绣衣御史趋承明。","奉使三年劳遍历，临戎六月诧专征。","露剡才闻驰捷奏，天书遄及荷褒荣。","高堂老人今白首，门倚秋风知望久。","灵鹊朝喧舍北林，青骢晚系篱前柳。","橐中金币帝所锡，起舞称觞为亲寿。","君恩日共新，南山北阙庆千春。","愿将忠孝酬今代，□见功名胜古人。"]},{"t":"酬别张侍御","f":"七言律诗","c":["春风曾驻木兰舟，使节真看万里游。","揽辔霜威清瘴海，停杯诗兴满沧洲。","天寒江县城空闭，秋旱山田谷未收。","多病有怀谈莫尽，送君分首重淹留。"]},{"t":"送顾使君华玉赴全州","f":"七言绝句","c":["吴客孤帆楚水涯，碧云千里度长沙。","湘山独夜看明月，莫听猿声易忆家。"]},{"t":"赠相命颜生","f":"七言绝句","c":["扫榻云林白昼眠，行藏于我固悠然。","元无蔡泽轻肥念，不向唐生更问年。"]},{"t":"别友人","f":"七言绝句","c":["此夜孤灯共草堂，明朝双屐度潇湘。","亦知心迹无南北，未道相违是两乡。"]},{"t":"雪后钤山寄友","f":"七言律诗","c":["江上日日吹北风，茅屋拥被卧如弓。","楚乡物色是燕北，晴雪楼台似画中。","病骨总缘诗思瘦，屏居长与岁年穷。","毳裘貂帽忆京国，佩马朝天过苑东。"]},{"t":"寄陆太史","f":"七言律诗","c":["客舍燕台对雪眠，别来心迹两茫然。","青山有地淹贫病，白日无情换岁年。","驽马极知难附骥，玉堂真叹远瞻天。","新诗海内流传遍，凭寄枫林水石边。"]},{"t":"酬雁洲见寄 其一","f":"七言绝句","c":["南山有松松有萝，昔日结交今谓何。","但使同吟白云峤，何须独上金銮坡。"]},{"t":"酬雁洲见寄 其二","f":"七言绝句","c":["何处云山疋马归，暮云相望两依依。","凭君慰我尺素寄，日日江楼有雁飞。"]},{"t":"酬雁洲见寄 其三","f":"七言绝句","c":["北风吹雪满汀洲，欲折梅花不自由。","无限离情渺难寄，题诗更上一层楼。"]},{"t":"寄谢子","f":"五言律诗","c":["谢公江海士，铩羽在空林。","高卧不出户，閒堂春草深。","积霖注南国，驰波渺夕阴。","相望一水隔，方舟不可寻。"]},{"t":"思友人","f":"五言律诗","c":["衡岳无来雁，江漂有蛰龙。","愁边波浪阔，梦觉云山重。","定识相逢语，未知同病容。","因思遗远道，何处采芙蓉。"]},{"t":"江行寄朝望","f":"五言律诗","c":["挂席爱沧茫，江天足晚凉。","望移城塔远，歌入浦云长。","起鹤横烟屿，飞鸥趁野航。","劳君致美酒，篷里自衔觞。"]},{"t":"早春郊园寄友","f":"七言律诗","c":["东郊柳色远依依，忽忆佳人候竹扉。","剡曲雪深回夜棹，杜陵花发典春衣。","閒思步屧寻芳草，醉爱携壶上翠微。","不是赏心缘节物，频年离索故交稀。"]},{"t":"刘子久有登游衡岳之兴书来讯予京行答赠","f":"七言律诗","c":["端居心赏若为酬，瘦马螺川感昔游。","芒屐可能窥岳麓，青黎元自照林丘。","鸣声每听春山鸟，清兴空回雪夜舟。","若与故人论出处，閒身仍被白云留。"]},{"t":"钤阁登咏","f":"七言律诗","c":["石堂岩径薜萝封，钟磬遥闻最上峰。","云净芙蓉列远岫，天晴风雨起长松。","真仙定拟过笙凤，樵客何因识洞龙。","高阁我来忘几度，每来拄笏坐从容。"]},{"t":"黎侍御新亭 其一","f":"五言律诗","c":["曲径看花入，幽亭载酒开。","兴迥忘主客，地胜有池台。","晻暧树帷合，逶迤江练来。","已方元亮隐，松菊绕园栽。"]},{"t":"黎侍御新亭 其二","f":"五言律诗","c":["城居厌烦燠，来此洒尘纷。","江月夜深到，野禽松上闻。","径幽怜草色，谷密想兰薰。","百里沧波棹，佳期一访君。"]},{"t":"吴伟画","f":"七言古诗","c":["郭熙之死谁复同，湖湘小仙今代雄。","惯将健笔写缣素，江山平远称尤工。","洞庭潇湘渺何许，积水长天迷处所。","沙处老树总呼风，波上轻云初散雨。","短棹扁舟竞往还，垂纶者翁意愈閒。","晴窗展玩心眼乱，兴在沧洲千里间。"]},{"t":"山水画","f":"七言绝句","c":["长松拂云生昼寒，沙上草阁俯江湍。","幽人竟日少尘事，白鸟青天到倚阑。"]},{"t":"张氏林亭","f":"七言律诗","c":["十载重来笑语亲，水亭山阁几增新。","辋川自卜王维宅，锦里谁分杜老邻。","岁课园丁收芋栗，日招溪叟坐松筠。","却笑阮郎知此路，碧桃花里重迷津。"]},{"t":"观王阳明书石刻","f":"五言古诗","c":["作宰庐陵县，阳明称古风。","起废葺宫宇，节用恤瘝恫。","刻辞诏后来，庋石当庭中。","已叹仁言博，兼怜书迹工。","来游非在日，怀览意何穷。"]},{"t":"庐陵谒忠节祠","f":"七言律诗","c":["两间王气此诸公，万古香名祀一宫。","人代纲常元未坠，侯邦章典故应崇。","冠裳列宿辉光动，朝世沧桑运劫空。","二百里来瞻庙貌，不堪庭木起秋风。"]},{"t":"入白芒朱陂","f":"五言古诗","c":["岸岸溪流急，山山篁竹多。","盘回遵石径，迤逦度松坡。","深岭皆宜木，高田亦种禾。","唤鸠梅雨暗，飞燕麦天和。","池卜晴蛙语，村防夜虎过。","稍看民乐土，还苦吏催科。","世事关愉戚，生涯学醉歌。","清溪足鲂鲤，吾欲买渔蓑。"]},{"t":"苦竹山","f":"七言绝句","c":["苦竹山高昼景迟，木阴葱茜动南飔。","草间鸣雉忽飞起，傲兀篮舆度岭时。"]},{"t":"板陂铺","f":"七言绝句","c":["到处云山是旧逢，几家茅屋数株松。","邮亭下马午时饭，陇上辍耕谈老农。"]},{"t":"野泊","f":"七言绝句","c":["野外萧条灯火稀，空江孤艇暂相依。","年荒触目俱堪骇，隔岸燎原驱虎归。"]},{"t":"宿山寺","f":"五言律诗","c":["野寺入林辟，江城击柝重。","艰虞逢世事，愁寂任浮踪。","烦暑蚊喧壁，微明马度松。","踟蹰独不寐，兀坐听楼钟。"]},{"t":"昌峡","f":"五言律诗","c":["霁晓渡昌峡，苍山烟雾开。","中流万石斗，隔水一舟来。","祠古还依嶂，林幽忽放梅。","故乡知信美，临眺转徘徊。"]},{"t":"下浦","f":"五言律诗","c":["古市江船集，平桥野店开。","沙中辨远树，云里望层台。","兹郡饶奇胜，吾生叹去来。","明兴陟丹壑，秋日净浮埃。"]},{"t":"夜宿报恩寺","f":"七言律诗","c":["落日解装投上方，还寻老衲借绳床。","春寒自酌山城酒，夜静犹闻竹院香。","危坐万缘心境净，不眠孤枕漏声长。","因搜短句了清景，人事诘朝酬应忙。"]},{"t":"水南寺诸君子饯予京行即席赋","f":"七言律诗","c":["莎岸松门溪寺幽，日高烟雾隐林丘。","城居出郭应难数，旅适逢春可自由。","青嶂白云晴入座，落英飞絮远随舟。","谁能去国忘羁思，谩引离尊惜劝酬。"]},{"t":"墓到防里","f":"五言律诗","c":["林飙生暮寒，溪石渡清湍。","烟火高门近，风霜古木残。","升堂列酒馔，叙旧集悲欢。","爱此银灯烂，离颜惜共看。"]},{"t":"杨树岭","f":"五言古诗","c":["杨岭际晓来，肩舆度深寂。","崖高门巴薄，篁苇风淅淅。","清泠涉幽涧，荦硧缘绝壁。","环顾阒无人，山禽自啁唽。","新泥松树下，往往见虎迹。","行侣时唳呼，铜钲鸣未息。","缅予鸿雪踪，夷险备所历。","翻惭一身安，坐惜众夫力。"]},{"t":"早发雁洲途中作","f":"五言古诗","c":["螺川朅游访，雁洲复踌躇。","夜投林下宿，晓发霜中车。","回道过谷口，青枫寒正疏。","哀鸿唳广泽，猛虎临路衢。","所历多险艰，悰抱未可舒。","寄言同心似，何用独离居。"]},{"t":"促缩","f":"五言古诗","c":["促缩复促缩，暮投主人宿。","荒垣对空池，落叶响败屋。","拈杯当炊糜，爇薪代秉烛。","如闻旁舍言，野寇或宵伏。","世虑婴我怀，默坐候天旭。"]},{"t":"宿大栎同年陈玉夫宅玉夫时往江东","f":"五言律诗","c":["故人何所之，门馆闭芳池。","解名登共岁，多病别经时。","独买金陵棹，遥怜琼树枝。","山窗今夜月，空照客相思。"]},{"t":"至庐陵","f":"七言律诗","c":["青螺白鹭入我梦，河上松间骑马来。","问俗初经永叔里，吟诗真忆长卿才。","衣冠古郡高风在，车马寒城短日催。","今夜故人桑落酒，不知怀抱若为开。"]},{"t":"夕次藤桥还寄城中同好","f":"五言律诗","c":["惜别忘前路，暝色过藤桥。","问向谁家宿，村灯隔水遥。","弊裘风正急，客思酒初消。","谩听空堂雨，对床非昨宵。"]},{"t":"过周文襄公墓下 其一","f":"七言绝句","c":["尚书旧里说山前，松柏阴阴有墓田。","何止乡邦崇盛烈，吴人碑碣更林然。"]},{"t":"过周文襄公墓下 其二","f":"七言绝句","c":["南圻治赋阅星霜，功在朝廷未可忘。","中秘储才得公等，贻谋端合拜文皇。"]},{"t":"过刘子熏墓","f":"五言绝句","c":["欲赠徐君剑，挂向陇头枝。","陇水自东逝，我悲君不知。"]},{"t":"船发信州新雨江涨还寄曹使君 其一","f":"五言律诗","c":["乘溜放船去，空江迷雾云。","岸回青草色，波动白鸥群。","郡旱初闻雨，途穷忽见君。","应知三日祷，天为答忧勤。"]},{"t":"船发信州新雨江涨还寄曹使君 其二","f":"五言律诗","c":["已失玉溪雨，还望灵山云。","川阳夕明灭，岩树春氛氲。","狎藻凫相属，摩霄鹤不群。","鼓枻已宵逝，揽袂转思君。"]},{"t":"严陵祠","f":"五言律诗","c":["严陵七里滩，叠嶂俯澄湾。","云物澹堪赏，风标邈未攀。","龙飞初白水，鱼钓但春山。","千岁见孤庙，苍苍烟雾间。"]},{"t":"魏塘独宿寄陶员外良伯","f":"五言律诗","c":["泊舟魏塘渚，萧萧菰叶风。","剪烛红蕊乱，浮杯绿蚁空。","暝吟依雪鹭，遐想接烟鸿。","还将此时兴，书寄海云东。"]},{"t":"夜行吴江","f":"七言绝句","c":["官船新稳官河平，笼烛牵桅中夜行。","菰蒲野水不知处，明发说到阖闾城。"]},{"t":"如松江访陆太史先申寄赠","f":"五言古诗","c":["菰岸雨声急，松门烟浪深。","沿洄趣易惬，怀望思难任。","云物中夏赏，湖天孤屿吟。","暧暧沙中树，悠悠波上禽。","临溪听黄鸟，拂石理瑶琴。","总多山水兴，兼慰别离心。"]},{"t":"棠溪宴集赠使君","f":"五言古诗","c":["佳游历松郡，雅集过棠溪。","碧筱临池净，垂藤入径迷。","林香花代发，庭曙鸟先啼。","画省班赏接，沧洲影独栖。","行春人吏惬，听雨客怀悽。","野沃饶粳稻，时平撤鼓鼙。","文叨下客会，尊喜使君携。","稍学泉上钓，言留竹下题。","兴幽忘去棹，烟景在林西。"]},{"t":"丁使君泛舟宴饯","f":"七言律诗","c":["异乡逢子得同游，祖帐邀宾设饯留。","锦席移遵遥出浦，绿阴牵舸漫随流。","残花怅望迷幽屿，渌水逶迤接远洲。","为约别时须酩酊，前程莫遣有离忧。"]},{"t":"松江龙华寺留别 其一","f":"五言律诗","c":["野寺行送客，东津潮满时。","傍花吟驻棹，扫石坐传卮。","细雨晨钟湿，轻云午阁移。","欲别还留语，重来未有期。"]},{"t":"松江龙华寺留别 其二","f":"五言律诗","c":["石桥僧院古，松门人迹稀。","树凉风淅沥，江暝雨霏微。","夏木欣闻鸟，春山忆采薇。","应愧京游者，缁尘满素衣。"]},{"t":"金山","f":"五言律诗","c":["寺拥金山古，江流碧海深。","千年此形胜，词客几登临。","波浪浮香阁，鱼龙听梵音。","晨风渡舟楫，真有济川心。"]},{"t":"杨州别舍弟","f":"五言律诗","c":["作伴来吴越，那堪此地分。","还同广陵月，独向楚山云。","客路频加饭，文场早策勋。","要宽千里念，时遣尺书闻。"]},{"t":"晚次宝应湖阻雨忆舍弟","f":"七言律诗","c":["广陵舟里连衾枕，宝应湖边隔雨风。","人世百年谁骨肉，天涯此路复西东。","中宵忆尔心俱折，逆旅无人信莫通。","身迹半生成底事，秪馀泥雪叹飞鸿。"]},{"t":"清河阻风","f":"七言律诗","c":["淮浦清河三日住，北风高浪可怜生。","鱼龙远水深疑斗，星斗中天迥觉明。","永夜乡山频入梦，谁家船笛更飞声。","微名顾我堪惭叹，六月携家万里行。"]},{"t":"郊祀","f":"五言律诗","c":["天行驾凤虬，春祀重圆丘。","殿幄红云绕，坛松壁月流。","馨香荐明德，穰简集洪休。","万国观成事，宫筵庆玉旒。"]},{"t":"拜陵庙作","f":"五言律诗","c":["六帝神游迥，诸陵御气浓。","泉飞千尺瀑，枝偃万年松。","一自仙城闭，徒看云壑重。","遗弓小臣抱，怅望鼎湖龙。"]},{"t":"谒泰陵 其一","f":"五言律诗","c":["先朝趋禁陛，今日上陵台。","讵识龙骖远，犹疑宝扇回。","雨垂苍柏泪，风动碧山哀。","千岁岐周下，空传凤鸟来。"]},{"t":"谒泰陵 其二","f":"五言律诗","c":["季年深望治，帝德日光辉。","听揽收群策，忧勤总万机。","最伤凭玉几，那复见宵衣。","恸哭朝陵使，秋晨奠币归。"]},{"t":"谒泰陵 其三","f":"五言律诗","c":["问士晨颁策，焚香夜祝天。","恩同沧渤水，东去无回年。","衮舄红云里，园陵白露前。","神游念王室，龙驭傥来还。"]},{"t":"西陵观月","f":"五言律诗","c":["万古秋天月，西陵午夜看。","影流苍柏罅，光满碧云端。","节序逢摇落，山河对郁盘。","凭高瞻玉宇，正忆凤楼寒。"]},{"t":"下陵作","f":"五言律诗","c":["归骖怅何适，迟回陵路东。","还循白石径，遥下翠微宫。","冉冉开松雾，飘飘堕涧风。","今宵有佳兴，明月万山中。"]},{"t":"谒陵途次柬子渊太史","f":"五言律诗","c":["公我相携久，朝陵复此行。","暂违清禁直，重问碧山程。","听雨惊宵梦，看松惬野情。","喜随冠盖入，立马万峰晴。"]},{"t":"酬崦西侍读见赠上陵之作","f":"五言律诗","c":["时秋重祠事，吾喜得山行。","是日愁霖净，风烟破晓晴。","看云千嶂立，临水一诗成。","为诵琼瑶句，浑忘羁旅情。"]},{"t":"酬未斋宫谕见赠 其一","f":"七言律诗","c":["先皇陵殿枕秋风，下马来瞻夕照红。","流水犹疑响环佩，长松只讶拥虬龙。","雄关北踞通秦塞，叠嶂西驰绕汉宫。","欲写神功镌峄颂，绿崖苍壁倚天穹。"]},{"t":"酬未斋宫谕见赠 其二","f":"七言律诗","c":["柏林溪路转纡馀，怪石淩空不受驱。","帝作大邦劳眷顾，民于此地敢樵苏。","峰峦四合看屏障，水树千重入画图。","人世丹丘惊险绝，仙山蓬岛讶虚无。"]},{"t":"酬石门侍读见赠","f":"七言律诗","c":["翻屋秋霖作夜惊，出城晴旭称郊行。","谩于夷险思身事，却以忧欢见友情。","山月解装陵屋白，涧风骑马柏林清。","浮尘扰扰非吾意，临羡沧州愧濯缨。"]},{"t":"宿昌平刘谏议祠次韵赠蒲汀学士 其一","f":"七言律诗","c":["秋原六辔咏如丝，蓬阁金莲下直时。","贪看碧山频驻马，喜过琳宇谩题诗。","周田禾黍民歌岁，汉室园陵吏奉祠。","仙侣别离知不惯，玉堂明月定相思。"]},{"t":"宿昌平刘谏议祠次韵赠蒲汀学士 其二","f":"七言律诗","c":["高馆茶烟袅鬓丝，话阑清漏转多时。","尘埃偶下留徐榻，兰荰重吟吊屈诗。","浮世光阴悲逆旅，大邦名哲仰新祠。","叫阍莫上忧时策，倚槛遥兴万古思。"]},{"t":"正德戊寅正月七日驾自宣府回前期颁赐廷臣服色是日大雪百官迎德胜门外首臣奉觞致辞称贺即事纪述","f":"古风","c":["彪衣麟袍夹路来，飞鱼绣蟒皆新裁。","千官尽出都门道，万乘遥从朔野回。","瑞气晴浮丹凤阙，先声晓过白龙堆。","东风吹雪度城隈，流英落絮舞徘徊。","王春玉历三阳动，人日仙蓂七叶开。","列炬通城明似昼，腾车广陌沸成雷。","骑营下令罗霜仗，帐殿留欢捧御杯。","小臣献寿颂休哉，陛下神武英雄才。","龙庭驱丑虏，雁塞灭氛埃。","宁如汉天子，空上单宇台。","鸿名骏烈垂千祀，帝德皇风被九垓。"]},{"t":"回銮诗","f":"五言古诗","c":["长杨骑火红，汉帝夜还宫。","观兵誇出塞，献捷贺平戎。","旌竿飐飞雪，铙吹喧高空。","百琛陈阙下，八骏游寰中。","千岁升平乐，欢宴曲难终。"]},{"t":"徐氏北楼","f":"五言律诗","c":["徐君北檈上，今赋北楼诗。","旧赏客频异，狂歌酒莫辞。","帘开新月色，菊对晚霜枝。","胜地今皇国，休歌王粲词。"]},{"t":"雨 其一","f":"五言律诗","c":["暑雨新秋剧，茆庐湿不禁。","气蒸时见日，阴积转成霖。","云雾北山密，烟波南国深。","床头有浊酒，独酌散幽襟。"]},{"t":"雨 其二","f":"五言律诗","c":["日日浮云色，深疑失太阳。","叶深听更急，葵意仰何长。","邻屋垣颓共，泥涂马去妨。","庭间独鸣鹤，尔亦念高翔。"]},{"t":"登报国寺阁 其一","f":"七言绝句","c":["毗庐阁望尽京华，楼阁参差云雾遮。","雨雪高城催岁暮，音书故国渺天涯。"]},{"t":"登报国寺阁 其二","f":"七言绝句","c":["代北风烟迷处所，云间孤影见鸿飞。","闺中锦字空相忆，塞上金鞍仍未归。"]},{"t":"登报国寺阁 其三","f":"七言绝句","c":["后皇开山祗树林，直布大地皆黄金。","朱甍矗起云天丽，翠木环围石道阴。"]},{"t":"登报国寺阁 其四","f":"七言绝句","c":["南去北来何日了，劳劳千古更魂消。","才过报国松间寺，又度卢沟月下桥。"]},{"t":"冬闰和李宫谕","f":"五言律诗","c":["岁闰移阴律，寒深值晚冬。","市飙连九陌，楼雪俯千墉。","宫酝閒能醉，乡书病懒封。","虚惭殿门籍，寂寞卧高舂。"]},{"t":"除夕和石潭学士时车驾狩于榆林","f":"七言律诗","c":["更烧残烛坐虚筵，起视明星在远天。","客夜杯盘随俗举，城春花柳向谁妍。","愁心暗逐阶蓂老，芳讯频经陇月圆。","身事流年那可道，箕山终愧古人贤。"]},{"t":"元日用前韵","f":"七言律诗","c":["椒觞柏酒对春筵，楼雪宫云倚曙天。","后饮屠苏惊老大，骤看花蕊笑新妍。","青山近郭浮烟迥，碧树笼街淑景圆。","已见三阳开道泰，早闻连茹进才贤。"]},{"t":"送客","f":"七言律诗","c":["春来每日晴明少，送客城阴骑马迟。","返照沙边寒欲敛，行云江上晓频移。","谩劳药裹供愁病，且折花枝当别离。","故里交亲如问讯，石泉山月负幽期。"]},{"t":"符子冬暮发京南迈予日思之恨不能从也作此讯寄","f":"七言律诗","c":["北风日日河冰壮，愁病思君万里行。","江上归帆何日到，天涯旅梦几回成。","青春自改浮云色，幽谷虚传好鸟声。","逋客总贻猿鹤笑，故山空系薜萝情。"]},{"t":"再至都下子容侍读兄叙旧见贻用韵和酬","f":"七言律诗","c":["远别岂知仍聚首，相过不厌屡回车。","江湖句忆停云里，勋业心悲览镜馀。","海内故交谁在眼，病来癯貌独憎予。","摧颓敢附青霄翼，忝窃还登白玉除。"]},{"t":"少傅靳公归丹徒","f":"五言律诗","c":["黄阁丝纶贵，东山水石情。","留侯终谢病，疏传早辞荣。","江寺移舟近，城居种竹清。","挥金会邻曲，举酒话升平。"]},{"t":"赠董宫谕","f":"五言律诗","c":["扬帆别潞渚，鸣驺指越乡。","恩辉驰满路，颜色奉高堂。","赐锦裁春服，宫醪献寿觞。","五色文章贵，天池待凤凰。"]},{"t":"崔子谢病还邺怀寄","f":"五言律诗","c":["相送出郊寺，独归愁郭门。","春城涉远道，朝雨恋芳樽。","幽梦时或到，素心谁共论。","若为经济略，归卧水云村。"]},{"t":"赠刘使君之成都","f":"五言律诗","c":["尔向蚕丛去，荣分竹使符。","溯江泷石险，入邸鹤琴孤。","雪岭看松日，蓉城坐画图。","文翁有石室，千古在成都。"]},{"t":"赠汪尉","f":"五言律诗","c":["裘马去翩翩，人称县尉仙。","榜歌津柳外，官舍海云边。","鱼蟹环溪市，蒹葭入野田。","相送忆佳政，无为别兴牵。"]},{"t":"送进士陈则英归觐","f":"七言律诗","c":["长安阙下送离觞，才子宁亲赴北堂。","已喜登科同片玉，曾看作赋比长杨。","归帆夜度闽川月，舞袖春携汉殿香。","暂到故园非久别，云霄计日待鹓行。"]},{"t":"奉同温宫谕移疾寺居之作","f":"七言律诗","c":["九衢车马暗尘氛，仙客西堂卧白云。","静爱市朝堪吏隐，胜将泉石与僧分。","澄心夜对莲花水，秘曲朝披贝叶文。","独有可人期不至，素琴萝径立斜曛。"]},{"t":"伦编脩归娶例赠","f":"五言律诗","c":["捧诏辞东观，鸣楫下南川。","皆言归驷日，不羡弃繻年。","寒度梅花岭，春歌桃叶篇。","知君世良史，来续子长编。"]},{"t":"赠致政李尚书","f":"五言古诗","c":["时士皆求遇，明公屡乞身。","三朝均雨露，八座切星辰。","阙望辞明主，林归复几人。","青宫增秩重，绿野构堂新。","柳映悬车夕，花明放棹春。","今朝国门道，叹息望行尘。"]},{"t":"汤处士","f":"七言绝句","c":["此生已老蠹鱼间，犹抱遗经手自删。","他日襄阳访耆旧，庞公知在鹿门山。"]},{"t":"温宫谕省觐","f":"五言律诗","c":["巴道瞻云迥，燕关立马寒。","行辞青殿直，归奉綵衣欢。","宅傍花溪挣，杯沾菊露团。","宁当恋丘壑，遄拟接鹓鸾。"]},{"t":"送王提举","f":"五言律诗","c":["装车候明发，蓟城烟露寒。","壮心悲远别，苦节耐微官。","天地重溟尽，江山百粤盘。","携家赴蛮徼，南斗望长安。"]},{"t":"赠余太史副宪广东","f":"五言古诗","c":["含香旧仙吏，何事下蓬莱。","斧钺移南海，星辰别上台。","岭遥思马度，关晓见梅开。","五典敷文教，三长叹史才。","一去青冥鹤，芝田迟尔回。"]},{"t":"登慈仁寺阁饯杨殿撰","f":"五言律诗","c":["独鸟层云尽，惊鸦落木多。","登高堪一赋，送远柰愁何。","阛市空尘雾，僧房自薜萝。","临觞劝取醉，此地几经过。"]},{"t":"徐侍读别后寄赠 其一","f":"五言律诗","c":["行辀望已远，悠悠那复亲。","微霜映郊树，斜日暗京尘。","身病嗟行役，情真念吐申。","惟应梅驿使，频寄薜园春。"]},{"t":"徐侍读别后寄赠 其二","f":"五言律诗","c":["昔约去同载，君去我留仍。","宁知赤骥尾，不得附苍蝇。","对酒叹宵月，买棹怯寒冰。","忽枉河洲翰，离思渺然增。"]},{"t":"胡进士出宰东阳便省尊翁佥宪送赠","f":"五言律诗","c":["渡淮津吏识，客似弃繻还。","作宰铜章贵，宁亲綵袖班。","沙明严子濑，花暗婺州山。","应嗣霜台美，宁劳百里间。"]},{"t":"赠刘卿","f":"五言律诗","c":["春棹问南京，符台拜列卿。","波晴摇浦树，草绿上宫城。","胜得江山览，閒兼吏隐名。","风埃日驱马，攀望羡君行。"]},{"t":"张侍御谪判晋州 其一","f":"五言律诗","c":["旧日埋轮使，中朝仰姓名。","忽闻迁客诏，独问晋州程。","暮雨留看剑，长河对濯缨。","浮荣是何物，且慰病身轻。"]},{"t":"张侍御谪判晋州 其二","f":"五言律诗","c":["圣明恩意厚，谪官亦王畿。","莫下杨岐泪，旋看贾传归。","城临滹水静，树绕晋山微。","怅惜三春晚，风花几片飞。"]},{"t":"赠侍御乾德","f":"五言律诗","c":["西蜀观风使，春明别帝乡。","法星移益部，仙鵧下瞿塘。","晓驿催霜节，秋灯检皂囊。","潘舆况扶侍，桑梓有辉光。"]},{"t":"赠王克明进士之吉郡","f":"五言律诗","c":["豫章十三郡，庐陵实壮哉。","艺文今代盛，忠节古祠开。","山拥青螺出，洲分白鹭回。","投刃自兹去，人称理剧才。"]},{"t":"集寿僧房饯少司成汪先生之南京和席间韵 其一","f":"七言律诗","c":["野寺携尊访昔游，石堂风雨坐相留。","檐前老树身全湿，竹里深烟气暗浮。","多病此时须劝酒，异乡何处复登楼。","平生词赋关幽兴，无柰江篱绕去舟。"]},{"t":"集寿僧房饯少司成汪先生之南京和席间韵 其二","f":"七言律诗","c":["君去扁舟碧水阴，古兰幽杜蔼芳襟。","移榻野鸥陪宴坐，开尊江月照离心。","春莺自解迁乔木，海鹤谁应别故岑。","怅忆先朝供奉日，西清钟漏隔花深。"]},{"t":"赋少师杨公石斋","f":"五言古诗","c":["自昔爱此石，斋居因得名。","省身成砥砺，比德象坚贞。","色染云岚古，阴留竹柏清。","补天功已钜，障海力犹勍。","瑞拟川珍贡，高看国柱擎。","镌崖方纪颂，漱渚讵关情。","愿以如磐固，千秋奉圣明。"]},{"t":"题李学士画","f":"五言古诗","c":["杏阁依青嶂，萝轩俯绿畴。","路迷仙子宅，花暗羽人丘。","水讶伊瀍阔，山疑鄠杜幽。","傍崖交杂树，悬石下飞流。","谷晓催禽哢，郊晴唤客游。","谁言居玉署，长此对沧洲。"]},{"t":"瞻辰楼","f":"五言古诗","c":["高楼薄泰清，宴坐接仙庭。","风传丹禁漏，天拱紫微星。","楼下长安道，车马尘冥冥。"]},{"t":"待曙楼","f":"五言律诗","c":["闻钟起振衣，展席坐东扉。","松岩微月堕，花林芳露稀。","悟澹境方寂，遣俗虑应稀。","稍稍晨光集，众禽川上飞。"]},{"t":"题杨时明瀛州别业","f":"五言律诗","c":["别业踞仙洲，仙人洞壑幽。","岩回疑径断，林抱见溪流。","竹隐横琴坐，花随放棹游。","终期谢簪绂，扫石卧兹丘。"]},{"t":"听琴","f":"七言绝句","c":["閒客清宵抚玉琴，露凉新月在高林。","凭君洗净松风耳，无限人间郑卫音。"]},{"t":"渔父","f":"七言律诗","c":["沧洲渔父人不识，日暮移舟烟水寂。","沙头野饭暂维稍，蓬里天凉自吹笛。","笛声嘹喨度江门，荻花枫叶满秋村。","溪边云月长相待，世上功名安足论。"]},{"t":"李学士薇园秋霁图题赠","f":"古风","c":["玉堂仙人入直还，尽日閒园惟闭关。","展席平临阶下树，开帘遥对几前山。","紫微阴深日卓午，石榻微凉过鸣雨。","涧道声飞泉瀑寒，云根色飐莓苔古。","仙人步屧出幽林，长啸时闻鸾凤音。","手挥綵笔吟芳荰，目?飞鸿弹素琴。","琴书偃傲有馀清，竹窗今夜月华明。","谁言西掖丝纶贵，更有东山萝薜情。"]},{"t":"传制遇雨纪事 其一","f":"七言绝句","c":["三殿初开夜漏迟，从臣犹肃汉宫仪。","喧呼马仆灯沉陌，零乱鹓班雨满墀。"]},{"t":"传制遇雨纪事 其二","f":"七言绝句","c":["每岁宗藩当遣使，锦旄龙节载恩辉。","昨年册礼弥年举，圣驾新巡漠北归。"]},{"t":"传制遇雨纪事 其三","f":"七言绝句","c":["至尊新免太皇丧，传制分封举旧章。","周宗盘石千年固，汉使星轺满路光。"]},{"t":"传制遇雨纪事 其四","f":"七言绝句","c":["向夕鸣鞘下建章，平明飞鞚出长杨。","冠军常侍俱承宠，白马金鞍从武皇。"]},{"t":"秋使静江先忆钤山草堂","f":"七言律诗","c":["南济江湘去意赊，草堂秋色满烟霞。","还家偶值陶潜菊，奉使真随博望槎。","市近亲宾能载酒，径深旌节故穿花。","秪于泉石应堪老，未倦风尘空自嗟。"]},{"t":"夕次通州怀京邑僚友","f":"五言律诗","c":["萧条古台上，云日蔽秋阴。","已判同人袂，偏伤独客心。","坏窗微月度，高树早寒侵。","沉念待明发，东山萝薜深。"]},{"t":"天津","f":"五言律诗","c":["双流赴海奔，形胜此中存。","潮汐浮元气，金汤峙国门。","亭秋叶尽落，江曙景逾昏。","厌听城笳起，边愁入梦魂。"]},{"t":"雨夕作","f":"五言律诗","c":["秋气总成悲，那堪积雨时。","客衣新授褐，林叶故辞枝。","关塞书难问，风波鬓易丝。","停舟闻夕雁，渺渺向南驰。"]},{"t":"夹沟驿闻曹太仆舟过追候不及寄之","f":"七言绝句","c":["沛江秋水驿门深，斜日扁舟度柳林。","河汉易成千里隔，云山难寄万重心。"]},{"t":"过彭城","f":"五言律诗","c":["十月彭城水，临观势渺漫。","客帆牵树杪，日夕畏风湍。","汴泗流争长，鱼龙卧未安。","无人守茆屋，寂寞傍江干。"]},{"t":"吕梁题陈工部观物亭","f":"七言绝句","c":["风叶飘摇秋意深，古墙幽竹自成林。","闭门吏散焚香坐，谁识亭中静者心。"]},{"t":"高邮湖夜泛","f":"五言律诗","c":["四望渺无际，中流扬素波。","褰衣露华重，开帆月色多。","病骨成萧爽，秋光入荡摩。","汉槎天上客，历历近星河。"]},{"t":"西湖杭守置酒","f":"七言律诗","c":["朱幡翠幌在兰舟，绿水澄潭写我忧。","云破楼台明晓日，筵开箫鼓竞中流。","烟中檞径藏山寺，蘋际菱歌起钓洲。","古木苏堤频怅望，看君为政继前修。"]},{"t":"九日将至衢州寄杨使君 其一","f":"五言律诗","c":["节序信流迈，川途仍阻修。","那知逢九日，复此对孤舟。","村晚枫鸣叶，沙寒雁叫俦。","烂柯应在眼，未插菊花游。"]},{"t":"九日将至衢州寄杨使君 其二","f":"五言律诗","c":["青蕊那经眼，空尊解浣愁。","招寻从今节，欢宴阻良俦。","寂寂随寒雁，茫茫泛夕流。","繁香未衰歇，归赏故林秋。"]},{"t":"十日李使君郡斋宴","f":"五言律诗","c":["未对重阳菊，还逢地主杯。","风光宁自异，怀抱转须开。","户引清香入，山邀好月来。","严城看未锁，灯火逐江回。"]},{"t":"玉山馆吴仁夫太史","f":"五言律诗","c":["辞燕仍伏暑，度越已深秋。","并署欣今命，联舟感昔游。","节过黄菊雨，诗记玉山邮。","客路同知己，清尊合劝酬。"]},{"t":"奉题阁老费公至乐楼","f":"五言古诗","c":["衮绣辞天宠，岩峦选地偏。","横林水石处，曾忆钓游年。","旋马开新筑，焚鱼乐静便。","峰晴窗列障，松暝鹤栖烟。","意狎亲鱼鸟，神怡对简编。","褰帏川雾湿，摇笔径花燃。","白传香山社，欧公颍水田。","传家馀故业，经世赖高贤。","应有青藜使，来寻阁上仙。"]},{"t":"龙泽驿逢钱使君","f":"七言律诗","c":["袁山借寇何由得，鄱水逢君本未期。","为政风流应两郡，怀人云树总多时。","沧江暮雨维舟楫，古驿残花对酒卮。","知己难同嘉会少，孤帆欲别更迟迟。"]},{"t":"同徐郡侯登浚渠亭","f":"七言律诗","c":["徐侯亭子李侯渠，水石新呈宿莽馀。","秋净野田闻鹳语，云深仙洞隐龙居。","驱驰暂驻三湘节，登赋初陪五马车。","此日佳游习池共，他年故事岘山如。"]},{"t":"发宜春风雨枉诸公出饯别后怀寄 其一","f":"五言律诗","c":["出郭众峰暝，萧萧风树鸣。","岭危攀磴上，桥断涉溪行。","四牡勤王事，三湘问楚程。","郡斋山雾里，回望渺层城。"]},{"t":"发宜春风雨枉诸公出饯别后怀寄 其二","f":"五言律诗","c":["严程不可住，风雨且须行。","驿荷群公饯，山怜候吏迎。","乱峰连雾色，深树隐溪声。","夙有遐观志，因忘故土情。"]},{"t":"宣风馆","f":"七言绝句","c":["宣风馆前新雨晴，南北平分水陆程。","客心不柰寒溪水，一夜潺湲树里声。"]},{"t":"夕次宣风馆见壁间题韵辄次一首","f":"七言律诗","c":["下马疏林新月痕，隔篱呼酒问清浑。","江流萍实此乡路，祠隐濂溪河处村。","尘里征骖自来去，壁间题墨半明昏。","舟軓欲挂湘江水，兰杜难招楚客魂。"]},{"t":"卢溪谒周元公祠","f":"五言律诗","c":["古镇无监税，高贤有奉祠。","位卑名德重，世远士民思。","风月卢溪迥，衣冠宋代遗。","停骖肃瞻拜，敢惜去程迟。"]},{"t":"夕次醴陵","f":"五言律诗","c":["晨装去萍邑，夕驾憩长沙。","湖江通两镇，井里带千家。","枫岸霜鸣叶，卢洲月映花。","即看临桂水，还喜泛星槎。"]},{"t":"行经长沙江寄易太史","f":"七言律诗","c":["酌酒看花兴每浓，十年林卧阻游从。","常参玉署归难并，远使沧江去未逢。","世事总知荣木槿，愁心空惜老云松。","湘园门巷云阳麓，日对秋屏翠几重。"]},{"t":"渌口驿","f":"七言绝句","c":["炉寒夜坐湘山榻，雾重晨开渌口船。","宁知东观神仙侣，未了南邦道路缘。"]},{"t":"衡山舟中卧病","f":"七言古诗","c":["三日病思伏在床，药物到口不敢当。","蓬间坐失湘山翠，枕上但忆湘流长。","晓报昏霾江气恶，临蒸自昔叹殊方。"]},{"t":"谒南岳 其一","f":"七言绝句","c":["溅溅石濑交寒溜，瑟瑟松枝来远风。","村经独树柴荆外，路指千峰雾霭中。"]},{"t":"谒南岳 其二","f":"七言绝句","c":["三日斋心屏俗荤，清朝病眼洗衡云。","叮咛入谷停驺喝，恐惊此中猿鹤群。"]},{"t":"谒南岳 其三","f":"七言绝句","c":["万壑云岚浩荡开，千重泉溜泻萦回。","始怜奇僻非人境，尘迹何缘此度来。"]},{"t":"宿云开堂","f":"五言古诗","c":["寤寐名山游，兹夕山下宿。","虚馆绝浮埃，沉沉在幽谷。","曈昽星映除，飒爽风动木。","耳目澹无营，静嘿寡所欲。","院寂凝清香，更长续明烛。","惭无昌黎诚，晴晦安可卜。","明发戒仆夫，愿恣云霞瞩。"]},{"t":"宿云开堂闻提学常甫兄行部奄至亟遣书迓之","f":"五言古诗","c":["夜闻台端檄，欲驻湘中船。","良游匪夙约，兹会岂天缘。","狂思忽如酲，揽衣不得眠。","纸窗露微月，髣髴至我前。","红日出东方，晓山映澄鲜。","高吟振衣去，期子层云巅。"]},{"t":"登岳憩半山亭","f":"七言律诗","c":["孤亭翠岭上层云，烟霭微茫万里分。","仙家鸟道迥莫到，石壁猿声清忽闻。","幽泉树杪飞残滴，瑶草岩中吐异芬。","看拂丹霄朱鸟近，焚香先礼祝融君。"]},{"t":"经湘南寺","f":"七言绝句","c":["半岭遥闻深径钟，石堂萝薜护青松。","草堂邀客供僧茗，此是云中第几峰。"]},{"t":"下祝融宿南台寺","f":"五言律诗","c":["山殿隐苕荛，禅灯照寂寥。","乱峰临宿霭，古木认前朝。","桃水忽相失，浮丘还见招。","欲跨松岩鹤，吹笛溯丹霄。"]},{"t":"岳下逢常甫兄","f":"七言绝句","c":["白玉堂中鹓鹭群，十年江海叹离分。","岂意与君逢此地，乱山携酒看飞云。"]},{"t":"南台寺同常甫兄宿是夕闻钦之兄自攸县来会","f":"七言律诗","c":["香阁珠林倚半天，两人相对岳峰眠。","羌村秉烛翻疑梦，缑岭乘鸾似下仙。","云伴瘦筇过绝壁，风传清啸隔苍烟。","攸江亦有山阴兴，莫更虚回半夜船。"]},{"t":"岳下答常甫兄见赠","f":"七言律诗","c":["楚乡杯酒故情浓，犹似长安日过从。","知己百年怜几在，胜游今日叹难逢。","吟看夜棹溪边月，坐对寒流石上松。","昨暮祝融应悔别，回瞻云壑已重重。"]},{"t":"云霁堂逢钦之","f":"七言绝句","c":["远信初闻近复疑，西堂清怨独吟时。","须臾松径传银烛，颠倒风亭洗玉卮。"]},{"t":"常甫宪副钦之翰检与予先后登岳钦之独值雨是日予与常甫坐候云开堂因赋二章 其一","f":"五言古诗","c":["祠谒朝景晖，峰登云物变。","今朝山中客，零雨罢登践。","林深崖路窄，幽赏不可遍。","磴滑危难步，谷暗近莫辨。","兹山号灵幻，顷刻殊隐见。","叨余上晴峦，万状悉输献。","愧乏摛毫赋，琢句被崖藓。","君侯擅风骚，胸中富溪巘。","佳辞出天巧，不复劳洗鍊。","岩峦閟辉彩，草树迷葱茜。","岂被山灵妒，或遭造物谴。","并觏欣兹奇，独往惜巳殿。","期君嗣芒屐，言保箸力健。"]},{"t":"常甫宪副钦之翰检与予先后登岳钦之独值雨是日予与常甫坐候云开堂因赋二章 其二","f":"五言古诗","c":["晴登适可想，雨望奇莫云。","三子本同志，所历各不群。","浴溟初杲日，触石忽肤云。","连峰弥霮䨴，八垠渺氛氲。","掀林怒飙激，悬壑流泉奔。","暝色啼玄貁，虎豹夹路闻。","俯视临万仞，悄怆惊心魂。","平生几奇游，拟刻石上文。","虚馆迟回车，秉烛冀同论。"]},{"t":"往岁西泉子约予同游衡岳而予不果西泉子独游有诗见怀兹登上封因忆前韵和寄西泉子","f":"五言律诗","c":["幸了登山愿，惭输作赋能。","自惊疲病力，亦上最高层。","境迥知凡隔，神閒卜寿增。","西岩清夜月，应照客吟曾。"]},{"t":"方广寺宋晦庵南轩二先生所经衡守计使君期游","f":"七言律诗","c":["涉涧登岩费远寻，古松寒寺入榛荆。","昔贤对榻闻高咏，太守移尊非俗情。","幽兰谷里堪纫佩，渌水潭边可濯缨。","林暝杳然迷所适，上方台殿有钟声。"]},{"t":"宿方广寺读朱张二先生唱酬集","f":"五言古诗","c":["南岳众峰寺，寺寺期夤缘。","高穷上封览，静寄南台眠。","湘南与依空，琐琐不足传。","方广岳西麓，迹胜由名贤。","朱张两夫子，杖屦来当年。","高辞贲岩石，老宿依寒禅。","而我二三子，景行志弥坚。","跻攀越林涧，怅望迷云烟。","不见谷中人，但闻山下泉。","驰驱限于役，申旦輶车旋。","幽境夙所尚，尘累何当捐。"]},{"t":"经西明山","f":"五言律诗","c":["崖登渺奇兴，况喜故人同。","石路寒山里，溪流万木中。","幽花晴泫露，高树晚多风。","劳思何能洗，清尊幸不空。"]},{"t":"再游水帘洞","f":"七言律诗","c":["此是朱陵第二游，恍疑云水閟仙丘。","磴盘鸟道萝烟暝，潭隐龙宫雨气浮。","闻有高人眠醉石，拟将俗耳洗寒流。","摩崖细认题名字，苔色苍苍万古秋。"]},{"t":"胡文定公书院 其一","f":"七言绝句","c":["文定祠堂衡岳下，岳云祠榜映崔嵬。","千年弦诵馀岩宝，长遣山灵护绿苔。"]},{"t":"胡文定公书院 其二","f":"七言绝句","c":["精思妙契了残编，杖屦南山二十年。","铅椠未终还仕籍，风尘颜面愧高贤。"]},{"t":"南岳道士","f":"七言绝句","c":["焚香松下迎官长，捧爵炉前礼岳君。","青鞋不畏苍崖路，日日峰头行白云。"]},{"t":"观音岩僧","f":"七言绝句","c":["自云家世本湘川，来往名山断俗缘。","只借蒲团供宴坐，不管岩花易岁年。"]},{"t":"衡州","f":"五言律诗","c":["积水长天尽，深冬暮景催。","吾仍问南去，雁向此中回。","岳晚和云立，花寒对驿开。","侍臣清禁上，荒徼几时来。"]},{"t":"雁峰寺易太史计使君集","f":"七言律诗","c":["衡阳溆浦水烟通，落日来登回雁峰。","星轺玉节道路远，洞庭潇湘云雾重。","川长不见传书雁，寺古仍馀夹道松。","山园绿竹扶疏好，共惜佳人此地逢。"]},{"t":"花药寺","f":"五言律诗","c":["昨暮雁峰宴，今晨花药来。","似携馀兴往，更待好怀开。","楼阁盘幽嶂，香烟上古台。","楚地多奇胜，吾惭作赋才。"]},{"t":"衡州与易太史别","f":"五言古诗","c":["輶轩遵岭路，别棹倚川浔。","萧条风壤异，婉婉岁年侵。","畴昔怀同侣，兹乡逢所钦。","清芬袭嘉惠，逸响激瑶琴。","复感承明直，何如湘水吟。","茆斋攸江上，忆尔会相寻。"]},{"t":"长至祁阳县行礼时车驾北征","f":"七言律诗","c":["使节祁阳逢至日，县庭班列觐天光。","即看暖入深宫线，正想风飘合殿香。","塞马力应疲雨雪，江鸿书不到衡湘。","寒云落木催愁剧，魏阙沧洲引睇长。"]},{"t":"题潇湘楼","f":"五言绝句","c":["山色青瑶润，江光素练长。","误疑看图画，乃觉临潇湘。"]},{"t":"镇国山亭","f":"五言律诗","c":["朱甍开邸第，竹径得山家。","桂种瑶台树，莲开玉井花。","倾杯移渤澥，染翰动龙蛇。","疑有神仙过，鸾箫隔彩霞。"]},{"t":"永州城西朝阳岩踞湘水上景号奇绝太守何君携酒岩上","f":"七言绝句","c":["危石野亭云外赏，澄潭仙舸镜中回。","朝阳岩洞堪留客，湘水湘山对举杯。"]},{"t":"寻愚溪谒柳子庙","f":"七言律诗","c":["柳侯祠堂溪水上，溪树荒烟非昔时。","世远居民无冉姓，迹奇泉石空愚诗。","城春湘岸杂花木，洲晚渔歌清竹枝。","才子古来多谪宦，长沙犹痛贾生辞。"]},{"t":"见梅花","f":"七言绝句","c":["岁尽荆南霜霰稀，天晴山雾湿人衣。","马上朝来如见雪，因傍梅花过翠微。"]},{"t":"全州道中","f":"五言绝句","c":["梅花千树雪，松叶万溪云。","湘源行日日，赖尔洒尘氛。"]},{"t":"宿深溪馆","f":"七言律诗","c":["湘皋风物晚凄凄，候馆星轺日向西。","白屋扉临一水静，苍山路入万松迷。","寒冲毒雾沾衣润，暝坐幽篁飐雨低。","不见此中猿鹤侣，恐栖萝月在深溪。"]},{"t":"全州古松歌","f":"七言古诗","c":["全州古松大道边，白昼暝色行苍烟。","溪回路转不知数，直至兴安阴接连。","蛟龙拿空势欲舞，往往呼号作风雨。","大枝屈铁少枝盘，偃蹇突怒如相忤。","时复一株罗樵斧，槎牙无枝形独古。","谁栽此松经几祀，国初太守名犹记。","胜迹曾留学士题，繁阴长与行人憩。","松风冷冷山寂寥，松月皎皎明清霄。","遥想山中风月下，定有鹤仙吹玉箫。"]},{"t":"湘山寺唐无量寿佛示寂地 其一","f":"七言绝句","c":["湘山台殿翠微连，石塔禅身坐俨然。","祗树天移兜率境，金灯焰续会昌年。"]},{"t":"湘山寺唐无量寿佛示寂地 其二","f":"七言绝句","c":["云岚坐涌岩扉暝，薜荔行遮塔径斜。","两日炎州病如洗，湘山寺里见梅花。"]},{"t":"过盘石太守华玉赋诗处","f":"七言绝句","c":["盘石江山雨潇潇，行客双旌疋马遥。","醉起题诗临峭壁，令人却忆顾东桥。"]},{"t":"山枣驿夜坐","f":"七言律诗","c":["溯岭路岐仍渺渺，拍林风雨更朝朝。","清溪傍竹听萧瑟，小驿燃灯坐寂寥。","湘浦叶飞惊岁晚，钤山家在忆书遥。","垂垂一树梅花白，赖尔能将旅思消。"]},{"t":"兴安县 其一","f":"七言绝句","c":["兴安城郭枕高丘，湘漓水分南北流。","万里桥头风雪暮，不知何地望神州。"]},{"t":"兴安县 其二","f":"七言绝句","c":["破屋古松喧夕籁，远峰寒雾起层阴。","梅花两岸漓江水，岁晚相随到桂林。"]},{"t":"白竹铺","f":"七言律诗","c":["午饭车停白竹铺，寒旌马度黄茆冈。","江分二水湘漓外，路绕孤城雨雪傍。","峦洞云霞隐僻绝，野田松竹连青苍。","遥看溪嶂怜佳境，却畏风烟叹异乡。"]},{"t":"公安何公大古令睢宁有致雨灭蝗瑞麦三异政令子方伯君廷佩请予赋诗","f":"五言律诗","c":["中牟循吏绩，江陵长者言。","如闻何令事，不愧古人贤。","为政宁求异，躬行可格天。","棠留睢水上，碑照岘山前。"]},{"t":"两广大都宪杨公母夫人寿词杨太师文敏之孙也","f":"七言律诗","c":["中丞绣斧移南粤，寿母霞觞宴北堂。","贞史百年刊阃范，相门三世引书香。","祥晖映海扶桑近，春色临阶玉树长。","何止庭闱奉牲鼎，待看勋业在旂常。"]},{"t":"太府宴","f":"七言绝句","c":["峰攒锦石当轩秀，雾隐晴花拂槛高。","鼓角声中催送酒，松杉影里借挥毫。"]},{"t":"官署梅花一株盛开","f":"七言绝句","c":["只怪幽香生别院，不知春色在南枝。","绕树百回吟看汝，天南日暮酒醒时。"]},{"t":"题双松卷","f":"五言绝句","c":["庭中双松树，柯叶何青青。","岁晚岩居子，相期来斸苓。"]},{"t":"赋胡明府归乐堂","f":"七言绝句","c":["燕粤风埃万里馀，羊肠历尽始回车。","竹泉萝月皆幽事，桂岭星岩仍故庐。"]},{"t":"喻大行宗之静藩祭葬别赠","f":"五言律诗","c":["宗藩勤恤典，汉使下彤墀。","云捧青霄节，山开碧殿祠。","桂江题句胜，藤浦系舟迟。","闻有慈帏别，重歌四牡诗。"]},{"t":"晨观风洞登叠綵楼历拱辰亭亭为镇守傅中贵所创岩峦奇耸千里在目诸巡院有诗予辄次韵是日介行登赋不尽兴也 其一","f":"七言律诗","c":["孤亭绝嶂倚南天，碧树苍崖共莽然。","八桂云山供作赋，群公尊俎坐筹边。","严城鼓角传清曙，落日帆樯出断烟。","王事未能穷胜览，北风摇楫下湘川。"]},{"t":"晨观风洞登叠綵楼历拱辰亭亭为镇守傅中贵所创岩峦奇耸千里在目诸巡院有诗予辄次韵是日介行登赋不尽兴也 其二","f":"七言律诗","c":["苍茫寒雾起遥天，岁晏凭高思渺然。","夜发仙槎南斗外，春瞻御座綵云边。","湘源水色浮晴雪，桂岭花枝拂瘴烟。","莫怪题诗惜幽赏，子长奇兴在山川。"]},{"t":"题风洞","f":"五言律诗","c":["宁知岩洞古，平临阛阓中。","梵阁开丹鹫，仙梯蹑彩虹。","遥峰晴吐雾，阴磴静含风。","安能赋招隐，来扳幽桂丛。"]},{"t":"题虞山庙","f":"五言律诗","c":["重华千载后，遗庙在南夷。","弦想薰风奏，庭思凤鸟仪。","断碑苔藓合，幽洞薜萝垂。","髣髴移仙驾，乘云度九疑。"]},{"t":"虞山宴别 其一","f":"五言律诗","c":["山隐韶音洞，江横舜帝祠。","旌旄勤出饯，岩石借题诗。","客路春梅色，湘洲碧草辞。","都忘去程暮，留赏更传卮。"]},{"t":"虞山宴别 其二","f":"五言律诗","c":["赠言纷授简，祖席迥临城。","奉使怜遐域，群公荷别情。","漓波经地险，桂树向冬荣。","胜会知难再，相思一寄声。"]},{"t":"暮次灵川怀寄大参师舜宪副天益二乡丈 其二","f":"七言律诗","c":["他乡相见故人稀，听唱骊歌欲湿衣。","数酌犹临碧水坐，两舆空指暮林归。","池台月浸薇堂影，绣斧霜传桂岭威。","长路题书祝餐饭，壮图勋业莫相违。"]},{"t":"除夕全州少司徒梅轩蒋公邀集少傅敬所公之兄也致政宫傅张公泾川在座有诗次韵二首 其一","f":"七言律诗","c":["除日他乡倍忆家，聚星高会转宜誇。","能堪黄阁留宾席，正赖清尊遣岁华。","青蕙色淩阶下雪，玉梅香破腊前花。","烟霜旅棹催晨发，已报春风动水涯。"]},{"t":"除夕全州少司徒梅轩蒋公邀集少傅敬所公之兄也致政宫傅张公泾川在座有诗次韵二首 其二","f":"七言律诗","c":["台阁勋名重帝家，不因荣盛有矜誇。","那知守岁逢椒颂，却喜登堂咏棣华。","吟就谢池怜梦草，醉归唐苑忆看花。","履端更有明朝庆，皇泽春阳总未涯。"]},{"t":"元旦全州行庆礼","f":"五言律诗","c":["燎火通宵设，轩车拂曙来。","星随双节动，雪映百廛开。","圣寿齐嵩华，春阳遍草莱。","翠华天北极，应指塞垣回。"]},{"t":"元日燕宫傅泾川公第用韵 其一","f":"七言律诗","c":["午桥来访晋公家，重德高名岂浪誇。","开径竹松便逸隐，登堂山水占清华。","宜春总换桃符帖，趁俗先传彩胜花。","愿借柏觞增五福，直从沧海咏无涯。"]},{"t":"元日燕宫傅泾川公第用韵 其二","f":"七言律诗","c":["碧潭青嶂绕千家，风景真堪对客誇。","海内衣冠尊洛社，天南旌节驻皇华。","春从阴谷潜回律，雪应丰年密宱花。","他日胜游那可再，系帆重醉粤江涯。"]},{"t":"拜詶泾川公见赠","f":"七言律诗","c":["曾随玉署瞻先达，愧谒龙门已后时。","往事殷勤劳晤语，非才流落负心知。","湘山夜雨留觞久，漓浦春波放棹迟。","别后双鱼难定觅，但吟佳句一相思。"]},{"t":"发湘江","f":"七言律诗","c":["人日移舟湘水岸，东风吹浪散寒阴。","城边柏叶留春酌，沙际沧浪清客吟。","咽村小径通渔浦，石壁回溪映竹林。","时向舟人问佳境，前程几处费登临。"]},{"t":"石期驿逢李明府","f":"五言律诗","c":["清苦东安令，心期得共论。","官看铜绶贵，贫惜布袍温。","野树依峦嶂，春江对驿门。","天涯一携手，风雨送离尊。"]},{"t":"早霁与计使君泛湘江遂登望岳亭观武侯庙新成 其一","f":"五言律诗","c":["倚棹江天豁，移尊草阁幽。","到窗分岳翠，当槛泻烝流。","春至花经眼，秋深月满楼。","使君时对客，诗兴绕沧洲。"]},{"t":"早霁与计使君泛湘江遂登望岳亭观武侯庙新成 其二","f":"五言律诗","c":["川接烝湘会，城临栋宇开。","武侯今寂寞，公为扫莓苔。","世远怀龙卧，江春识雁回。","天涯山水郡，落日进馀杯。"]},{"t":"予少孤多病恒有忧生之嗟今年四十矣日月于迈禄不逮养学未有闻使经衡山适遘初度矢痛申情爰成兹咏焉 其一","f":"五言古诗","c":["婉娈为童子，父母不暂离。","出门十顾望，恒恐儿寒饥。","受气素薄弱，既长犹尪羸。","多疢贻亲忧，焉保黄发期。","庸知四十载，老大生须髭。","中朝玷荣禄，出使万里归。","公厨饭白粲，文锦褰华衣。","衣食岂不美，亲养弗可追。","初度临兹辰，怆恻有馀悲。","海波逝莫回，悲伤竟何为。"]},{"t":"予少孤多病恒有忧生之嗟今年四十矣日月于迈禄不逮养学未有闻使经衡山适遘初度矢痛申情爰成兹咏焉 其二","f":"五言古诗","c":["饬驾辞桂岭，弭棹越江湘。","我行几何时，巳涉万里疆。","万里岂漫游，王命肃所将。","咨询遍原隰，登眺穷崖冈。","闻昔太史公，足迹好瑰奇。","东游探禹穴，南浮踰九疑。","山川激壮气，一以昌文章。","赧予诚薄陋，怀古意慨慷。","男子始生朝，弧矢悬门堂。","眷言四方志，岂必怀故乡。","眷彼孤黄鹄，矫翮云天翔。","啾啾茅檐下，燕雀空榆枋。"]},{"t":"予少孤多病恒有忧生之嗟今年四十矣日月于迈禄不逮养学未有闻使经衡山适遘初度矢痛申情爰成兹咏焉 其三","f":"五言古诗","c":["弱龄不量力，高视慕前俦。","学道思理人，洗心念寡尤。","奄忽踰四龄，此志但悠悠。","聪明异前时，行业不加修。","抱册时呻吟，宁免遗忘忧。","雕虫技何补，食粟颜堪羞。","中夜起长叹，反躬时内省。","宣父戒无闻，漆雕惭未信。","勋业弗及时，白发忽生鬓。","嗟彼万里道，中途可旋轸。","愿言加餐饭，努力桑榆晚。"]},{"t":"归次醴陵","f":"五言律诗","c":["悠悠驻双骑，翼翼抗前旌。","云物媚清旦，山水映孤城。","平野楚烟碧，高峰松雪明。","客愁浑欲失，巳入故乡程。"]},{"t":"慧力寺","f":"五言律诗","c":["古道苍松转，重洲碧水连。","桥传伏马地，台忆读书年。","客舫平沙倚，禅灯夕嶂悬。","驰驱愧尘鞅，栖息叹何缘。"]},{"t":"移疾慧力方丈呈郡中诸君子 其一","f":"七言律诗","c":["城市谁能此地游，石堂禅榻借深幽。","藤萝月上诸峰静，楼阁风回古木秋。","病身偶似维摩室，客思应同王粲楼。","巳惜浮萍自流转，却扳丛桂更淹留。"]},{"t":"移疾慧力方丈呈郡中诸君子 其二","f":"七言律诗","c":["漫怀陶谢与同游，怅惜青山古寺幽。","江县羽书频报警，石门萝薜自宜秋。","孤城片月闻吹角，落日千峰对倚楼。","潇水驿亭舟楫地，异时尊俎记相留。"]},{"t":"不寐","f":"五言律诗","c":["羽檄连宵至，徵兵列郡闻。","乾坤遂戎马，云日更炎氛。","食禄宁辞难，临危好策勋。","灯残僧阁夜，孤枕百忧纷。"]},{"t":"夜至太平观 其一","f":"五言律诗","c":["暝色山径入，钟声林杪来。","道人惊客至，烛下松门开。","瑶席凝芳篆，琳馆绝浮埃。","尘襟藉消豁，天明车骑催。"]},{"t":"夜至太平观 其二","f":"五言律诗","c":["群仙朝上帝，高居俨太清。","玉池泉不涸，玄圃树长荣。","剑作苍龙跃，笙同彩凤鸣。","倘因值灵药，此地问长生。"]},{"t":"陈节推久在南昌寄赠","f":"七言绝句","c":["郡阁萧条昼掩扉，窗中林岫待玄晖。","东湖亦是桑乾水，应望袁山日忆归。"]},{"t":"赠陈侍御原习","f":"五言律诗","c":["木落岁年晚，空江忽到公。","世途千辙异，高论一尊同。","怀玉幽人志，缨冠国士风。","重溟隔南纪，瞻望渺行骢。"]},{"t":"郡内逢春","f":"七言律诗","c":["春日春台宜引望，万家城郭庆春新。","彩幡花胜巧随俗，柏叶梅枝清傍人。","离离雪树开晴旭，冉冉风烟度野津。","还沾郡邸宾筵醉，转觉乡园物候亲。"]},{"t":"卢洲宴集值雨赠罗使君","f":"七言律诗","c":["名园邀客绿尊开，红旆行春五马来。","江迥波声喧几席，山寒雾色隐楼台。","庭中翠荫延修竹，林下幽芳折老梅。","为报青阳布新令，满城甘雨使车回。"]},{"t":"过双龙寺","f":"五言律诗","c":["入谷岚霏重，开门松寺深。","滩流万木罅，萝拥众峰阴。","溪鹭仍寒浴，潭龙或夜吟。","楚地多风雨，春山不可寻。"]},{"t":"山行赠仁甫 其一","f":"五言绝句","c":["万峰云度壑，孤寺雨鸣溪。","马渡溪前水，疑怜锦障泥。"]},{"t":"山行赠仁甫 其二","f":"五言绝句","c":["共宿东窗中，下宵雷雨闻。","风尘迟双剑，好为拭龙文。"]},{"t":"寄仁甫","f":"五言律诗","c":["篁木翳深岭，独行千嶂间。","溪山正奇绝，霖潦倦跻攀。","闻子渡前壑，日暮临河还。","相思阻幽梦，一夜雨潺湲。"]},{"t":"题黄氏池亭","f":"五言律诗","c":["黄生池阁清，独宿怡我情。","高窗延雾色，曲涧绕泉声。","邻里閒能过，鸥鱼近不惊。","永学溪中钓，宁求世上名。"]},{"t":"雨望","f":"五言律诗","c":["高楼集飞雨，半入空濛间。","梅痕低映水，草阁暝依山。","境寂浑饶睡，杯深忽破颜。","五岭愁难望，烟中凝翠鬟。"]},{"t":"赠张秀才","f":"五言律诗","c":["吾爱张明府，承家不乏贤。","芳兰临谢砌，白璧照蓝田。","暮雪明书幌，春莺对别筵。","天池待鸣凤，綵翼看腾骞。"]},{"t":"春日游石乳洞 其一","f":"五言律诗","c":["跻险遘灵室，赏胜得仙溪。","紫泉飞作雨，玉髓积如泥。","暂驻心魂爽，重寻岩径迷。","拟结丹霞想，来从静者栖。"]},{"t":"春日游石乳洞 其二","f":"五言律诗","c":["地隐林峦秀，春馀草木芳。","古岩宜置酒，清溜忽沾裳。","有象名难具，无言趣转忘。","未云欢赏罢，歌吹送残阳。"]},{"t":"游洪阳洞","f":"七言律诗","c":["二仙何代隐岩阿，涧绿山青长薜萝。","尘世总经桑海变，丹丘长占水云多。","天台到拟逢桃实，石室归疑烂斧柯。","思向此中寻静侣，因牵俗累欲如何。"]},{"t":"彬江罗使君宴别","f":"五言律诗","c":["乳洞初旋盖，邮亭复此筵。","夜歌临浦月，春赏寄云泉。","宾从滁山醉，风流岘水传。","所嗟牵远役，安得重延缘。"]},{"t":"师俭堂","f":"七言绝句","c":["山泉野饭聊今夕，金谷铜驼非故时。","随缘自有数椽足，题俭真成一字师。"]},{"t":"双溪","f":"七言绝句","c":["宛似名山入武溪，花源仙艇记还迷。","春圃剪蔬逢客至，午窗丸药听莺啼。"]},{"t":"题龙封君颐贞卷","f":"五言律诗","c":["学道人未识，端居遗俗纷。","云龟导真息，玄豹养深文。","履坦自多吉，逃名世却闻。","当时读易处，幽室洒兰芬。"]},{"t":"萧氏凤山别业","f":"五言律诗","c":["卜筑傍幽深，烟霞费远寻。","窗喧石涧水，槛落翠峰阴。","巢鹊依新主，溪花发故林。","应招白云侣，终日伴閒吟。"]},{"t":"郡学罗守新肄乐请予观赋","f":"五言古诗","c":["朅闻金丝奏，洋洋黉舍中。","迹类观周庙，神疑游泽宫。","徵师来独远，享圣礼攸崇。","兹郡惭遐僻，居然邹鲁风。","伟哉贤守化，不羡蜀文翁。"]},{"t":"阅武亭置酒","f":"古风","c":["山拥宾筵翠，城围将垒高。","霜天清鼓角，云日丽旌旄。","箭迅穿鸿鹄，杯香擘蟹?。","取醉自兹别，临岐赠宝刀。"]},{"t":"晓登春台 其一","f":"五言律诗","c":["楼阁山寒里，肩舆冲晓来。","仲冬群木下，初日万峰开。","平野何寥邈，层城亦壮哉。","予心慕奇胜，欲别更登台。"]},{"t":"晓登春台 其二","f":"五言律诗","c":["山暝烟岚合，城高睥睨齐。","攀跻兴不极，旷望意还迷。","风壤荆吴际，星文翼轸西。","遗祠深木里，来客拜昌黎。"]},{"t":"和唐侍御晚登春台","f":"七言律诗","c":["春台夕上兴犹奇，落木苍苍白日迟。","行傍径梅诗自好，坐看松嶂榻频移。","江城揽辔霜威迥，山阁开尊月色宜。","莫为浮云望天际，恐增愁思倚阑时。"]},{"t":"晓登春台用韵","f":"七言律诗","c":["翠岭烟开楚望奇，绿江天尽鸟飞迟。","松彬覆郭泠风起，楼阁当空淑景移。","岩树故因时序改，山云岂与俗情宜。","双峰寂寂应相对，怅忆高人独往时。"]},{"t":"惠上人房","f":"五言律诗","c":["绝壑闻流水，香床住半天。","林间飞盖入，松下看云眠。","谷鸟知春候，昙花识静缘。","冥心遗所适，岂必定中禅。"]},{"t":"夏夜府公辱过","f":"五言律诗","c":["山月照庭际，如传松桂神。","到门银烛远，当席锦袍新。","自惜迂疏旧，多惭宠顾频。","荒居寡承奉，小酌愧情真。"]},{"t":"酬罗使君仰山之招","f":"七言绝句","c":["开缄见月生幽思，清晓雨声翻屋来。","千峰古木啼猿处，空忆题诗坐石苔。"]},{"t":"钤山夜别简侍御得宽字","f":"五言律诗","c":["柱史来天上，相过坐夜阑。","霜威清暂假，月色好同看。","晨渡河冰壮，春浮楚泽宽。","台臣纲纪地，送子见才难。"]},{"t":"阳春书院唐朱二侍御邀集","f":"七言律诗","c":["阳春院里花仍发，不饮其如春色何。","高台曲沼人能到，迟日浓烟景自多。","犹怜绿水飞鸿雁，更著兰舟采芰荷。","章郡升平异前日，时邀骢马一相过。"]},{"t":"薛楼宴集次汪户部希会是日出师捕安义之寇","f":"七言律诗","c":["城外章江碧草春，城头高阁绮筵新。","野航受客还依渡，江燕穿花不避人。","山川南国登临在，今古浮云感慨频。","战舸眼边连夜发，捷书早报放吾颦。"]},{"t":"夜登明远楼同王阳明中丞唐朱二察院","f":"五言律诗","c":["遥夜肃已静，朗月照重湖。","风窗倚天汉，星峤临蓬壶。","的的徐亭树，寥寥霜署乌。","微言欢欲奉，清赏未云徂。"]},{"t":"龟峰寺 其一","f":"五言律诗","c":["森森荫水柏，暝暝入山烟。","始惊灵境绝，忽步翠微先。","异状群峰出，幽探万虑捐。","心期驾鸾鹤，从此问真仙。"]},{"t":"龟峰寺 其二","f":"五言律诗","c":["鸟鸣芳树暗，云度碧峰阴。","春益林峦秀，山围洞壑深。","青莲窥色相，绿竹动讴吟。","人世那逢此，丹溪一一临。"]},{"t":"上巳玉山集 其一","f":"五言律诗","c":["岩嶂何盘郁，汀洲复渺绵。","江深迷草树，林霁净风烟。","兰叶修春禊，杨花对别筵。","不醉河阳酒，愁心益惋然。"]},{"t":"上巳玉山集 其二","f":"五言律诗","c":["怀玉今辰到，官亭憩晚晴。","连山雨渺渺，独树花盈盈。","对酒三春暮，离家一月程。","旧窗园木暗，惆怅忽闻莺。"]},{"t":"塔山望","f":"五言律诗","c":["初闻流泉响，渐入深林间。","灵峰窥宝塔，竹径款禅关。","晻暧花覆谷，空濛雨映山。","回看万壑里，云雾渺人寰。"]},{"t":"自西湖入灵隐上天竺","f":"五言古诗","c":["苏桥初进艇，露峰忽振衣。","三竺开丹鹫，诸天在翠微。","涧水浮花片，松磴锁烟霏。","屈折岩扉到，萧条苔径归。","藉草还留酌，闻香顿首机。"]},{"t":"嘉兴三塔寺留别朝仪子谦二使君年丈","f":"七言律诗","c":["三塔移舟望若仙，穹林翠壑俯江烟。","莺花对酒城春丽，钟梵登楼海日先。","世路无端频送客，空门不碍拟逃禅。","与君更是燕吴别，冲雨开帆各惘然。"]},{"t":"虎丘寺侍少傅守溪公游奉次高韵 其一","f":"七言律诗","c":["禅径香台访碧山，玉堂黄阁奉台颜。","乍挥藻翰花争丽，久脱朝簪鹤并间。","林下看云松影静，岩边著屐藓痕斑。","分明仙舸中流坐，瞻送宫袍月下还。"]},{"t":"虎丘寺侍少傅守溪公游奉次高韵 其二","f":"七言律诗","c":["潭渚逶迤草树重，上方台殿隐孤峰。","清辉夜吐吴城月，虚籁寒生梵院松。","窗瞰浦云宜引望，石留僧讲谩遗踪。","移舟更欲归城市，惆怅青山日暮钟。"]},{"t":"东平遇雨","f":"五言律诗","c":["急雨来东郡，萧萧乱入云。","祷祠诸路见，亢旱一春闻。","风疾吹疑断，天高洒易纷。","都饶万民望，吾亦洗炎氛。"]},{"t":"莲花淀舟泛","f":"五言律诗","c":["沿洄洲渚异，演漾水云空。","绿荷初冒日，青蘋解起风。","唳鹤横天迥，眠鸥炯云同。","会意聊自适，望美转难穷。"]},{"t":"卢沟桥","f":"五言律诗","c":["逝波与行客，汨汨无时休。","猊蟠明积雪，虹饮亘长流。","晓月迷征骑，春沙压弊裘。","经过道傍寺，暍思且淹留。"]},{"t":"忆钤山寄溪亭明府","f":"七言律诗","c":["小径升堂绿桧长，翠屏终日对钤冈。","丘园物色闲闲在，朝市风尘事事忙。","尚忆琴尊同笑语，最怜风雨发舟航。","朝来马上逢乡使，为寄新诗当八行。"]},{"t":"南京户部后池双莲同干大司徒王公邀赋","f":"五言古诗","c":["朱夏尚书省，池莲表异祥。","绛葩开并蒂，青乳结连房。","晻薆红云丽，披翻翠盖长。","文鸳纷比翼，振鹭俨分行。","引类何猜妒，淩波故颉颃。","灵妃泛湘浦，赵女入昭阳。","照月平分影，迎风倍有香。","瑞呈鲛室外，盛过鲤湖傍。","旱暵忧方剧，芬敷理讵常。","气和占圣世，地重切公堂。","嘉木歆连理，灵芝颂九光。","予惭职歌颂，留赏滥华觞。"]},{"t":"初拜留院少师相公赠诗用韵拜酬","f":"七言律诗","c":["金陵楼阁倚天开，玉署晴云覆禁槐。","荐赋敢晞文似者，拜恩真荷帝俞哉。","鸿钧播物宁论德，豹管窥斑却愧才。","拭目庙堂歌喜起，五星重聚凤凰来。"]},{"t":"奉酬汪石潭宗伯","f":"七言律诗","c":["八座高衔礼绝攀，两朝清望重于山。","招延隽老皆登用，揣量非才合置閒。","驽骀岂复思千思，广厦终期庇万间。","谁意用儒逢世理，一尊相属重开颜。"]},{"t":"奉酬翟石门兄","f":"七言律诗","c":["春明别棹问南京，谁道君犹羡我荣。","恋阙巳瞻红日远，忝官仍喜玉堂清。","鸠巢计哂经营拙，鱼饭心怜去住轻。","十七年中同宦侣，细论离合倍关情。"]},{"t":"夕次潞河怀寄馆阁寮友 其一","f":"五言律诗","c":["朝游燕台上，夕宿潞河滨。","空洲牵积水，广陌足流尘。","情忆离尊满，年伤别袂频。","玉署星辰切，金陵月露新。"]},{"t":"夕次潞河怀寄馆阁寮友 其二","f":"五言律诗","c":["虚薄忝朝籍，文馆厕英寮。","萝施攀松柏，葭倚接琼瑶。","鸟有同栖树，鱼怜独上潮。","江海参辰隔，流盻极春霄。"]},{"t":"春迎慈圣歌 其一","f":"七言绝句","c":["绿水云摇帐殿开，龙艘日照锦帆来。","千盘玉膳分船进，百骑银珰奏御回。"]},{"t":"春迎慈圣歌 其二","f":"七言绝句","c":["御气金门起郁蟠，至尊当殿候鸣銮。","玉食直移九州养，龙楼长奉万年欢。"]},{"t":"春迎慈圣歌 其三","f":"七言绝句","c":["濮园议礼伸舆论，代邸崇恩本圣情。","正阳文母遵门入，五凤英皇却辇迎。"]},{"t":"东昌驿下逢少保鹅湖相公赴召，是日大行人赍敕迎劳适至，敬抒赠贺","f":"七言律诗","c":["直道谁云竟忤时，如公亲结九重知。","大贤出处关朝运，圣代谋谟重鼎司。","龙纸才开天咫尺，使轺重遣路逶迟。","试论再入中书事，文吕于今复见之。"]},{"t":"德州董子庙","f":"五言古诗","c":["董生读书处，寂寞临高台。","门墙窥孔室，编简拾秦灰。","业守三馀积，宫存一亩开。","墨池春草遍，园木晚禽来。","独有贤良策，人称王佐才。"]},{"t":"翰林斋宿","f":"七言律诗","c":["郊禋元岁盛声明，玉署深寒宿旧京。","长乐听钟天已远，钟陵对雪梦犹清。","池头星斗归环佩，城上风云飐旆旌。","鹓侣此时皆侍从，綵毫春色赋初成。"]},{"t":"汪司成学省斋宿寄赠","f":"七言律诗","c":["清宵琴铎静斋庐，怅望无因奉起居。","寺近独吟孤嶂雪，烛明亲校六堂书。","云中比翼瞻鸿雁，河畔开缄忆鲤鱼。","渐拟谢池春草发，清诗幽梦复何如。"]},{"t":"祷雨晓出神乐观","f":"五言律诗","c":["灯火严城启，楼台秘苑通。","精明石坛月，凄断柏林风。","望极仍延伫，忧深尚蕴隆。","瓣香勤祝史，何以格皇穹。"]},{"t":"钦佩南原草堂集别","f":"五言律诗","c":["梁宛乘骢马，秦淮掩竹扉。","因怜奉丹诏，不得羡荷衣。","古屋秋山近，清池夕鸟飞。","故人从此去，吾至欲何依。"]},{"t":"黄子伯固昔为兵部郎官率同列谏止巡幸，被杖斥归。今上登极起为南京大理丞，奉表入贺饯以是诗","f":"七言律诗","c":["明到凤楼听漏日，汉仪重睹泪堪垂。","伏蒲旧侣谁同在，荐藁芳名帝独知。","骅骝逸步谙长道，鹓鹭崇班恋赤墀。","凭将金鉴千秋录，为献南山万寿卮。"]},{"t":"张子常甫自翰林出督学旋以病告寄赠","f":"七言律诗","c":["登朝与子最情亲，院宿郊游事巳陈。","暂失凤池官自好，重归山径业犹贫。","遍栽松菊疑真隐，且废讴吟惜病身。","燕乳蝶飞烟草绿，相思难寄秣陵春。"]},{"t":"新作院署之堂汪司成投赠佳篇用韵和酬 其一","f":"七言律诗","c":["偶锄荒圯得清深，更置芸编对素琴。","凉吹泻轩翻竹韵，朝阳临砌捧葵心。","高依凤阙知天近，净扫蛩阶与月侵。","幸有大贤携晚进，文觞几度惬幽寻。"]},{"t":"新作院署之堂汪司成投赠佳篇用韵和酬 其二","f":"七言律诗","c":["金銮西畔玉堂深，凤沼云泉滴暗琴。","巳藉典谟开骏业，更留烟月寄閒心。","池栽脩竹藏莺语，亭覆荒碑见藓侵。","牛渚故逢仙子问，桃源不遣世人寻。"]},{"t":"和郭司业官舍閒咏 其一","f":"五言律诗","c":["阶西众山处，重到有馀情。","地是名贤宅，庭栽古柏成。","夕岚迷叠嶂，秋雨过高城。","最爱摊书坐，窗灯映竹清。"]},{"t":"和郭司业官舍閒咏 其二","f":"五言律诗","c":["前日瀛洲侣，同来白下居。","真能忘尔汝，时复到阶除。","鱼笋供常宴，朱铅校古书。","南都官况僻，暂免听朝车。"]},{"t":"和郭司业官舍閒咏 其三","f":"五言律诗","c":["池宽新雨后，山翠夕阳时。","秀句无心得，幽怀只自知。","暮钟来古寺，秋槿遍疏篱。","欲践移尊约，新凉月色宜。"]},{"t":"酬和少宗伯汪先生省中步月见怀之作 其一","f":"七言律诗","c":["南宫风露溢清寒，华月当窗转玉盘。","始信仙踪隔尘土，漫怜浮世有悲欢。","茶烹石鼎分池雪，香爇金垆和泽兰。","忽荷云章寄琼署，欲携春兴伴花坛。"]},{"t":"酬和少宗伯汪先生省中步月见怀之作 其二","f":"七言律诗","c":["夜深高咏在虚亭，无柰蟾光影竹青。","对树栖鸦眠自在，傍城更柝语丁宁。","歌馀白雪翻瑶瑟，兴入沧洲拂画屏。","人事故逢清景少，赏心长为碧云停。"]},{"t":"石潭先生荣进吏侍兼副史局用韵贺赠","f":"七言律诗","c":["凤日龙霄近欲攀，仙踪元只在蓬山。","尽誇荣宠从今盛，长拟门庭似旧閒。","群才总属陶钧地，一字犹严衮斧间。","当日相从今远别，玉堂凉月梦清颜。"]},{"t":"送王中丞赴召前在豫章有平难之绩","f":"五言律诗","c":["绣斧清霜避，楼船绿水开。","风云千历会，麟凤众贤来。","投老仍严召，当途赖上才。","向来筹策地，投檄净烽埃。"]},{"t":"赠林大理茂贞","f":"七言律诗","c":["尔别河桥系我思，柳枝攀赠绿烟丝。","中兴奏议看前辈，南国声名重棘司。","今古秪应荣节槩，圣明奚忍负恩私。","明庭此去观夔契，好续徂徕圣德诗。"]},{"t":"杨侍御使蜀","f":"七言律诗","c":["江草萋萋江水长，使轺闻欲度潇湘。","开帆夜坐星河色，载笔春吟杜若香。","綵绣过家非旧服，皂囊还阙有新章。","西州五月无炎暑，应避青骢满路霜。"]},{"t":"待月集宗伯凤山邸第","f":"五言律诗","c":["风梧翻夕籁，云叶漏轻光。","东林初上月，华馆更留觞。","寅清欣务简，宴语接宵长。","方占德星聚，复咏柚华芳。"]},{"t":"送礼侍吴公赴召","f":"七言律诗","c":["文昌星彩动南宫，徵拜三卿宠数崇。","承旨故随宗伯后，致辞初入谢班中。","披云近睹长安日，击水高抟渤海风。","朝省事频閒日少，回看烟月忆江东。"]},{"t":"蒋户侍省墓送赠","f":"五言律诗","c":["楚江秋潦净，巴岭夕云重。","烟鸟随孤舫，乡山到万峰。","窗园馀旧菊，墟墓长高松。","国计遥相待，期君隔岁逢。"]},{"t":"赠邵佥宪","f":"五言古诗","c":["幽兰閟芳馨，白璧怀坚贞。","端居不踰阈，奕奕当世名。","剡荐驰云陛，鹤书贲柴荆。","直道昔忤时，今为士所荣。","始感白日照，亲见黄河清。","恭翼承皇命，慷慨发脩程。","骢车列城避，鸟道千峰行。","水邮经楚甸，海峤浮昆明。","饮冰徇苦节，击隼蜚英声。","挥手自兹别，许身良不轻。"]},{"t":"奉送司寇赵公入觐","f":"七言古诗","c":["群公得句锵鸣球，司寇引杯登綵舟。","金函奉表江东发，银汉乘槎天上游。","六月沧洲不知暑，夜泊风烟渺何许。","远势斜分清泗流，新凉早入长杨树。","羡公怀抱有馀清，临流见月几诗成。","调高白雪谁同和，行爱青山自问名。","公今去国巳经时，星履重来上赤墀。","皋陶淑问持邦宪，阅道清忠结主知。","纯皇当日擢群英，三十馀年并列卿。","庙堂正藉经纶业，江海犹传冰糵声。"]},{"t":"赠寇京兆","f":"七言律诗","c":["宦情乡思渺难裁，怅望春帆带雨开。","芳草不堪频送客，暮云何处独登台。","闾阎解说循良政，廊庙元须卓异才。","借问府中林馆胜，棠花应候使车回。"]},{"t":"赠边太常黎银台北觐 其一","f":"五言律诗","c":["两乡南国望，同上赤墀行。","接羽鹓鸾贵，论言玉雪清。","冠裳临伟饯，风雨发严程。","遥羡川途兴，新诗几许成。"]},{"t":"赠边太常黎银台北觐 其二","f":"五言律诗","c":["莽莽龙河雪，双帆几日开。","亦知从此别，巳是隔年回。","珂马春城并，衣冠晓仗催。","驿亭梅柳色，来往送行杯。"]},{"t":"暮春神乐观饯方使君","f":"七言律诗","c":["登临南郭久相期，忽漫看山是别时。","童子正宜春服咏，使君莫为一尊辞。","林中坐石焚香静，花里穿云出洞迟。","欲赠美人无缟纻，石坛折取古松枝。"]},{"t":"赠少司寇胡公赴召","f":"古风","c":["秣陵佳胜几招邀，公去风骚叹寂寥。","?俊总登台鼎地，乾坤今睹圣明朝。","鹍鹏击水辞瀛海，鹓鹭排云上紫霄。","黄花送酒期留醉，沧浦鸣榔惜去遥。"]},{"t":"赠太宰罗公归省","f":"七言律诗","c":["宁亲诏赐驿舟行，祖席南都尽列卿。","裴宰重名悬水鉴，秦公家范列簪缨。","日临化国春逾永，星映澄江德共明。","已报远书传勿药，要知虚席待持衡。"]},{"t":"大司马廖公致政","f":"七言律诗","c":["两都清望许谁先，留钥恩深遽引年。","陵路晓辞松罢雪，江船春坐水连天。","山林岁月从今得，编简勋名与世传。","旧里龙湾草堂胜，手栽松菊故依然。"]},{"t":"赠杨月湖先生","f":"古风","c":["尘外高踪何处?，白云依岫鸟归林。","才于济世施难尽，学为逢原得最深。","独抱韦编閒自注，静观庭草坐长吟。","门墙已隔春风地，江汉徒悬北斗心。"]},{"t":"大宰杨公考绩送赠","f":"七言律诗","c":["相业当朝文敏最，直看家学到今公。","笏床经笥传何远，岐凤郊麟瑞本同。","政以经纶归重望，久知清白振高风。","国思世受何为报，多在山公启事中。"]},{"t":"送司徒秦公入朝","f":"七言律诗","c":["剑履乘春上玉墀，梅花度腊送行卮。","承明宣室元相待，鹭溆钟陵无到时。","江上流移何日少，眼中经济属公宜。","东曹斋阁松阴在，几借前筹退食迟。"]},{"t":"观雪登清凉山饯秦司徒","f":"五言律诗","c":["岩壑风烟积，楼台气色寒。","祗园最高处，飞雪更宜看。","鹤近瑶空舞，花依绮席漫。","中台趣严召，南斗寄馀欢。"]},{"t":"送鲁给事之江西","f":"七言律诗","c":["远别逢春望转迷，柳条萦绿草新齐。","回看紫禁烟霄上，独宿征帆楚水西。","事往不堪闻战伐，忧分行可慰黔黎。","越边高阁临江在，閒对山云续旧题。"]},{"t":"赠寇都宪赴镇","f":"七言律诗","c":["上谷风烟钜镇开，雄关叠嶂锁萦回。","山川故识鸾舆幸，戎落新惊绣斧来。","耕牧总叨明圣力，保釐多倚宪臣才。","秋城落日烽尘静，倚剑遥登万里台。"]},{"t":"送边都宪召掌北台","f":"七言律诗","c":["诏书宣召北门归，恋阙怀乡愿不违。","行爱云山过旧里，步纡星履上彤闱。","朝廷正倚台纲重，天日长瞻帝座辉。","雄峻古称三独坐，百寮回首避霜威。"]},{"t":"顾山人寿诗","f":"七言律诗","c":["最忆芜城车马地，草堂花竹净风烟。","地偏廛市同真隐，貌古衣冠似列仙。","清爱碧箫吹海月，静看玄鹤舞芝田。","绿蒲青艾俱生色，岁岁开尊午日前。"]},{"t":"朱润轩寿","f":"七言律诗","c":["他乡献寿逢新岁，同里相过总近亲。","行乐不妨时序改，交驩惟有酒杯频。","岸花樯燕能留客，对水看山不负春。","闻说挥金多义事，江城无限待餔人。"]},{"t":"徐氏东园观梅","f":"七言律诗","c":["东阁开筵雪树春，主情花意共清真。","似怜标格初经眼，自识芳香久袭人。","鸑鷟故移天上种，珊瑚不受世间尘。","习池宾客俱名胜，雅尚从知德有邻。"]},{"t":"喜雨 其一","f":"五言律诗","c":["南国夏无雨，钟山朝出云。","精虔三日祷，甘澍万家分。","野爱商羊羽，池怜蜥蜴群。","康衢今日颂，一饭是吾君。"]},{"t":"喜雨 其二","f":"五言律诗","c":["卧闻清雨至，萧飒浣烦襟。","开轩进荷气，闭院静驺音。","凤沼流泉细，彤楼隐雾深。","隐几听脩竹，何异在中林。"]},{"t":"喜雨和胡都宪","f":"七言律诗","c":["沾席敲窗慰客心，院池新水坐来深。","烦襟正解尘中渴，好事如听谷里音。","霮䨴总随和气洽，萧森时逐远风沉。","天公只借须臾力，明日郊原看绿阴。"]},{"t":"喜雨和汪宗伯","f":"七言律诗","c":["怅望星河作夜晴，晓闻零雨度高城。","乍迷云岫氛氲合，乱入槐轩淅沥鸣。","正有清凉破炎毒，可无新句答高情。","郊原明日堪携酒，自喜吾兼吏隐名。"]},{"t":"喜雨和秦宗伯","f":"七言律诗","c":["焦枯何计讹吹嘘，一雨全胜万斛珠。","看舞商羊应得意，听鞭蜥蜴最怜渠。","凉开竹簟眠方稳，日饭盘蔬味自腴。","志喜有诗传画省，巴人惭和郢歌馀。"]},{"t":"喜雨和郭司业","f":"七言律诗","c":["入秋忽听翻江雨，长夏空瞻落槛云。","顿失尘熇净如洗，乍迷山翠杳难分。","民情正望仓箱富，神荐犹凭黍稷芬。","更喜清凉慰幽独，简编遥夜坐膏焚。"]},{"t":"赠友 其一","f":"五言律诗","c":["大江渺千里，金陵丽五云。","枉棹特垂访，念子意何勤。","久客怀故知，相见各欣欣。","且复话乡邑，不厌穷朝曛。"]},{"t":"赠友 其二","f":"五言律诗","c":["留都罗群署，词林最萧閒。","古屋荫槐柏，时见檐前山。","图史纷座隅，披玩豁心颜。","与子坐永日，清风竹珊珊。"]},{"t":"赠友 其三","f":"五言律诗","c":["北风吹层波，高帆疾于马。","矫首望云山，日夕到乡舍。","亲友慰远归，春杯正堪把。","故园多所欢，薄宦何为者。"]},{"t":"简尚宾将归赋赠","f":"七言律诗","c":["相留忽是一年期，落叶西风话别时。","宾馆寂寥寒榻在，吏情凉薄故人知。","舟冲雾雨帆飞远，书忆乡园雁到迟。","明日古槐修竹里，玉亭吟坐复同谁。"]},{"t":"赠叶刑部","f":"五言古诗","c":["把酒逢宵月，登车犯早寒。","逶迤涉远道，日夕望长安。","霜蹄看骥展，风翮羡鹏抟。","以我僻居者，殷勤怀所欢。","迟归秣陵署，高咏对云峦。"]},{"t":"吴司空旧家嘉鱼有东湖徙居苍梧作东湖书院命予赋","f":"五言律诗","c":["问讯东湖第，司空此卜居。","清澜堪悟道，石室可藏书。","野绿开裴阁，花香引邵车。","苍梧转奇胜，风景似嘉鱼。"]},{"t":"题罗太守画 其一","f":"五言律诗","c":["何处林居好，移来庭壁间。","风泉留喷薄，云峤锁孱颜。","溪忆浮槎到，峰疑采药还。","郡斋收印坐，知尔饱看山。"]},{"t":"题罗太守画 其二","f":"五言律诗","c":["溪山尽瑶素，晓霁更宜人。","不悟梁园雪，虚疑芳树春。","剡舟乘兴逸，郢曲和歌新。","怀君当此夕，难浣渴心尘。"]},{"t":"聂君持梅雪卷请题走笔赠之","f":"七言古诗","c":["鹭沙尺书何日传，聂君近泊金陵船。","到门览剌丞出迓，丰度雅朴神翛然。","书云此君乐幽尚，十年寄迹江湖边。","平生爱梅有真癖，梅雪自号争清妍。","琼姿绰约种万本，茅屋正在春风前。","芒鞋缓步石径月，拄杖独往青林烟。","有时临流发孤啸，风致髣髴疑逋仙。","只宜跨驴学肩耸，那复骑鹤思腰缠。","青蚨沽酒与之醉，散发岸帻歌青天。","吁嗟聂君亦不俗，挥毫赠尔梅花篇。"]},{"t":"无锡茹氏惜阴楼其先世所创民泽请题","f":"五言律诗","c":["茹翁读书处，高楼名惜阴。","捲幔灯烟在，开轩草带深。","古人勤志业，我辈得规箴。","为诵陶公传，千秋见苦心。"]},{"t":"酬陆司业见寄秋怀之作 其一","f":"七言律诗","c":["书囊药裹镇吾随，岐路东西岂预期。","多病祗怜癯骨在，素心惟荷故人知。","游鱼远水书难寄，碧树高云意每迟。","鳌禁掖垣追逐地，独惭虚薄□恩私。"]},{"t":"酬陆司业见寄秋怀之作 其二","f":"七言律诗","c":["云海沧茫隔凤台，两年刚得一书回。","敢将胶漆期君并，莫为阴晴与世猜。","往日诗篇常在把，几时尊酒定重开。","龙山又是茱萸节，珍重登高作赋才。"]},{"t":"登金陵观音山","f":"古风","c":["江阁凭虚似幻成，绿崖苍壁有人行。","波晴日抱鼋鼍窟，天险山围睥睨城。","万里涛泷争赴海，八?琛帛尽朝京。","谁能数到层轩坐，临水看云失宦情。"]},{"t":"和顾东桥宪长游天界寺之作","f":"七言律诗","c":["素衣不受市尘侵，虚谷超遥见此心。","苔径客吟猿鹤挣，石床僧定薜萝深。","高贤有意依莲社，开士何年建鹫林。","更借玉琴酬雅兴，欲凭瑶草寄幽寻。"]},{"t":"寄寿高仰峰先生 其一","f":"五言律诗","c":["勋业三朝重，年龄八帙高。","名应书汗竹，寿及荐蟠桃。","天远冥鸿迹，池新綵凤毛。","圣明颁异宠，赐诰贲林皋。"]},{"t":"寄寿高仰峰先生 其二","f":"五言律诗","c":["乡里论耆旧，惟公五福完。","寿乡馀日月，宪府重衣冠。","老鹤昂仙骨，贞松耐岁寒。","青云誇令子，更折桂枝看。"]},{"t":"寄寿高仰峰先生 其三","f":"五言律诗","c":["昔奉秋堂宴，今歌云海篇。","追趋怀杖履，瞻望礼星躔。","台傍重门近，洲分碧水连。","秫田新报熟，歌醉入丰年。"]},{"t":"蔡氏浚永阡","f":"五言古诗","c":["露草眠牛集，云松吊鹤来。","黄山开碧嶂，蒿里閟层台。","哲士今亡矣，高风日远哉。","渊源寻旧德，梁木叹遗材。","不见丘原起，惟馀风树哀。","诸孙寒食里，日暮奠椒回。"]},{"t":"奉送太宰杨公赴召","f":"五言古诗","c":["象德家声远，登贤国论公。","泰应占世运，圣巳识渊衷。","听履星辰切，持衡水鉴同。","构堂资柱石，补衮藉山虫。","熙洽隆殷祚，高明达舜聪。","平章均四海，峻绝冠群工。","霖雨收舆望，丹青肖祖风。","四朝推练达，一节想清忠。","播物鸿钧大，抡材杞梓充。","山涛能荐士，王旦不言功。","猷告宁闻外，谟询待折中。","正容亡憸侧，轸虑切瘝痌。","祖席逢秋净，王畿属岁丰。","竞看威凤集，周雅咏梧桐。"]},{"t":"送汪吏侍先生","f":"七言律诗","c":["叨随钟阜瞻依近，怅别江波跂望劳。","长奉清言过玉署，重闻仙步上铨曹。","时艰静曙纡筹定，国议新陪出论高。","愿坐庙堂同水镜，总收贤俊入甄陶。"]},{"t":"至日信州怀寄汪石潭宗伯 其一","f":"七言律诗","c":["至日题诗信州驿，泊舟虚馆近寒汀。","江潭岁晚蛟龙蛰，岩壑霜馀桧柏青。","鸣玉尚思金殿直，移文深忆草堂灵。","谢公正在东山畔，日对云峰看翠屏。"]},{"t":"至日信州怀寄汪石潭宗伯 其二","f":"七言律诗","c":["天畔登台望北辰，三回巳隔御筵春。","冰霜暗惜年华老，棋局频看世事新。","安得梅花逢驿使，欲凭瑶草寄佳人。","白鸥片片风湍急，捩柁冲星下远津。"]},{"t":"弋阳遇赠舜卿翰检兼寄用修殿撰 其一","f":"五言律诗","c":["京国何时出，舟航此地逢。","批鳞叩龙阙，塌翼下鳌峰。","天地生全德，江湖汗漫踪。","相留话今夕，明发楚云重。"]},{"t":"弋阳遇赠舜卿翰检兼寄用修殿撰 其二","f":"五言律诗","c":["两贤俱侍从，万里各风埃。","鸟道青冥外，谁怜逐客来。","醉歌频击剑，愁望且登台。","珠树同栖鹤，蓬山迟尔回。"]},{"t":"送凌司训","f":"五言律诗","c":["沅湘从此去，孤棹雨冥冥。","烟屿宜春望，林猿足夜听。","青云谁假翼，白首叹穷经。","明日河阳酒，思君草色青。"]},{"t":"雨泊凤洲酬寄朝望太守 其一","f":"五言绝句","c":["厌听高城雨，还维古驿舟。","琼枝那近眼，烟浪递生愁。"]},{"t":"雨泊凤洲酬寄朝望太守 其二","f":"五言绝句","c":["鸦湿波翻木，鸥喧雨满洲。","离心何处是，暝色载孤舟。"]},{"t":"雨泊凤洲酬寄朝望太守 其三","f":"五言绝句","c":["凤洲几回至，一至情眷眷。","佳期渺未忘，薄别宁当怨。"]},{"t":"雨泊凤洲酬寄朝望太守 其四","f":"五言绝句","c":["山阁忆春临，渚花宜晚望。","不共瀼西游，空怀郢中唱。"]},{"t":"游洪阳洞","f":"七言律诗","c":["鹤驭鸾骖去不回，林扃岫幌客频来。","洞门日照烟萝发，岩窦泉飞雪屋开。","始惊奇僻非人境，更爱攀临坐石苔。","回舆出谷千峰暝，猿啸禽啼万壑哀。"]},{"t":"晓济鄱阳湖","f":"五言律诗","c":["鸣榔发荻浦，击楫过蘋洲。","皛皛霞日烂，盈盈天汉流。","远帆征未息，高鸟去何求。","汗漫江湖志，吾今几度游。"]},{"t":"泊弋阳江","f":"五言律诗","c":["客思增悽断，风湍渺宿留。","云来津树黑，雨集浦帆收。","作宦逢杨闰，辞家感麦秋。","龟峰岚雾里，心赏若为酬。"]},{"t":"夕会顾宫谕兄姑苏驿下","f":"七言律诗","c":["共怜挥手别鳌峰，烟水吴洲此夕逢。","世事秪应论塞马，春雷正合起潭龙。","坐阑红烛谈犹健，折赠琼枝意自重。","借问昔时鸳鹭侣，几人同听凤楼钟。"]},{"t":"姑苏王少傅怡老园子贞中舍邀集","f":"五言律诗","c":["宛似入鸡山，寥寥云壑间。","攀松上岩翠，憩石坐苔斑。","霄汉清班接，林园乐事关。","昔游陪剑履，辉赫想台颜。"]},{"t":"怡老园后池集","f":"七言律诗","c":["竹径萝烟翠且重，行寻幽洞失前峰。","因攀岩下丛生桂，故识云中旧种松。","楼台碧水虚相映，车马高门日自容。","犹道绿尊欢未尽，别来深院起歌钟。"]},{"t":"虎丘临眺和朱侍御 其一","f":"七言律诗","c":["泊舟禅径石门通，徙倚湖天望不穷。","正扫书坛拜和靖，犹开梵塔礼生公。","汀洲晚浸蒹葭水，台殿晴呼松柏风。","惟羡观风骢马使，清游丽句满吴中。"]},{"t":"虎丘临眺和朱侍御 其二","f":"七言律诗","c":["翠岭晴烟锁鹫峰，玉泉阴洞隐龙宫。","高攀双树青冥上，俯瞰三吴宿雾中。","沙浦断云低度鸟，石林修竹静吟风。","禅房水石佳游在，尘世沧桑浩劫空。"]},{"t":"题悟石轩旧传生公说法石为点头轩以是名","f":"五言律诗","c":["盘石寺门前，相传听法年。","袭讹僧善幻，赏胜客犹怜。","松桂流寒月，藤萝起夕烟。","未须谈寂理，聊此息尘缘。"]},{"t":"赋少宰汪公西溪草堂","f":"五言古诗","c":["山辉知玉韫，渊静识龙居。","古邑名贤里，膺门幸到予。","开堂瞻剑履，登阁览清虚。","积翠罗千嶂，分流贯二渠。","夕云生画障，春水动鸥鱼。","庭爱森琼树，门看拥驷车。","玉床留贮笏，丹壁会藏书。","直道中朝仰，高名北斗如。","凤凰需宠诏，萝月卧林庐。","理惬心弥逸，神閒体自舒。","萍游奉佳论，临别意踌躇。"]},{"t":"盘谷歌为司寇高公赋","f":"古风","c":["乐清山水天下奇，中间茗屿更逶迤。","坤灵勃郁萃元气，何人卜筑开新基。","高公百年草堂在，林色川容未曾改。","地隔桃源长子孙，村标盘谷名江海。","盘谷幽栖自隐君，后人济济藉芳薰。","一溪桑梓横青野，九畹兰荪结綵云。","堂下阴森满松柏，风雨泠泠护幽宅。","岁时蘋藻荐明馨，阶前半是朱衣客。","司寇承恩著锦袍，江山掩映罗旌旄。","后来杰出况非一，上下彩凤看翔翱。","礼成叙饮复酬倡，接盏飞觥各相向。","里闬风猷出故家，朝廷礼乐归群望。","吁嗟乎湛恩馀庆奕世存，路人尽识于公门。","请君试听歌盘谷，昔日三槐安足论。"]},{"t":"题胡使君可泉","f":"五言古诗","c":["秦安卦山北，相传有异泉。","胡公读书处，钓月弄潺湲。","漱玉云根净，牵萝雪瀑悬。","夜弦翻雅调，春瓮泻芳涓。","江海覃馀泽，山林结挣缘。","鉴澄心比瑩，膏润暍同蠲。","地以高贤胜，图将美迹传。","次山文笔健，岩石几铭镌。"]},{"t":"经筵进讲毕还至国庠会寮属诸生听讲","f":"七言律诗","c":["翠华仙殿说经回，冠带桥门讲又开。","岂有涓埃禆圣学，独惭模范育英才。","云龙嘉会逢明代，奎壁祥光应上台。","听诵唐虞风噩尔，载歌琴瑟思悠哉。"]},{"t":"送李若溪佥宪","f":"七言律诗","c":["别君南国若为情，聚首无端复送行。","同里衣冠知己少，外台风纪拜官荣。","桄榔夜宿蛮中驿，金鼓晴登岭外城。","儒术古来经世用，直看尊俎坐谈兵。"]},{"t":"送罗南康使君","f":"七言律诗","c":["犹烦领郡赴江干，千里南州路未难。","遗爱旧栽棠树遍，别怀今放酒杯宽。","山深洞可寻名迹，家近书能慰母欢。","见说府中公事简，五峰苍翠倚楼看。"]},{"t":"赠柳州桂二守","f":"五言律诗","c":["南登桂岭道，却上楚乡舟。","赋就江篱晚，书回旅雁秋。","山形攒剑戟，方语杂旃裘。","好种江边柳，还将惠化留。"]},{"t":"赠简少府二首 其一","f":"五言律诗","c":["客舍依莲宇，清风满竹林。","愧予怀短剌，长喜得幽寻。","旌节梁园迥，云山楚甸深。","别离明月共，千里寄同心。"]},{"t":"赠简少府二首 其二","f":"五言律诗","c":["尔向滇中去，官程柰远何。","云峰当马峻，雾树听猿多。","郡僻逢迎简，天南气候和。","相期敷惠政，早入远人歌。"]},{"t":"赠郑南昌复官昔与逆藩之难","f":"七言律诗","c":["黄绶欣看复在身，却论前事益沾巾。","江关乱后馀残垒，棠树春来泣故民。","人情阅世从翻覆，直道怜君有屈伸。","巳喜拜恩同雨露，可堪回首忆风尘。"]},{"t":"大理汤公寿词","f":"五言古诗","c":["廷尉当朝彦，荣名晚节全。","棘堂卿月回，天署法星悬。","魏阙班频入，巴山使久旋。","边陲经略后，旒冕对扬前。","议政过松掖，听经侍翠旃。","礼看优宠渥，貌不怠恭虔。","利锷馀盘错，贞松阅岁年。","书云逢令节，弥诞秩初筵。","却老传真诀，阴功格上玄。","于公曾活狱，贡禹解惟贤。","宅荫宫槐近，窗迎海日先。","愿言跻寿域，长此奉尧天。"]},{"t":"送赵司空致政","f":"七言律诗","c":["嶷然冠剑汉司空，出入三朝操履同。","事忤贵人知节槩，心忧王室见清忠。","俞章赐允皇仁大，荐剡留贤物论公。","遥羡高踪去尘网，云霄万里一冥鸿。"]},{"t":"送秦司徒致政","f":"七言律诗","c":["履声长听殿东墀，祖席春明是别时。","去国二贤舆论惜，登庸八座大名垂。","云霄路隔冥鸿远，江渚情牵碧草思。","莫谓东山成稳卧，苍生应有谢公期。"]},{"t":"送郑刑部之南京","f":"七言律诗","c":["人事无端类转蓬，更劳分署过江东。","三年卧病烟霞隔，尊酒逢君笑语同。","地胜湖波浮几席，秋深庭菊傲霜风。","芜城亦是桑乾路，望近桥陵紫翠中。"]},{"t":"送吴学士视篆南京予旧领此职","f":"七言律诗","c":["二年相逐喜同声，几度尘沙并辔行。","新握院章当妙选，重吟江树动离情。","蓬瀛地接金銮近，城阙天开晤嶂清。","借问旧堂脩竹在，壁间虚薄愧题名。"]},{"t":"陈监丞父寿词","f":"七言律诗","c":["寿酒新开秋露盘，草堂高隐碧云端。","花边玉杖閒堪拄，箧里丹经老自看。","济郡伏生还授学，鹿门庞叟只遗安。","胶庠有禄能分养，恬淡无心羡达官。"]},{"t":"费氏横林孝友堂诗为学士钟石赋","f":"五言古诗","c":["地擅溪山美，乡称德义门。","衣冠先泽远，诗礼古风存。","瓜蔓绵相引，槐阴绿正繁。","傍岩开甲第，绕砌树芳荪。","叠嶂芙蓉峙，飞流玉练奔。","赭亭春秀茗，绩石夜闻猿。","萝幌摊书静，萍池洗墨浑。","钓游仍旧里，腾翥并天阍。","黄阁崇师保，中朝伟弟昆。","朝回珂满路，燕集醴盈尊。","遗范元无改，殊恩讵可论。","秪应传五桂，名比窦家村。"]},{"t":"经筵宴罢有述","f":"五言律诗","c":["衮席龙盘扆，仙班鹭列行。","赐筵沾玉醴，归袖带炉香。","身到钧天近，恩垂湛露瀼。","圣朝儒学贵，虚薄愧明扬。"]},{"t":"赏荷刘司空部署次韵","f":"七言律诗","c":["东省盆荷初夏开，绮筵晴旭净风埃。","气和嘉瑞先时见，地迥灵根近日栽。","镜水綵云频对酒，露盘仙掌独登台。","尚书星履朝天罢，每为红芳竹径来。"]},{"t":"夏日李公薇园燕集次徐少宰","f":"七言律诗","c":["堂轩地迥开新筑，松桧年多长旧围。","涉径忽惊炎暑失，寻诗故与俗情违。","池边折芰留连坐，竹外移灯酩酊归。","遥想紫薇花上月，清宵独对谢玄晖。"]},{"t":"徐养斋方棠陵偕至喜而有作用王浚川韵","f":"七言律诗","c":["江上新传李郭舟，鹤汀凫渚羡清游。","谁知今雨来千里，似忆佳期渺十洲。","梧竹越山栖綵凤，风云天路引骅骝。","相留拟下南州榻，醉里狂歌海月秋。"]},{"t":"凤图为宗伯序庵公题","f":"古风","c":["凤飞千仞宿昆丘，饥食竹实渴饮沧海流。","人间此物不易见，云胡得之置在中堂幽。","矍然注视使我疑，文彩照座光陆离。","初惊素壁开丹穴，忽辨朝霞捧赤曦。","腾辉绚景瀰东海，积石方壶渺焉在。","嬴女箫声隔彩云，缑仙笙韵流苍霭。","忆昔重华称盛治，览德呈祥曾一至。","周京载见岐山鸣，迩来千载不复闻其声，祗令粉墨丹青空尔形。","方今圣人在位寰宇清，豁廓氛■登休明。","锵锵韶濩谐灵奏，蔼蔼冯翼充王廷。","吁嗟乎人中之凤乃所珍，我爱南宫上卿美且仁。","格天事业归寅直，华国文章重缙绅。","昌辰更赋卷阿什，化日高翔阿阁春。"]},{"t":"九日登戒坛寺阁 其一","f":"五言律诗","c":["梵阁千峰里，征骖九日来。","松萝禅径入，龙象法筵开。","黄菊宁簪帽，青莲独上台。","如堪授直戒，吾此息氛埃。"]},{"t":"九日登戒坛寺阁 其二","f":"五言律诗","c":["尘迹何因到，名山不易逢。","谷深微辨径，寺近始闻钟。","古树寒飙急，幽轩夕翠浓。","菊觞违雅集，相忆在高峰。"]},{"t":"和陈司马元日早朝","f":"七言律诗","c":["衮袍当殿识威严，黄表开函近御筵。","舜历尧蓂欣载纪，日华天表庆同瞻。","赤葵心向青阳吐，丰草恩随湛露沾。","闻道塞垣新撤警，圣谟贤略巳先占。"]},{"t":"寄寿少傅木斋谢公 其一","f":"五言律诗","c":["孝庙看遗老，明公独岿然。","向非平格寿，那睹中兴年。","剑履重趋阙，纯诚自格天。","要知敦薄俗，湖上有归船。"]},{"t":"寄寿少傅木斋谢公 其二","f":"五言律诗","c":["再入中书日，诸生得重亲。","岱宗瞻气象，龙马羡精神。","正喜谋衢室，旋闻偃渭滨。","高楼限岩壁，寿斝若为陈。"]},{"t":"赠别汝湖学士","f":"七言律诗","c":["少年擢第胜琼枝，同在清朝白玉墀。","渐老不堪仍送别，后期何地更传卮。","横经帝幕皆称贵，载笔纶闱巳讶迟。","剡水越山深驻马，因看春草一相思。"]},{"t":"崦西徐少宰省中藤花开有诗邀予同作徐昔侍外舅守溪公授经于此今继践其职云 其一","f":"五言律诗","c":["华省曙沉沉，朝回坐密林。","竹风增爽气，花露净朝阴。","轩静驯孤鹤，床空对素琴。","皆言公辅贵，仍有薜萝心。"]},{"t":"崦西徐少宰省中藤花开有诗邀予同作徐昔侍外舅守溪公授经于此今继践其职云 其二","f":"五言律诗","c":["地是留棠旧，人应比玉清。","独攀东省树，犹忆下帷情。","萝映摊书静，花增染翰明。","天庭多雨露，岁晚共芬荣。"]},{"t":"寄赠宫保白楼吴公","f":"七言律诗","c":["却忆吴门濠上居，草堂高阔瞰清虚。","青宫旧识尚书履，石室应藏太史书。","开槛海鸥依钓席，移尊山鸟候篮舆。","鸿冥凤翥谁堪似，郗桂庄椿庆有馀。"]},{"t":"赠刘梅国都宪","f":"七言律诗","c":["保釐东土新恩下，制置江淮后命催。","当署棠阴随处满，自天龙敕两回开。","楼船听雨看吴岫，藻翰吟秋上沛台。","报国总需刘晏策，逢时不羡贾生才。"]},{"t":"赠许学士归省","f":"七言律诗","c":["银鱼学士今公辅，青霞丈人真地仙。","紫诰黄麻覃雨露，琼林瑶草傲风烟。","莱衣拜庆承恩诰，郦菊攀英荐寿筵。","暂向故园荣书锦，即归蓬阁赐金莲。"]},{"t":"赠费司训之山阴","f":"五言律诗","c":["游吴还适越，心赏寄风烟。","世业称韦相，诸生仰郑虔。","客帆秋草外，官舍海云边。","送尔增遐想，重歌棣萼篇。"]},{"t":"答用修见赠","f":"五言古诗","c":["鸡鹜争稻梁，凤凰食琅玕。","感恻念物理，沉冥结忧端。","俛仰宇宙间，知己长独难。","我友在远方，欲往从游盘。","岷江阻奔汹，剑岭间巑岏。","缅怀九苞质，讵接双飞翰。","暌离惊岁改，栖息喟形单。","斸苓春雨暮，采菊秋露漙。","明后应天历，众贤集衣冠。","奄忽千里至，执手平生欢。","濯缨升博望，踔辔游长安。","愧比萧艾姿，芳馨托幽兰。","幸容竽迹滥，莫遣胶盟寒。","晤言期谁与，怀抱为君殚。"]},{"t":"再次 其一","f":"五言古诗","c":["昔行湘江曲，万竹青琅玕。","低枝荫水石，高叶拂云端。","幸适心赏趣，宁辞行路难。","漓波渺万里，桂岭郁千盘。","风溪渡飒爽，云峤陟巑岏。","会意辄縻驾，放歌或濡翰。","形胜岂不美，但愧言词单。","朅来故山住，两见白露漙。","眷言怀魏阙，复此弹尘冠。","休文自多病，刘琨故少欢。","京国多贵游，闭门卧袁安。","赠君湘川竹，贻我握中兰。","兰流香气馥，竹凛清风寒。","贞素各自保，精衷讵能殚。"]},{"t":"再次 其二","f":"五言古诗","c":["夫君起西蜀，谒帝陈琅玕。","妙龄赐上第，声名动朝端。","遂令海内士，啧啧称才难。","譬彼珊瑚枝，置之赤瑛盘。","清辉映皎洁，修干凌巑岏。","贱子忝官署，往往接英翰。","珠玉富璀璨，觉我形寒单。","开缄清风穆，入手垂露漙。","耿耿苍水佩，峨峨切云冠。","池看凤毛贵，庭忆彩衣欢。","苍生望安石，才人羡子安。","郗林应擢桂，谢砌总生兰。","巨川须拯溺，广厦思庇寒。","致身立津要，早愿勋猷殚。"]},{"t":"用修殿撰惠予蜀中云根竹笔","f":"七言律诗","c":["西蜀云根修竹清，管城新制比南金。","携来尚带岷峨色，赏剧全倾翰墨林。","欲赋远情牵渭树，合裁天诏洒商霖。","虚心直节元相倚，珍重佳人赠爱深。"]},{"t":"用贞中舍赠云根竹茅笔各一","f":"七言古诗","c":["青茆束束银兔毫。","云根修篁鸾凤毛。","娟娟柔翰利所操。","携持蜀山越江涛。","投赠直比金错刀。","翰林文价赖尔曹。","念我蹇思增郁陶。"]},{"t":"梦竹卷题赠胡世贞光禄","f":"七言古诗","c":["君家竹林何处所，万玉萧森作风雨。","夜闻乡梦绕园扉，晓望征帆渡江水。","江水悠悠堪濯缨，羡君风致有馀清。","玉堂延阁辞分直，凫渚鸥汀思结盟。","忠安公后重家声，千甍甲第晋陵城。","云泉自占江南胜，轩盖宁论世上荣。","世间万事何反覆，平地波澜变蝇玉。","君今归去耳不闻，把笔题诗倚青竹。"]},{"t":"发京六部都察院通政司大理寺诸公会饯于报国寺","f":"七言律诗","c":["双龙御节下重霄，九棘芳筵集上僚。","冠盖宠行宾礼重，山川衔命去程遥。","天香清梵留僧室，雾树啼莺别市桥。","幸遇圣明崇孝理，愿从南国采风谣。"]},{"t":"登毗卢阁","f":"五言律诗","c":["远目穷秋望，高窗试醉攀。","鳞鳞列城肆，莽莽抱京山。","沙碛来鸿细，松阴处鹤閒。","鄢襄从此去，旌旆几时还。"]},{"t":"寅长方李二公董徐二少宰至胜泉寺饯别","f":"五言律诗","c":["古寺郊园胜，名卿宠饯过。","还同习池醉，更唱渭城歌。","涧影依松桂，潭香折芰荷。","暮归轩盖远，柰此别愁何。"]},{"t":"胜泉寺宿","f":"五言律诗","c":["相送各巳返，独宿在招提。","钟漏临城迥，星河隔树低。","方欣市喧寂，转觉客怀悽。","因叹劳劳者，深惭萝薜栖。"]},{"t":"夕济黄河","f":"七言律诗","c":["荻丛沙路莽难分，拍岸惊涛骇客闻。","千帆浪里惟看影，一雁天边自叫群。","漫滩积水浑无地，极浦青山半入云。","借问荥城在何处，不堪荒戍闭斜曛。"]},{"t":"郑州察院","f":"古风","c":["使节晨驱初渡河，宋京梁苑日经过。","停车最爱兹轩?，维楫犹惊昨暮波。","暑路尘沙淹暍思，晚云台榭起悲歌。","晋公祠墓千年在，怅望秋烟隐薜萝。"]},{"t":"中秋新郑提学高子大宾集饮 其一","f":"古风","c":["此夕中秋月，来从郑邑看。","冰轮出海净，桂子落云寒。","暂对儒台酒，聊?旅夜欢。","如何千里别，儿女忆长安。"]},{"t":"中秋新郑提学高子大宾集饮 其二","f":"五言律诗","c":["倚槛浮云暝，开樽片月随。","阴晴那可定，会合正难期。","桂苑曾题柱，梁园好赋诗。","相留惜佳景，明发路逶迟。"]},{"t":"中秋新郑提学高子大宾集饮 其三","f":"五言律诗","c":["途倦风尘色，堂清灯烛光。","倏逢秋月满，转觉旅行长。","萤度沾高幔，蛩鸣出坏墙。","坐闻铙吹发，留赏尽馀觞。"]},{"t":"岘山谒羊侯祠","f":"五言律诗","c":["晋代传遗爱，羊祠独至今。","岘山南郭上，千古一登临。","未下看碑泪，犹怀仰止心。","汤汤德泽在，日暮汉江深。"]},{"t":"九日独咏 其一","f":"五言律诗","c":["斋馆坐岑寂，雨声荆楚秋。","风高木叶下，天远汉江流。","佳节思萸菊，新寒理褐裘。","从来惯为客，展卷自销忧。"]},{"t":"九日独咏 其二","f":"五言律诗","c":["地近宜城酒，秋高宋玉台。","临觞那取醉，作赋转兴哀。","淅淅浦枫落，冥冥湖雁来。","阳春堪极目，云雾晓须开。"]},{"t":"初谒宫保九峰孙公投赠","f":"七言律诗","c":["昔窥东阁怅无因，得使南邦喜见亲。","清汉波深龙久卧，碧云天杳凤难驯。","功成名遂升平世，溪泛山游矍铄身。","却到锦堂丛桂里，帝台风月自为邻。"]},{"t":"题宫保孙公宜晚亭","f":"五言律诗","c":["翠屏无限好，历历近青冥。","落景閒宜对，高歌醉自听。","浦帆依鸟尽，岩桂向人青。","黄绮疑公是，终朝辅汉庭。"]},{"t":"安陆阳春台在潜邸之西皇考尝登陟□赋今都院行署实枕其麓往年南坞贾公以礼侍奉册命寓止兹署有诗后六年门人嵩亦忝此官来奉册命睹壁间题敬和一章","f":"七言律诗","c":["皇居帝邸接仙台，使节春曹步武来。","睿藻昔曾留翠巘，尘踪不敢涴苍苔。","龙文御气氤氲合，玺册天书焕烂开。","画省玉堂传盛事，和家衣钵叹非才。"]},{"t":"吉祥寺","f":"古风","c":["峰巘何盘郁，林泽亦芊绵。","鹫峰衔殿阁，珠?倚风□。","此地逢昌运，先皇有赐田。","永戴尧天日，流辉照法筵。"]},{"t":"晚次普门寺作是日发郢诸公饯于池河 其一","f":"古风","c":["郢?山应隔，池河酒尚醺。","独?溪寺宿，疑远世人群。","古桂寒禽聚，虚堂夕磬闻。","神宫更瞻眺，御气绕重云。"]},{"t":"晚次普门寺作是日发郢诸公饯于池河 其二","f":"五言律诗","c":["骑拥岩旌合，钟鸣松寺深。","烟霞盘石磴，台殿耸珠林。","未息征途驾，偏怜阅世心。","郢邦今帝里，节使几经临。"]},{"t":"晚次襄阳","f":"古风","c":["朔雪荒台独雁飞，楚乡凝眺转依依。","天连浦溆惟寒水，山隐城皋已夕晖。","旅客竞?潼口住，钓船閒傍鹿门归。","庞公旧隐岩扉在，怅望无因得息机。"]},{"t":"使归途中作","f":"七言律诗","c":["来日日炎归雪飞，星轺江汉远騑騑。","空山驿傍春梅静，荒徼人逢汉使稀。","南国音书凭旅雁，上林花色待朝衣。","眼中菑殣堪垂涕，细写封章达禁扉。"]},{"t":"裕州阻雪","f":"五言古诗","c":["玄阴凝北陆，皓雪遍中衢。","整驾迟明发，览望复踟蹰。","野旷厉飙急，陴荒饥雁呼。","昔至冲炎日，还今逢岁徂。","蓬转无停迹，輖经多畏途。","临餐乃三叹，沟中盈饿夫。"]},{"t":"保安驿遇张内翰南使","f":"七言律诗","c":["驿榻风灯倚暮寒，庭松积雪皓宜看。","使华远下金銮直，家庆先承綵服欢。","江雁引帆过鄂渚，苑花迎佩忆长安。","扈从正待扬雄赋，感激须弹贡禹冠。"]},{"t":"行次汝坟","f":"五言古诗","c":["汝坟百家市，依依墟土间。","野旷豁予目，青见车前山。","嵩岭露微雪，伊流泻潺湲。","倏感炎燠改，俄兴旌旆还。","遇胜初会意，省菑仍惨颜。","惭乏拯人策，默默但忧叹。"]},{"t":"渡冰志险 其一","f":"五言律诗","c":["洪河冰上度，回望使人惊。","寒日无朗照，哀鸿有断鸣。","垂堂孝子戒，叱驭古人情。","天末风云色，萧萧送远征。"]},{"t":"渡冰志险 其二","f":"五言律诗","c":["远役逢年暮，危途感命轻。","长河蟠地险，积雪与天平。","逆旅悲今古，浮云是利名。","昔闻高蹈者，被褐偃柴荆。"]},{"t":"立春日至京先寄崦西少宰","f":"七言律诗","c":["星轺计日觐神京，彩胜迎春在客程。","沙上柳松烟霁色，水边楼阁雁归声。","阳回海宇人皆乐，云近蓬莱眼倍明。","画省故人劳见念，清诗早为卜旋旌。"]},{"t":"九日天坛登集酬夏桂洲都谏 其一","f":"七言古诗","c":["仙都楼阁堪凝望，谏署壶觞得尽欢。","九日旧从尘里过，八埏今向眼中宽。","风来碣石驱涛壮，日上扶桑影树团。","君擅高才能作赋，吾怜短发未攲冠。","明良一代赓歌盛，礼乐千年复古难。","即拟泰坛陈藁秸，早闻阊阖献琅玕。"]},{"t":"九日天坛登集酬夏桂洲都谏 其二","f":"七言古诗","c":["八座轩裳吟对酒，佳辰此会若为欢。","凤飞正借高梧近，鹏运真同碧海宽。","青枫极浦遥连影，细菊重岩巧缀团。","桓孟高风追落帽，夔龙胜集庆弹冠。","层城烟雾将归远，郢曲阳春欲和难。","莫把茱萸问谁健，共看颜色比琅玕。"]},{"t":"陵祀奉简闻司寇唐中丞","f":"七言律诗","c":["秋日野晴朝露晞，六陵如黛净烟霏。","村原几处临寒水，台殿千重锁翠微。","频来古寺能留榻，久客缁尘欲化衣。","西省内台俱重望，叨陪鹓序有光辉。"]},{"t":"泰陵果园夕憩感述","f":"五言律诗","c":["泰园众峰里，冬晴雪树稀。","宫监栖岩翠，山禽下夕晖。","攀髯悲隔世，种木见成围。","怅忆临轩日，瞻天泪暗挥。"]},{"t":"陵祀夜归","f":"五言古诗","c":["繁星攒列炬，流尘起飞鞚。","绕树远钟微，沾衣零露重。","回望碧山椒，山深夜寂寥。","云舆归缥缈，玉殿锁岧峣。","重泉光景匿，蔓草蛩声唧。","唯有朝陵使，年年来此夕。"]},{"t":"昌平学宫傍有刘谏议祠翰林诸寮陵祀则寓止祠下予昔备员史官尝两至焉追忆旧游简吴学士王徐二太史 其一","f":"五言律诗","c":["瀛馆虚尘榻，香灯伴古祠。","衣冠秋祀到，风节里贤思。","堂近栖鸾树，泉分采藻池。","俊僚来衮衮，仍续旧题诗。"]},{"t":"昌平学宫傍有刘谏议祠翰林诸寮陵祀则寓止祠下予昔备员史官尝两至焉追忆旧游简吴学士王徐二太史 其二","f":"五言律诗","c":["谢公墩尚在，贾传井依然。","问讯祠前柏，怀予系马年。","并游看玉树，分直想金莲。","巳是仙凡隔，衰庸愧后贤。"]},{"t":"清河村舍与闻唐二公小酌","f":"七言律诗","c":["十里清河去未遥，暖烟秋色过枫桥。","柳条惊风故零乱，茆屋枕溪还寂寥。","谁家砧杵敲寒练，客子风尘换敝貂。","乘兴且倾黄菊酒，还家须忆紫宸朝。"]},{"t":"送林石崖都宪","f":"七言律诗","c":["中丞出镇在扶风，共说登台两世同。","天语宣廷催拥传，霜威满路避乘骢。","簪缨独继家声贵，斧钺荣兼节制崇。","宵旰忧勤问民瘼，几回书奏大明宫。"]},{"t":"赠陈都帅","f":"五言古诗","c":["平生仗奇节，感激与谁论。","报主丹心切，参戎伟绩存。","营锋百阵合，漕粟万舟屯。","受诏辞皇邑，驱车还里门。","龙泉别壮士，春草忆王孙。","闻有飞章荐，重来谒至尊。"]},{"t":"赠王太常之闽藩","f":"七言律诗","c":["未论海峤与宸居，同是君恩感激馀。","地僻云霞三岛近，官清琴鹤一舟虚。","省薇昼永消炉篆，山荔风香引传车。","知尔兹行暂分手，即看宣拜紫泥书。"]},{"t":"夏学士荣赐犀带并手敕褒谕贺以是诗","f":"七言律诗","c":["赐犀新宠冠朝行，飞白宸奎照玉堂。","霄汉渥恩承湛露，琐闱清论满朝阳。","君臣合契同鱼水，廊庙抡材有栋梁。","留与词林传盛事，要知明主重惟良。"]},{"t":"奉和序翁先生从游西苑视谷","f":"七言律诗","c":["行宫别殿接严宸，诏赐同游禁苑春。","龙渚泛舟呼力士，御厨分膳辍饔人。","阳和茂对皇情豫，云汉昭回圣藻新。","政以艰难知稼穑，共言鱼水喻君臣。"]},{"t":"奉诏陪祀谷祗坛西苑游瞩汎舟太液和亭溪学士 其一","f":"七言律诗","c":["祗坛奠璧晓光初，法驾临畴宿雨馀。","幕近炉烟浮羽仗，林晴花色上簪裾。","身逢广乐钧天盛，世际淳风太古如。","农亩起家陪帝籍，江乡春事忆郊居。"]},{"t":"奉诏陪祀谷祗坛西苑游瞩汎舟太液和亭溪学士 其二","f":"七言律诗","c":["仙居春汎渺银河，桃杏红芳水绿波。","日出芙蓉开帐殿，风回笙吹绕云萝。","汀洲凫藻荣光满，楼阁烟花淑景多。","不是传宣承帝泽，岂缘天路得经过。"]},{"t":"赠管银台","f":"五言律诗","c":["奉使持天节，宁亲捧寿杯。","传车寒色送，歌吹夕阳催。","驿傍河津转，关迎陇月开。","留欢犹未尽，计日汉庭回。"]},{"t":"赋练塘卷李御史父","f":"五言律诗","c":["悠然练塘上，拂榻坐清风。","绿树重于盖，澄流映若空。","鱼来深石下，鸟度夕阳中。","独有乘骢客，看云忆甬东。"]},{"t":"初入铨曹 其一","f":"五言律诗","c":["肃穆堂阶迥，阴森柏桧齐。","吏人依鹤立，乌雀傍林栖。","水镜悬清鉴，丝纶照紫泥。","天曹元峻绝，何意得攀跻。"]},{"t":"初入铨曹 其二","f":"五言律诗","c":["炉篆销寒昼，濡毫削奏书。","多惭华省贵，秪拟列仙居。","心结壶冰里，恩垂雨露馀。","如何报明主，荐士满公车。"]},{"t":"赴任南礼部九卿会饯于万福庵次韵留别 其一","f":"七言律诗","c":["五云回首望宸宫，感激皇恩覆载同。","身比马牛难报主，心随江汉亦朝宗。","镐丰故拟周京重，礼乐亲知舜典崇。","自是臣劳均出入，岂将鸿迹叹西东。"]},{"t":"赴任南礼部九卿会饯于万福庵次韵留别 其二","f":"七言律诗","c":["星轺驻节倚禅宫，祖席登筵八座同。","禁苑鸳鸾劳送远，留都礼乐愧称宗。","正逢春郭烟花丽，更屈天卿礼数崇。","巳隔长安辞日下，独看云树赋江东。"]},{"t":"过东昌寿学士许龙石先生尊翁九十","f":"五言古诗","c":["地是登瀛里，春当献寿辰。","凤书擎诰重，鹇锦制袍新。","禄待千钟养，天扶百岁身。","古松仍偃蹇，老鹤倍精神。","榴色侵琼斝，椿阴上绣茵。","欲知恩庆远，东海正无垠。"]},{"t":"安山待闸","f":"五言律诗","c":["客思去匆匆，川程渺未穷。","水生波荡漾，日出景冥濛。","花发当春树，舟牵逆浪风。","颇觉征途倦，情非少壮同。"]},{"t":"晓行南湖寄友","f":"五言律诗","c":["远树犹含雾，澄流欲飐空。","帆樯飞鸟外，箫鼓曙烟中。","映带江林出，萦回岛屿通。","无因寄相忆，春草正蒙茸。"]},{"t":"重经石佛闸望岸傍阁而赋之","f":"七言律诗","c":["梵阁临江记昔攀，白云苍桧锁禅关。","波澜极浦浮高栋，雾霭疏林出断山。","尽日帆樯经树杪，早时钟鼓落人间。","尘劳未息堪惆怅，又送官航此路还。"]},{"t":"将至徐州风阻野泊闻陈水部拿舟来会作此寄之","f":"七言律诗","c":["津程望近转离忧，高浪烟汀阻宿留。","剡渚正怜人独往，春山真忆鸟相求。","云飞沛里风仍起，江绕黄楼水自流。","闻说冬曹新政好，极知才是济川舟。"]},{"t":"徐州陈水部萃墨亭留题","f":"五言古诗","c":["高浪轩中沸，层楼画里开。","浦云千嶂合，漕粟万艘来。","墨萃刊亭石，风歌上沛台。","树连平野尽，江逐古营回。","舐泽烟霞改，桓山松柏哀。","莫倚登檈赋，还资理国才。"]},{"t":"夜至淮阴中丞刘公临访遂宴台院","f":"五言律诗","c":["凫渚风灯乱，传呼绣斧来。","那知维月舫，更得近霜台。","披豁闻高论，将明仰上才。","华觞春漏永，怀抱故须开。"]},{"t":"宴张总戎宅","f":"五言律诗","c":["棨戟元戎第，文觞得暂过。","鸟吟春树遍，花映夕堂多。","家世张车骑，勋名马伏波。","淮洲见明月，其奈别离何。"]},{"t":"杨州别邓太仆以正因寄玄庵穆学士","f":"五言律诗","c":["养拙惭吾道，兹行偶共君。","长途欣并舫，此路惜离群。","树隐烟中郭，帆飞海上云。","因声寄玄老，公暇好论文。"]},{"t":"泛鸳湖","f":"古风","c":["楼榭开烟雾，汀洲似画图。","城阴度?窱，天影入虚无。","岸迥传清吹，波深洗玉壶。","兹辰春日好，留兴在鸳湖。"]},{"t":"谒孝陵 其一","f":"五言律诗","c":["翠巘皇陵閟，青松石道长。","百灵罗象卫，五位备冠裳。","龙剑风尘靖，罗图日月光。","山空飙吹急，萧飒动宫墙。"]},{"t":"谒孝陵 其二","f":"五言律诗","c":["社稷戎衣起，梯航玉帛朝。","睹河功戴禹，瞻庙祀宗尧。","石马嘶空翠，金灯照寂寥。","遥看钟阜上，御气满层霄。"]},{"t":"南宫初上 其一","f":"五言律诗","c":["谬忝文昌入，虚惭礼乐司。","居当分陕地，荣及履星时。","位重才非称，恩深报未知。","愿奉惟寅训，还陈匪懈诗。"]},{"t":"南宫初上 其二","f":"五言律诗","c":["爽气澄秋朔，朝光动省闱。","竹风来锦席，花雾上朱衣。","北斗跻衡峻，南曹领务稀。","圣明谟典在，万世敢愆违。"]},{"t":"送何司空","f":"五言律诗","c":["冬曹公报政，钟阜我移官。","傍树开新筑，临觞叙旧欢。","宦途劳涉历，世泽盛衣冠。","岂乏春华好，青松耐岁寒。"]},{"t":"赠潘吏侍入觐","f":"五言律诗","c":["少宰今时望，风仪八座看。","留曹称水镜，北阙待鸳鸾。","振舄秋尘净，登车晓月寒。","同年满朝署，相见庆弹冠。"]},{"t":"顾户侍考绩补赠","f":"五言律诗","c":["民部知名久，清朝最老成。","松当云壑古，冰贮玉壶清。","国计分留署，秋帆上帝京。","赠言惭我后，叨此继同声。"]},{"t":"序翁相公惠寄对月见怀之作依韵拜酬","f":"七言律诗","c":["远传仙翰到南宫，安得清光此夕同。","气味敢云兰并臭，瞻依真以岱为宗。","冰衔宠带铨衡重，衮席荣跻殿阁崇。","共贺太平今有象，德星环聚五云东。"]},{"t":"留都诸司拜进元旦贺表仆忝官礼曹当职题署摄事讫敬识一诗","f":"七言律诗","c":["表函遥贺谨题封，黄袱亲缄献九重。","下土葵心惟向日，丹霄云气总成龙。","青阳启律欢称寿，紫禁趋班忆听钟。","八座二京分职事，涓埃无补愧登庸。"]},{"t":"金陵城西泛舟太宰刘公邀集","f":"七言律诗","c":["叠嶂澄江绕帝州，金尊锦席在兰舟。","正逢吏散轩裳集，况是郊晴雾雨收。","隔岸帆樯迷浦溆，傍城楼阁带林丘。","名都胜槩还今赏，赤壁高阳空昔游。"]},{"t":"观音山燕矶临眺","f":"七言律诗","c":["高云石壁相因依，侧倚莲宫临燕矶。","画栋岩峦开险绝，沧州烟树隐霏微。","鲸鳌吹浪三山动，帆舶乘风万里归。","日晚川长堪怅望，天青无尽雁孤飞。"]},{"t":"观音山次紫岩太宰 其一","f":"七言律诗","c":["危栏高栋俯江深，萝径松门胜可寻。","祗苑白云生静思，石溪红叶动秋吟。","遥岑不改鸿濛色，清啸如传鸾凤音。","轩盖拥林钟磬发，山僧应记宰官临。"]},{"t":"观音山次紫岩太宰 其二","f":"七言律诗","c":["天末长云逐雁来，江间波浪起孤台。","初晴风日邀登阁，胜地山河对举杯。","著帽山公期取醉，挥毫李白故称才。","极知人世閒情少，多谢霜前白菊开。"]},{"t":"观梅花泉同紫岩太宰","f":"七言律诗","c":["闻道幽香临绝涧，偶寻遗迹一相过。","风前雪树花难觅，岩上镌题字半磨。","苔径客行青嶂远，石堂僧占自云多。","尘骖此地应稀到，洞口年年长薜萝。"]},{"t":"牛首寺","f":"七言律诗","c":["绝嵿双峰天阙开，禅房幽洞锁莓苔。","岩峦路转孤云近，松柏风生万壑哀。","当日翠华临别殿，千年威凤起层台。","细观惟有阶前树，历尽人间累劫灰。"]},{"t":"晓登朝天宫西阁集宴还坐东麓亭有作","f":"七言律诗","c":["江郭晴烟翠且重，山城紫阁坐高峰。","杯前木落萧萧影，天外鸿归渺渺踪。","御气尚浮宫苑树，寒声遥送石门钟。","偶寻玄圃逢瑶草，拟接丹霞访赤松。"]},{"t":"和浚川大司马","f":"七言律诗","c":["雾阁云窗拂曙开，白沙青嶂绕城回。","鼋鼍浴日江光动，龙蜃嘘空海气来。","万事纠纷堪息驾，百年佳胜偶登台。","运筹作赋公能事，莫厌频来把酒杯。"]},{"t":"和紫岩太宰","f":"七言律诗","c":["仙家楼阁隐嵯峨，丽景祥烟入槛多。","剑失正怜龙久化，台空犹忆凤曾过。","冶城遗事遥难问，卞庙精忠耿未磨。","风物岂殊桃洞宴，阳春重和郢中歌。"]},{"t":"和久庵少宗伯","f":"七言律诗","c":["袅袅高云覆阁阴，冥冥宿雾映江深。","丛篁暄带林烟碧，独雁寒随浦树沉。","天上楼台堪怅望，水边亭槛足幽寻。","共来佳丽金陵地，重对樽前谢眺吟。"]},{"t":"和筠溪少司马","f":"七言律诗","c":["冬日邀宾东麓阁，冻云檐日共凄凉。","天连一水蒹葭净，霜落千林橘柚黄。","暂对碧山心自逸，独攀琼树意何长。","风烟远目增幽思，身病逢欢亦尽觞。"]},{"t":"大祀斋居 其一","f":"五言律诗","c":["省阔南宫静，台阶北斗齐。","露承金掌近，天傍玉绳低。","院寂人稀语，松高鹤对栖。","旧编閒自校，窗火照青藜。"]},{"t":"大祀斋居 其二","f":"五言律诗","c":["坐漏频移榻，听钟更振衣。","月疑开宝扇，云忆闪朱旂。","礼乐今周祀，河山旧汉畿。","翠华天北极，遥仰六龙飞。"]},{"t":"大祀斋居 其三","f":"五言律诗","c":["露笋分朝馔，炉沉换夕薰。","地严增阒寂，味澹谢芳荤。","澄汉悬珠斗，层霄驻彩云。","百辟同明德，千春奉圣君。"]},{"t":"大祀斋居 其四","f":"五言律诗","c":["忝窃纡朱绂，栖迟记玉堂。","钟陵山上月，重此对清光。","白日看驹隙，青云愧鹭行。","所嗟心寸草，何以报春阳。"]},{"t":"斋居奉同久庵寅长纪赠 其一","f":"七言绝句","c":["松柏高姿兰蕙薰，茆斋北郭旧论文。","宁非夙世神仙侣，华省青精更对君。"]},{"t":"斋居奉同久庵寅长纪赠 其二","f":"七言绝句","c":["叔度令予鄙吝消，英词往往奏英韶。","文章巳见追前古，礼乐还应翊圣朝。"]},{"t":"寄赠钟石翰长 其一","f":"七言绝句","c":["咫尺南宫近木天，羡君官府是神仙。","鸾凰会整青霄翼，山水还留白雪篇。"]},{"t":"寄赠钟石翰长 其二","f":"七言绝句","c":["玉署清衔直似冰，文章南斗价逾增。","古槐脩竹清阴里，散帙谈诗记我曾。"]},{"t":"寄赠介立旧寅长","f":"七言律诗","c":["学省清游易岁年，留台重望借才贤。","鹓鸾故集丹山树，奎壁还联紫极天。","麟阔石渠须制作，碧山沧渚寄延缘。","怀人正有停云思，抚景空弹白雪弦。"]},{"t":"次紫岩太宰斋居韵 其一","f":"七言律诗","c":["遥想泰坛燔璧夜，彩云晴护帝城春。","帷宫御气临黄屋，阁道炉烟上绣茵。","翠管银罂沾泽旧，椒花柏叶献年新。","留曹自是均劳地，珍重台衡报主身。"]},{"t":"次紫岩太宰斋居韵 其二","f":"七言律诗","c":["省阁松阴动日华，仙卿高咏兴无涯。","正逢山翠开书幌，拟近池波著钓槎。","阊阖北云频望阙，烟花南国更移家。","甘盘旧学留宸眷，早晚徵纶拜宠嘉。"]},{"t":"次费学士斋居","f":"七言律诗","c":["玉堂幽事镇相关，雪茗云篇兴未悭。","春槛烟花迷紫禁，夕帘苍翠满钟山。","纶闱世掌看新命，讲殿晨趋忆旧班。","见说天庭起黄色，北扉应待凤书颁。"]},{"t":"次胡太常斋居","f":"七言律诗","c":["容台斋祓静炉薰，江郭晴烟霭瑞氛。","自识仙曹堪隐吏，偶过僚署喜论文。","海中鹤驭通三岛，天上彤楼丽五云。","邻并最欢依玉树，别来三日倍思君。"]},{"t":"予昔在翰林礼部杨月湖汪閒斋二先生斋居邀予诗会今二公已下世矣感旧述情而题此句","f":"七言绝句","c":["剑水烟云宝气消，龟峰猿鹤巳难招。","读罢旧题空泪落，省闱风竹晚萧萧。"]},{"t":"至日群公集灵谷寺 其一","f":"七言律诗","c":["青霞宿雾净朝阴，长笛洞箫悲远林。","云窦泉流一壑静，石门路入万松深。","回廊古壁留名画，坠叶冷风助梵音。","此地岩峦足幽胜，岁时携酒一登临。"]},{"t":"至日群公集灵谷寺 其二","f":"七言律诗","c":["至日上方吟送酒，尽看鸾鹤在烟霞。","阳回嶰谷时方泰，山绕钟陵境自嘉。","林下幽香逢蕙草，水边春信见梅花。","习池宾客今名胜，转觉风流兴未涯。"]},{"t":"灵谷寺次浚川大司马韵","f":"七言律诗","c":["深冬翠壑尚春姿，八座舆骖共此时。","今代珠林开净境，千年金塔礼真师。","泉边倚榻逢僧话，树底穿云避鸟知。","莲社虎溪俱胜事，不妨重作后游期。"]},{"t":"次久庵少宗伯","f":"七言律诗","c":["上方台殿耸岧峣，望近松门路转遥。","山抱玉陵增气色，磴盘琪树入云霄。","岩花当日迎龙驭，涧水千年落凤韶。","林下志公呼不起，空馀遗事说梁萧。"]},{"t":"晨经凤台门","f":"五言律诗","c":["台凤久寂寞，门今尚得名。","岗峦拔地峻，竹树带烟晴。","寒日一以眺，白云空复情。","万峰天外色，二水抱神京。"]},{"t":"登雨花台","f":"五言律诗","c":["雨花朝独上，寒望尽皇州。","猎猎海风至，冥冥江雾流。","楼台开秘苑，城郭枕高丘。","今古浮云色，长歌寄此游。"]},{"t":"过永宁高座二寺","f":"五言律诗","c":["永宁峰寺僻，高座亦为邻。","曲径无人到，云松自可亲。","异花飘法界，幽草发新春。","安得遗尘事，林中结净因。"]},{"t":"送司空秦公赴召 其一","f":"七言律诗","c":["又看冬省承优诏，更折春梅送别筵。","江寺劝杯曾对雪，凤楼鸣玉再朝天。","舟经故里迂仙棹，衣近金炉上御烟。","想到禁庭多雨露，一时卿望尽才贤。"]},{"t":"送司空秦公赴召 其二","f":"七言律诗","c":["十年钟阜重游地，正喜从公柰别何。","垂老再逢宣室召，祖筵犹唱渭城歌。","南宫昼接天颜近，西苑春祠水树多。","周历五曹谁得似，圣朝勋业看嵯峨。"]},{"t":"赠士鸣年兄","f":"五言律诗","c":["簪盍欣相倚，其如此别何。","江湖忧思在，霄汉盛名多。","暮渚吟蘅杜，春山隐薜萝。","赐环知有日，行矣养天和。"]},{"t":"金陵岁夜 其一","f":"七言律诗","c":["旧都遗俗是升平，又听盈门鼓吹声。","柏酒竞传知腊味，土牛初献识春耕。","万家梅柳开烟市，双阙星河隐凤城。","萍海客游今老大，自惭癯质玷华缨。"]},{"t":"金陵岁夜 其二","f":"七言律诗","c":["朮炉松火照春城，夜雪寒灯对旧京。","霜鬓暗催人易老，天涯独宿梦难成。","因怀泉石违初志，愧乏涓埃答圣明。","烧竹引杯聊饯岁，望乡瞻阙总关情。"]},{"t":"乐道吟","f":"五言古诗","c":["朱邸神仙馆，芸窗翰墨林。","简编求至理，泉石散幽襟。","点瑟声靡间，颜瓢味可寻。","独攀丛桂隐，时对白云吟。","鍊气餐霞液，斋心玩兔阴。","东平为善意，千载嗣徽音。"]},{"t":"东园灯宴","f":"五言律诗","c":["芳节谁招宴，东园公子家。","瓮浮千日酿，灯灿九枝花。","林榭凝歌吹，楼台满月华。","习池风景异，留赏未云赊。"]},{"t":"赠参赞王公浚川","f":"七言律诗","c":["圣明留钥付元臣，位重南都领缙绅。","身系安危称大老，道弘风雅作诗人。","指麾貔虎千营静，苏息疮痍万户春。","共道政成催入辅，汉家勋业待麒麟。"]},{"t":"哭东井内兄 其一","f":"七言律诗","c":["才沾除目便终身，襆被囊书秪旧贫。","新授景陵山县长，晚登京兆贡科人。","剩闻行义称乡党，每见文章重缙绅。","天道茫茫那可问，伤心归榇暮江滨。"]},{"t":"哭东井内兄 其二","f":"七言律诗","c":["二年京国走红尘，客舍相依意自亲。","往事恍疑春作梦，浮生空忆幻为身。","可怜丹旐题新秩，谩说乌纱换旧巾。","铜绶向来消不得，纡朱拖玉是何人。"]},{"t":"上陵作","f":"五言律诗","c":["十载朝陵路，重来识翠微。","听泉经石涧，攀柏候金扉。","麛鹿能迎客，山云故上衣。","那能不老大，旧侣觉全稀。"]},{"t":"宿鸡鸣山","f":"五言绝句","c":["寺峰云雾里，重借石堂眠。","犹似当年到，灯悬古佛前。"]},{"t":"省中元会","f":"五言古诗","c":["献岁三阳泰，祝圣万方欢。","卿云朝气合，繁星夜炬攒。","延阁绵钟漏，华省肃鹓鸾。","金塘初变柳，玉砌巳舒兰。","秩礼崇元化，备职忝春官。"]},{"t":"元旦孝陵陪祀","f":"五言律诗","c":["玉殿中峰里，烟开雪树春。","盘乌栖露静，涧鹿向人驯。","弓剑陵园閟，旒衣岁日陈。","万年周鼎地，奔走备王臣。"]},{"t":"元日久庵少宗伯九峰太常集饮","f":"七言律诗","c":["竹烟松雪散馀寒，蓂荚桃符庆履端。","天地万年吾道泰，阳和四海圣恩宽。","增龄更藉椒觞劝，应俗先传綵胜看。","喜并德邻能枉驾，正依云阙共弹冠。"]},{"t":"钤山御书楼成自述短诗 其一","f":"七言律诗","c":["楼成东圃定何如，缃帙牙签尽赐书。","延眺巧当山色处，对扬荣荷圣恩馀。","三春花气薰兰芨，五夜虹光映斗墟。","留与后人传世泽，要知经训是菑畬。"]},{"t":"钤山御书楼成自述短诗 其二","f":"七言律诗","c":["十载虚叨列近臣，宝函宸翰拜恩频。","云霞捧出天家制，琬琰藏为奕世珍。","万古江山开栋宇，百年忠孝报君亲。","愿将天保歌周历，夜傍奎躔礼北辰。"]},{"t":"钤山御书楼成自述短诗 其三","f":"七言律诗","c":["頖邻松竹是吾庐，廿载辛勤此卜居。","山近云烟浮几案，门深宾从拥轩车。","敢将新构誇仑奂，但愿淳风挹里闾。","他日若论归老计，邺侯惟有满家书。"]},{"t":"题顾中丞山居 其一","f":"五言律诗","c":["城居厌烦郁，遥在碧山栖。","石径云俱静，松窗路转迷。","到来峰历历，吟处草萋萋。","我忆闻高论，春醪远为携。"]},{"t":"题顾中丞山居 其二","f":"五言律诗","c":["桃树仙人宅，春山不可寻。","偶随芳草去，言到白云深。","片月窥萝幌，啼莺绕竹林。","亦知难久卧，四海望为霖。"]},{"t":"和太宰紫岩送春四首 其一","f":"七言绝句","c":["风晴芳絮萦书幌，日晚馀花照酒卮。","传语吏人休白事，宰公方咏送春诗。"]},{"t":"和太宰紫岩送春四首 其二","f":"七言绝句","c":["江寺花枝开不稀，背岩幽渚斗芳菲。","东君有意如相惜，莫遣风吹片片飞。"]},{"t":"和太宰紫岩送春四首 其三","f":"七言绝句","c":["未因春别恨匆匆，酌酒看花兴转浓。","闻说郭西花更好，与公同上最高峰。"]},{"t":"和太宰紫岩送春四首 其四","f":"七言绝句","c":["便买春醪日典衣，及时行乐莫相违。","白鹭洲前宁久驻，紫薇红药待公归。"]},{"t":"寄欧从龙侍御","f":"七言绝句","c":["壮心黄鹄青冥上，旧业苍山楚水南。","谁道向来经济略，种畬栽树伴农谈。"]},{"t":"致政刘光禄偶见遂别赋赠","f":"七言律诗","c":["碧山高榻卧清风，几许音书渺未通。","旧日绨袍仍恋恋，百年尘路苦匆匆。","华轩滥处真惭鹤，世网难羁独羡鸿。","明日吟诗向何处，白云江上倚孤蓬。"]},{"t":"送黄少司徒","f":"七言律诗","c":["去国十年仍赴召，遭逢今睹汉仪新。","烟花对酒留春棹，剑佩冲星上紫宸。","馆中朋辈谁同在，白下交期我重亲。","台省故人如见问，为言閒僻称吟身。"]},{"t":"寄寿张允敬同年","f":"五言律诗","c":["吾爱张平子，餐霞东海阴。","异方仙客授，高行里人钦。","久税林中驾，弥清尘外心。","无因介眉寿，远寄鹤飞吟。"]},{"t":"寄题欧侍御碧溪草堂","f":"七言律诗","c":["柱史溪堂何处寻，石潭沙岛静阴阴。","扁舟客到柴门近，芳树莺啼草屋深。","霜简皂囊酬夙志，渚兰汀芷寄閒心。","濯缨拟和沧浪曲，抱膝还为梁甫吟。"]},{"t":"题石滩卷","f":"五言律诗","c":["吾爱石滩子，为赋石滩吟。","云波晴泻练，风濑暗鸣琴。","澹逸凫鸥侣，青苍枫栝林。","尘缨何日濯，访尔草堂深。"]},{"t":"石川诗为婺源汪子赋汪子思亲所尝游也","f":"五言古诗","c":["羲驭无停辔，川流靡回波。","朝见枝上花，暮观叶辞柯。","伊昔亲在时，杖屦此婆娑。","奄忽逝如期，忍赋诗蓼莪。","极浦菱荷发，清澜凫雁多。","向来钓游处，白石横秋萝。","憩石复怀川，揽涕伤如何。"]},{"t":"送盛程斋都宪 其一","f":"七言绝句","c":["欲寻东海黄金灶，仍向罗浮碧玉峰。","人世尘劳知已息，仙山灵药会相逢。"]},{"t":"送盛程斋都宪 其二","f":"七言绝句","c":["银鱼锦豸承恩日，绿水丹山归隐时。","逍遥且喜从吾好，宠辱由来非我知。"]},{"t":"送胡司寇","f":"七言绝句","c":["长干寺里几回来，折柳寻花醉此回。","同榜四人公复去，后期何地更衔杯。"]},{"t":"奉送浚川王公赴召 其一","f":"五言律诗","c":["皇构须梁栋，天逵侍凤鸾。","圣衷劳侧席，时望切弹冠。","霄汉恩波近，江湖别路漫。","所嗟从教远，长展卷诗看。"]},{"t":"奉送浚川王公赴召 其二","f":"五言律诗","c":["雄峻称三独，清忠仰百寮。","天书新宠渥，霜署旧风标。","威振台纲肃，春行郡国遥。","向来经济望，好答圣明朝。"]},{"t":"紫岩刘公参赞留务贺赠","f":"七言律诗","c":["玉堂延阁旧儒仙，华省三台次第迁。","待入凤池司帝制，暂持龙节掌兵权。","寰区人物甄陶内，建业山河控制前。","共道全才齐吉甫，早闻功德格皇天。"]},{"t":"王银台北上识别 其一","f":"七言律诗","c":["移官来共秣陵居，每诵清诗叹起予。","晚岁欲谐金石契，新恩重下紫泥书。","骅骝逸步谙长道，鹓鹭崇班上玉除。","蓟北江南相忆否，还将尺素付双鱼。"]},{"t":"王银台北上识别 其二","f":"七言律诗","c":["长安里第似幽居，水石流传亦到予。","芳会更移泉上酌，旧题多认竹间书。","能留嘉荫棠堪憩，谩适閒心草未除。","君去好随天阙凤，吾衰终钓楚江鱼。"]},{"t":"题晏守备画","f":"七言律诗","c":["汲泉抱瓮谁家妇，伐岭负薪何处翁。","要识民间贫苦事，此图长置此堂中。","当午锄禾妇子同，力田心只愿年丰。","人间最苦惟农事，看取豳诗七月风。"]},{"t":"送大司寇周公致政","f":"七言律诗","c":["海东归驾杳难攀，松桂清阴满旧关。","老境正逢开口笑，畏途谁得乞身还。","花边曳杖吟随鹤，湖上移舟坐看山。","簪笏有人能继美，恩波长在五云间。"]},{"t":"九日金陵城西泛舟同顾中丞 其一","f":"七言律诗","c":["蘋洲荻浦水云长，素舸筠帘冰雪光。","霞气入江明岛屿，浪花沾席净琴觞。","伴人泛泛鸥何逸，媚石辉辉菊自芳。","非是龙山吹帽客，还将幽意寄沧浪。"]},{"t":"九日金陵城西泛舟同顾中丞 其二","f":"七言律诗","c":["龙河西渚石城隈，九日风烟霁色开。","帝苑楼台云里见，澄潭凫雁镜中回。","青溪渡转桥横木，朱雀航空月映苔。","千古风流今独胜，中丞与客泛舟来。"]},{"t":"陈中丞年兄升大理卿赠别","f":"七言律诗","c":["卿月昭回入紫微，法星迢递别南圻。","江波共惜仙帆远，台路争看绣斧归。","松柏晚当冰涧立，鹓鸾春傍禁城飞。","江东云树遥相忆，榜下同年太觉稀。"]},{"t":"赠陈虞山中丞之南赣","f":"七言律诗","c":["清献祠前秋水清，郁孤台上暮云平。","江关粤峤开雄镇，玺敕兵符借老成。","正以冰霜论节操，须知鱼鸟避威名。","天南旧路君应识，惟喜梅花管送迎。"]},{"t":"大司马刘公宅翰林诸寮修瀛洲之会限韵得诗四首 其一","f":"七言律诗","c":["钟山晴对草堂青，胜日芳筵更此庭。","花雾竹烟笼气色，汉雍唐省备仪形。","直令浑噩追三代，坐见文章侣六经。","却忆北扉供奉日，几回钟漏候明星。"]},{"t":"大司马刘公宅翰林诸寮修瀛洲之会限韵得诗四首 其二","f":"七言律诗","c":["十年重见柳条青，剩水残山旧所经。","胜会正看鹓作侣，瘦躯翻讶鹤同形。","情娱尊俎堪移日，地远江湖漫聚星。","食饱事閒兼吏隐，不知何以答虞庭。"]},{"t":"大司马刘公宅翰林诸寮修瀛洲之会限韵得诗四首 其三","f":"七言律诗","c":["菊丛橙实竞寒青，客舍钟陵岁几经。","玉署俊游论接武，金兰交契到忘形。","盍簪琼树罗玄圃，张乐泠风起洞庭。","巳报泰阶呈国瑞，夜阑搔首望天星。"]},{"t":"大司马刘公宅翰林诸寮修瀛洲之会限韵得诗四首 其四","f":"七言律诗","c":["烹茶烧竹坐谈经，正爱清香满户庭。","赖有琴觞能遣俗，都无案牍可劳形。","上林梧竹栖群凤，东壁文章纪二星。","他日汉家麟阁上，愿期勋业在丹青。"]},{"t":"答潘石泉年兄见赠","f":"七言律诗","c":["尘壒驱驰愧我形，鬓衰非复旧时青。","偶随冠佩登仙署，未有涓埃报帝庭。","省阁优閒无吏牍，山川名胜有图经。","江湖敢替忧君念，夜夜频瞻紫极星。"]},{"t":"院堂之集予以病不赴次韵答诸公","f":"七言律诗","c":["玉堂开宴劝杯宽，彩笔题诗洒墨乾。","绕槛山围锦绣障，过檐竹长凤凰竿。","旧游梦忆仙曹隔，雅会身惭病祟干。","八座轩裳俱俊望，蒹葭那得倚琅玕。"]},{"t":"大司成陆公枉驾钤山草堂予远寓金陵无缘攀迂感别增情作此寄谢次原韵 其一","f":"七言律诗","c":["鳌禁儒山薇省使，近传旌节过林丘。","青苔地僻无人扫，翠竹天寒可自留。","想复移丹空对雪，谁能载酒共登楼。","为吟佳句增惆怅，目极孤云楚水头。"]},{"t":"大司成陆公枉驾钤山草堂予远寓金陵无缘攀迂感别增情作此寄谢次原韵 其二","f":"七言律诗","c":["浦东我昔登公堂，岂意公犹度我乡。","海内交游同骨肉，天涯涕泪各参商。","关山落日云千嶂，河汉怀人水一方。","冰玉丰神鸾凤羽，百年愚俗借馀光。"]},{"t":"大司成陆公枉驾钤山草堂予远寓金陵无缘攀迂感别增情作此寄谢次原韵 其三","f":"七言律诗","c":["攀留能爱小山丛，此日相过似梦中。","萍海漫怜身作客，杏园俱忆鬓成翁。","多惭华省迂高驾，可笑贫家只素风。","想见江山入题品，玉堂椽笔是宗工。"]},{"t":"送大理周公赴召","f":"五言律诗","c":["亭晚离尊集，波晴锦缆开。","使旌移北斗，卿月近西台。","奏谳平天宪，登延简上才。","宁知湘水客，重睹汉庭来。"]},{"t":"送张中丞赴召北台张旧以翰林例出补外乃独有今召","f":"七言律诗","c":["旧日并辞金马客，天书荣召似君稀。","独怜一鹤归瀛岛，却领群星入太微。","西台执法摇霜笔，东掖趋朝著豸衣。","共说为儒堪重寄，益看吾道有光辉。"]},{"t":"会林介立先生宅限韵","f":"七言律诗","c":["眼中世事何多虞，置酒高堂聊宴娱。","衣冠朋辈几寥落，风雨林花半有无。","生人情致向所似，炯炯清冰涵玉壶。","愧予寮寀平生分，迟尔云霄万里途。"]},{"t":"赠林大理次崖 其一","f":"七言绝句","c":["廷尉平反力有馀，昼帘朱墨更忘劬。","存疑遍示诸生录，传信新刊两寺书。"]},{"t":"赠林大理次崖 其二","f":"七言绝句","c":["芹曝犹堪献至尊，皇王治道有新论。","汉庭帝鉴明如日，次第还行贾谊言。"]},{"t":"入省十四韵","f":"五言古诗","c":["斗极三辰峻，天曹六职先。","官为岩石地，政自祖皇年。","定鼎乾坤辟，开堂水镜悬。","百司存法守，一敬启心传。","驽蹇惭非据，鸿私荷再迁。","两都仍践历，孤迹寡阶缘。","天日逢明后，璠玙浼隽贤。","吹竽容窃滥，推毂广登延。","每切循墙惧，方叨涖席专。","敢期攀凤羽，荣得上星躔。","斋阁山如画，留都境若仙。","帘垂钟阜月，鸦散石城烟。","簿领频多暇，寅恭敢怠虔。","惟应论晚节，松柏誓同坚。"]},{"t":"司徒许公宅修瀛洲之会限韵二首 其一","f":"七言律诗","c":["瀛岛书传白鹤先，佳辰展席对江天。","官梅东阁催诗兴，客舍并州感岁年。","尝果味分霜后橘，烹茶香泛竹间泉。","杏园绘事风流在，此会他时合共传。"]},{"t":"司徒许公宅修瀛洲之会限韵二首 其二","f":"七言律诗","c":["肴出驼峰酒送泉，新诗珠玉尽堪传。","空江木落年华晚，幽树梅开淑气先。","钟阜移尊聊此夕，玉堂载笔是何年。","司徒门第今韦杜，时论真同尺五天。"]},{"t":"省中斋宿呈同寅潘公年丈 其一","f":"七言律诗","c":["大祀恭传帝命先，两人联宿省堂年。","浮葭淑气初回琯，燔璧荣光远烛天。","槛近静移苍桧月，亭空寒浸碧池泉。","连宵促席闻佳话，茗碗蔬盘得共传。"]},{"t":"省中斋宿呈同寅潘公年丈 其二","f":"七言律诗","c":["萧萧林叶坠高庭，寂寂窗灯隐幕青。","画省竹松仍坐漏，紫坛冠佩尽冲星。","圣明礼乐追三代，薄劣遭逢起一经。","清庙告成当有颂，黄虞致化本无形。"]},{"t":"省中池亭作","f":"七言律诗","c":["一泓长湛镜中天，栏槛凭高得月先。","秪道省中持简牍，不知窗外有林泉。","幽篁拂座能蠲俗，老桧淩霜不记年。","谁信仙曹兼吏隐，诗成莫遣外人传。"]},{"t":"皇储恩例赐给二品诰命感忭有作 其一","f":"七言律诗","c":["赐诰新恩出帝阍，几回荣宠到私门。","锦鸾织处天章丽，犀轴颁时御墨温。","先世总看覃雨露，微生何以答乾坤。","百男万寿吾皇祝，夜礼星垣稽首言。"]},{"t":"皇储恩例赐给二品诰命感忭有作 其二","f":"七言律诗","c":["西蜀旬宣惟我祖，簪缨馀泽到诸孙。","琅函锦字尚书诰，秀水钤山世德门。","蓬舍尽堪容驷马，圭田元可荐蘋蘩。","四年两度逢恩庆，重见天光贲九原。"]},{"t":"腊日奉常穆公宅集会限韵","f":"七言律诗","c":["长安门馆凤池通，几许招寻令节同。","海内故交还骨肉，天涯萍迹漫西东。","鸾栖正借高冈树，鹏运宜抟碧海风。","圣主聪明过尧舜，欲于何地献愚忠。"]},{"t":"元日费林二翰长集饮","f":"七言律诗","c":["柏叶细传元日酒，相过喜是玉堂人。","他乡对客情偏洽，帝里逢春赏更新。","紫禁祥烟低拂柳，凤池细水欲含蘋。","年华物色看流輚，珍重尊前报主身。"]},{"t":"初岁于省中作","f":"五言古诗","c":["献岁开元祚，丽景耀神京。","彤庭祥雾合，钟山佳气盈。","天曹肃弘敞，巍阁峻且清。","北瞻鳷鹊观，东瞰凤凰城。","修庑俨槐柏，列署映瑶瑛。","虚薄蒙皇眷，缪此忝持衡。","跂昔繁名哲，一一惟国桢。","蟠木讵为用，华章忽滥婴。","本乏资世器，幸遭休运明。","萤光思向日，涔滴愧输瀛。","夙夜怀山甫，懿德诚可经。"]},{"t":"正月七日翰林诸寮于敝寓山池为瀛洲之会阄韵得七言近体二章 其一","f":"七言律诗","c":["人日邀宾共草堂，壑云岩石动辉光。","因攀梅蕊生诗兴，更藉椒花献寿觞。","天近凤池通雨露，气催莺谷转春阳。","高才尽是云霄望，薄劣惭随鹓鹭行。"]},{"t":"正月七日翰林诸寮于敝寓山池为瀛洲之会阄韵得七言近体二章 其二","f":"七言律诗","c":["客邸长安水竹居，能堪八座拥朝裾。","幔亭正启神仙宴，花径初停长者车。","幽洞驻云迷紫翠，碧池消雪漾清虚。","莫嫌菲薄无供给，留取新题石上书。"]},{"t":"元夜集宗伯甘泉公宅得五言体 其一","f":"五言律诗","c":["瑞雪南宫夜，华灯共此筵。","缝葩燃夕艳，琼絮舞春妍。","应节辛盘出，留欢柏酒传。","坐中皆郢曲，歌咏答韶年。"]},{"t":"元夜集宗伯甘泉公宅得五言体 其二","f":"五言律诗","c":["帝城春信早，春园趣不稀。","池烟凝竹色，庭雪助灯辉。","气煖浮兰醴，花寒落毳衣。","清言欢未极，玉漏转微微。"]},{"t":"灵谷寺 其一","f":"五言律诗","c":["莲宫青嶂合，松门石径通。","窈然深谷里，疑与秦人逢。","涧底藏馀雪，窗中列秀峰。","寂寞支公宅，惟闻朝暮钟。"]},{"t":"灵谷寺 其二","f":"五言律诗","c":["谷寺新春到，山深岚雾寒。","苍松立万壑，宝塔青云端。","不睹崇宫丽，那知法界宽。","夙有烟霞好，登临寄一欢。"]},{"t":"题顾中丞载酒亭图 其一","f":"七言绝句","c":["紫芝题墨千年胜，图向衡山赏更新。","万壑云松一茅屋，就中疑是草玄人。"]},{"t":"题顾中丞载酒亭图 其二","f":"七言绝句","c":["松坞高眠深闭关，清词白雪落人间。","我欲相从迷所适，却随芳草到春山。"]},{"t":"生日自述 其一","f":"七言律诗","c":["童稚萤囊抱一经，宦途奔逐鬓还星。","风云自幸逢明世，羸病那知介晚龄。","寒雪映岩松色定，早春当槛柳条青。","晨觞未许儿曹送，追忆劬劳涕暗零。"]},{"t":"生日自述 其二","f":"七言律诗","c":["五十五年初度日，他乡踪迹尚流萍。","关心万念悲身事，窃禄三朝愧宠灵。","晚盛冰霜恒自保，世途巇险故曾经。","迟回退食江湖远，省阁钟峰吟翠屏。"]},{"t":"观音岩同浚川王司马作 其一","f":"五言古诗","c":["久怀名山游，登赏春巳暮。","言寻紫芝约，颇适沧洲趣。","巉巉石抱城，泯泯江流雾。","憩涧挹飞泉，攀萝荫芳树。","临川足鱼鸟，揽泽多蘅荰。","兴发挥绿觞，浩歌谁与晤。","弱水隔烟涛，蓬瀛渺天路。","岂无乘鹤仙，云中自来去。","人世多嚣尘，流光草间露。","嘉会良足怡，转盻巳成故。","何当巢云松，脱迹葆贞素。"]},{"t":"观音岩同浚川王司马作 其二","f":"五言古诗","c":["皋林媚晴春，宛若绮绣错。","岷江汇洪波，九派悉输约。","仄叠万古矶，悬崖出飞阁。","崖中白衣士，趺坐澹虚泊。","祗苑遗俗氛，岩花自开落。","俯窥群象杳，仰视天宇阔。","昔贤几登临，异代不可作。","朅来奉佳游，转使吏情薄。","欲钓任公鳌，还梦坡仙鹤。","青山何寥寥，白石亦凿凿。","寄谢同心侣，且永今夕乐。"]},{"t":"西园赋赠徐六公子用陈侍讲韵","f":"七言律诗","c":["幽人宴息在林园，不信城闉车马繁。","镜里芙蓉临玉沼，烟中楼阁俯青原。","荒台凤去云俱寂，茂苑莺啼日自喧。","合有神仙来此地，时占紫气候前轩。"]},{"t":"暮春集鸡鸣山阁","f":"七言律诗","c":["胜侣携尊兴不违，春山高阁坐忘归。","浓烟密树深相映，丽日澄湖迥自辉。","清磬乍随仙梵远，异花时傍佛筵飞。","真从画里看京邑，更与攀萝上翠微。"]},{"t":"写真自题","f":"七言律诗","c":["湖海浮名山泽形，漫劳图史付丹青。","裴卿独笑非冰鉴，方朔虚疑是岁星。","事可告天惟自信，志期希古不遑宁。","华簪朱绂吾何意，乞取烟霞养性灵。"]},{"t":"送许仲贻赴举","f":"七言律诗","c":["高亭击剑酒杯深，极浦维舟风雪阴。","积水不堪连暮色，归鸿应是带春音。","云霄献纳升东观，泉石栖迟别故林。","共道孙弘工射策，莫令经术负初心。"]},{"t":"除夕作","f":"七言律诗","c":["杯湛灯明深客堂，促阴浮迹笑尘忙。","病来渐觉形容老，静后浑于岁月忘。","星斗逼檐知夜永，垄畦融雪丨年康。","朝衣细整听钟漏，正想氤氲汉殿香。"]},{"t":"元日作","f":"七言律诗","c":["客居钟阜三移岁，官阁梅花暖自芬。","欲试綵毫诗每就，重斟柏叶酒初醺。","春城万户催箫鼓，霁景千峰映雪云。","窃禄自惭无寸补，圣朝功德冠华勋。"]},{"t":"元日罗子印冈以诗见寄次韵答之","f":"七言律诗","c":["正元天气兆和丰，旭日卿云瑞霭同。","缇室启春回物候，玉书颁泽起疲癃。","侵阶细草痕微绿，裛露仙桃萼渐红。","却爱巢由歌帝力，康衢新咏寄南宫。"]},{"t":"岁初视篆呈潘公寅长","f":"五言律诗","c":["涤篆池冰暖，开堂雪树青。","春光动八极，休气协三灵。","北阙垂恩露，南宫聚德星。","同志欣寮寀，摅忠报帝庭。"]},{"t":"新年乡会","f":"五言律诗","c":["扬历群公在，吾乡不乏贤。","盍簪逢帝里，投辖启春筵。","柏叶随樽细，梅花斗胜妍。","留欢非易得，四海是尧年。"]},{"t":"人日宋中丞宴集","f":"五言律诗","c":["此日逢人好，邀宾荷主贤。","台霜凝画戟，庭柏近芳筵。","雪拥千门曙，春增万象妍。","曾同杏园宴，相对惜华年。"]},{"t":"侯中丞宴集","f":"五言律诗","c":["中丞今峻望，南国尽称贤。","楚水移家久，霜台共此筵。","饮高觞令促，坐久烛花妍。","蓬质惭难并，青松耐岁年。"]},{"t":"和侯中丞元夜喜晴","f":"七言律诗","c":["九衢华月霁灯宵，帝里韶年景自饶。","吴地歌声传子夜，汉家楼阁入烟霄。","三阳淑气迎黄道，四海仁风乐圣朝。","正喜中台布时令，尽看南亩事春苗。"]},{"t":"和顾中丞出息东郊田舍二首 其一","f":"五言古诗","c":["息驾追夙游，艺畴戒春作。","缫茧巳眠蚕，探鷇忽成鹊。","林英纷委地，柰此风雨恶。","芊绵原隰引，联络沟塍错。","叠石群岫移，诛茆数椽缚。","宁希金悬肘，赖有田负郭。","灿灿霞冠岑，涓涓泉赴壑。","雊雉当坐隅，嗥犬出丛薄。","床横元亮琴，架贮韩康药。","雅志璞仍怀，浮荣屣应脱。","岂异子云居，草玄甘寂寞。"]},{"t":"和顾中丞出息东郊田舍二首 其二","f":"五言古诗","c":["清旦漱玉齿，焚香讽道书。","朗吟百神卫，万遍袪灾虞。","至人昔有语，上智乃如愚。","谷虚神以存，累遣体应舒。","大隐在城市，岂必侣樵渔。","林卧观众芳，水木及春馀。","青阳忽巳暮，不乐复何如。","览镜彫朱颜，发白不满梳。","兴来理瑶瑟，且复对浮蛆。","诵君东郊作，吾亦赋归欤。"]},{"t":"生日效长庆体是岁予窃禄留曹三载矣","f":"七言律诗","c":["年过半百仍加六，贪恋清时未拂衣。","朱绂拖身官秩贵，青云屈指故交稀。","游鱼在藻恩诚渥，病鹤乘轩分却非。","待得铨曹书满日，只应便扫故园扉。"]},{"t":"江阁春眺","f":"七言律诗","c":["冉冉松云开阁扉，冥冥烟浪绕亭矶。","秾花锦石春能丽，禅径香台赏未稀。","鸥鹭不惊尘事远，江山无改昔人非。","蘼芜千里汀洲晚，怅望征帆带雨飞。"]},{"t":"观音山作 其一","f":"五言律诗","c":["山畔青莲宇，江间白鹭洲。","中天横积翠，百谷汇洪流。","俗远因成寂，林深易得秋。","谁能来月夕，吹笛起潜虬。"]},{"t":"观音山作 其二","f":"五言律诗","c":["千峰遥翠合，九派迅流奔。","积气浮潭浦，殊状变朝昏。","岩幽藏绮阁，萝悬翳石门。","叹逝徒延伫，悟寂与谁论。"]},{"t":"观音山作 其三","f":"五言律诗","c":["晨霁烟景豁，平流净如掌。","鱼鸟遂飞潜，舟舻相下上。","具美信难期，朋宴娱春赏。","何当风雨冥，来阅惊涛壮。"]},{"t":"金山寺登赋 其一","f":"五言律诗","c":["披云跻绝壑，搴萝憩石门。","上方孤磬发，令我澄心魂。","苔壁风烟古，龙湫雾雨昏。","摩藓铭难辨，开金迹尚存。"]},{"t":"金山寺登赋 其二","f":"五言律诗","c":["浴日鲸波迥，含风鹫岭孤。","春洲足烟雨，客思渺平芜。","天影遥连海，山形尽入吴。","复此弭兰楫，因悲芳岁徂。"]},{"t":"赠王翁野极","f":"七言律诗","c":["方袍鹤氅白纶巾，来往人间作至人。","借问碧桃今几发，东风一百九回春。","海上灵山那可寻，人间至药几时成。","翁能授我长生诀，便欲相随隐姓名。"]},{"t":"寻方伯张公合溪隐居","f":"五言律诗","c":["激濑交文渚，列树间平畴。","双涧缅回合，中隐林庐幽。","结驷台省别，巾车山泽游。","停云思弥积，伐木意相求。"]},{"t":"憩舟九石潭下同合溪方伯登张侯庙有作张侯者南唐时将有功封侯方伯之远祖也 其一","f":"五言律诗","c":["灵峰开峻宇，危磴俯澄湾。","鸟道风烟上，停舻得共攀。","山春谷彩媚，天迥水容閒。","知有仙人过，吟留双树间。"]},{"t":"憩舟九石潭下同合溪方伯登张侯庙有作张侯者南唐时将有功封侯方伯之远祖也 其二","f":"五言律诗","c":["山隐张侯庙，洲传九石潭。","碧溪环岛屿，高栋锁烟岚。","灵旆风云拥，神舆虎豹骖。","千秋春明祀，遗泽在江南。"]},{"t":"行经傍罗江怀寄黄费二太史","f":"五言古诗","c":["沿溯多异状，九潭清我心。","岩松冠朝旭，河柳变时禽。","霞烂初成绮，溜远忽鸣琴。","知有玄豹隐，求之云雾深。","冲怀结悃素，一寄瑶华音。"]},{"t":"暮春广陵往观宗伯湛公甘泉山精舍马赵二户曹携酒至同酌 其一","f":"五言律诗","c":["地以高贤胜，春逢淑景和。","爱山因独往，载酒得同过。","周览乾坤大，幽寻水石多。","咏归堪自乐，鸣鸟亦成歌。"]},{"t":"暮春广陵往观宗伯湛公甘泉山精舍马赵二户曹携酒至同酌 其二","f":"五言律诗","c":["岳麓名非忝，龟山道可宗。","堂轩开峻构，剑履寄高踪。","坛杏有千岁，江花能百重。","尘缨如可脱，吾意会相从。"]}]};